  `fluency_promotion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '流利度改进',
  `general_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '一般建议',
  `self_left_x_data` json NULL COMMENT '用户左脚X轴数据',
  `self_left_y_data` json NULL COMMENT '用户左脚Y轴数据',
  `self_right_x_data` json NULL COMMENT '用户右脚X轴数据',
  `self_right_y_data` json NULL COMMENT '用户右脚Y轴数据',
