INSERT INTO `ai_analysis_result` VALUES (314, 87.8, 89.5, 88.2, 86.3, '在第10秒至第20秒期间，动作的稳定性稍有波动。建议在此时间段内加强腿部力量训练，提高控制力。', '从第25秒到第30秒，动作与标准样本存在较大偏差。建议多进行右脚单踢-脚内侧踢球的基本功练习，特别是注意脚内侧触球的角度和力度。', '整体流畅性较好，但在第15秒至第20秒的动作转换过程中出现轻微卡顿。建议通过慢速重复练习，逐步加快速度，以提升动作转换的平滑度。', '总体来看，动作较为规范，但仍有提升空间。建议在日常训练中增加腿部柔韧性和力量训练，并且注重动作细节的把握，特别是在关键的时间点上，如第10秒、第15秒和第25秒等处。', '[142, 53, 57, 50, 36, 18, 9, 0, 25, 36, 55, 65, 70, 72, 71, 73, 75, 74, 74, 61, 54, 37, 24, 24, -7, -4, 27, 20, 35, 56, 63, 67, 70, 66, 72, 71, 75, 76, 75, 65, 56, 44, 37, 37, 6, 4, -8, 11, 20, 48, 66, 75, 77, 63, 60, 68, 62, 61, 60, 64, 68, 65, 58, 56, 49, 8, 3, 4, 32, 51, 66, 67, 68, 60, 64, 73, 75, 79, 76, 65, 65, 60, 56, 50, 48, 46, 5, 11, -17, -16, 7, 38, 57, 69, 74, 71, 69, 66, 74, 78, 69, 61, 56, 33, 21, 7, -9, -10, 2, 14, 41, 62, 71, 79, 71, 76, 77, 83, 74, 66, 49, 37, 16, -3, -1, 2, 13, 49, 62, 65, 66, 71, 66, 71, 71, 67, 70, 68, 58, 56, 49, 42, 34, 12, 1, 10, 8, 1, 31, 55, 66, 79, 83, 87, 77, 78, 76, 79, 77, 68, 60, 49, 48, 28, 10, 1, -12, 15, 45, 59, 76, 66, 65, 68, 66, 72, 71, 72, 70, 71, 57, 50, 32, 24, 14, 13, 5, -6, -7, 14, 43, 66, 75, 78, 69, 66, 67, 69, 72, 75, 69, 60, 51, 41, 9, 6, 40, 25, -19, -3, 23, 31, 60, 72, 68, 73, 72, 75, 72, 67, 57, 44, 17, 27, 2, 8, 32, 35, 52, 63, 64, 69, 66, 62, 66, 59, 71, 70, 66, 65, 56, 55, 36, 35, 7, -14, -6, 18, 34, 59, 72, 79, 76, 79, 79, 79, 84, 80, 76, 74, 63, 49, 43, 39, 17, -3, -23, -1, 15, 50, 60, 70, 77, 75, 71, 71, 76, 75, 73, 59, 49, 50, 53, 31, 14, -10, -3, 20, 50, 61, 68, 76, 73, 68, 65, 74, 60, 78, 65, 59, 56, 49, 38, 20, 24, -5, 13, 32, 48, 47, 67, 72, 70, 71, 67, 72, 60, 60, 74, 65, 60, 56, 38, 51, -1, -1, 3, 2, 25, 48, 58, 60, 61, 65, 75, 75, 80, 79, 82, 80, 68, 61, 58, 39, 18, 10, -7, -4, -12, 1, 33, 57, 69, 75, 73, 78, 81, 76, 78, 81, 75, 68, 52, 37, 15, -8, -16, -20, -3, 15, 38, 53, 56, 69, 78, 79, 76, 78, 75, 63, 46, 22, 13, -7, -16, -20, -1, 7, 33, 58, 73, 69, 86, 82, 83, 87, 85, 79, 68, 47, 29, 13, 1, -11, -5, -8, -13, -9, 13, 50, 66, 79, 85, 84, 84, 84, 8