INSERT INTO `ai_analysis_result` VALUES (475, 96, 95, 96, 97, '在第3秒和第7秒时，左脚支撑点出现轻微晃动，建议通过加强核心稳定性训练减少身体摆动幅度，例如加入单脚平衡练习。', '踢球瞬间的左脚高度与标准动作对比稍显不足，建议强化腿部肌肉发力控制，在第4秒至第6秒增加踝关节爆发力训练。', '整体动作流畅性较好，但在第8秒过渡回位阶段略显僵硬，可通过增加柔韧性拉伸和连续盘踢衔接练习改善。', '建议结合慢动作视频反馈纠正细节问题，并通过模拟实战环境提高动作自然度，同时定期复盘以监测改进效果。', '[-50, -34, -31, -28, -29, -29, -25, -24, -17, -18, -13, -13, -11, -13, -12, -8, -9, -8, -10, -11, -13, -15, -18, -14, -20, -23, -29, -33, -43, -55, -62, -65, -64, -58, -58, -55, -51, -42, -30, -22, -17, -12, -18, -17, -17, -19, -24, -30, -40, -53, -66, -65, -83, -81, -73, -75, -69, -62, -55, -48, -38, -29, -24, -21, -20, -19, -20, -20, -30, -39, -62, -90, -106, -114, -119, -116, -118, -114, -105, -99, -82, -69, -56, -42, -30, -23, -21, -20, -21, -24, -32, -46, -70, -91, -110, -122, -126, -129, -114, -104, -99, -102, -86, -64, -46, -28, -23, 0, 5, 3, 2, -1, -3, -4, -9, -15, -19, -40, -43, -53, -63, -76, -77, -75, -39, -70, -64, -55, -44, -39, -31, -26, -13, -9, -3, 0, -1, 0, -3, -17, -27, -35, -52, -62, -76, -83, -90, -81, -65, -76, -59, -58, -48, -38, -31, -19, -9, 3, 4, 5, 6, 2, -4, -11, -21, -28, -44, -54, -62, -71, -83, -79, -76, -69, -59, -52, -40, -33, -22, -9, -2, 0, 1, 0, -1, -4, -13, -11, -19, -22, -26, -34, -44, -49, -45, -43, -22, -20, -20, -18, -15, -10, -4, 1, 6, 7, 6, 1, 3, 1, 1, -2, -3, -12, -25, -46, -68, -85, -96, -104, -100, -91, -89, -80, -72, -61, -49, -37, -27, -20, -17, -12, -13, -13, -22, -44, -65, -98, -121, -141, -130, -130, -121, -119, -108, -99, -96, -80, -62, -44, -28, -21, -20, -20, -15, -17, -12, -15, -16, -19, -17, -17, -21, -24, -27, -28, -34, -38, -42, -48, -55, -61, -68, -68, -67, -58, -50, -35, -19, -6, 7, 16, 26, 27, 27, 23, 21, 24, 24, 22, 22, 21, 19]', '[291, 194, 194, 194, 193, 191, 188, 186, 181, 180, 177, 175, 174, 172, 174, 176, 177, 179, 181, 182, 182, 182, 180, 175, 174, 172, 162, 155, 146, 128, 108, 88, 74, 73, 86, 105, 125, 151, 167, 177, 183, 183, 186, 187, 184, 181, 173, 163, 155, 144, 131, 106, 71, 70, 72, 81, 108, 125, 148, 179, 189, 191, 