INSERT INTO `ai_analysis_result` VALUES (481, 95.72, 95.32, 94.65, 97.18, '在第3秒至第4秒间，左脚动作的稳定性略有波动，建议加强核心肌群的控制训练以减少摆动幅度。', '右脚在第6秒附近踢球高度略低于标准，可通过调整膝关节发力角度提升精准度。', '第8秒时左右脚交替衔接稍显生硬，建议增加髋关节柔韧性练习以优化动作过渡的流畅性。', '整体表现接近标准动作，但需注意第3秒和第8秒的动作衔接细节。可通过重复慢速分解练习强化肌肉记忆，同时结合视频回放进行自我纠正。', '[10, 7, 6, 11, 11, 10, 10, 14, 14, 16, 15, 15, 13, 13, 10, 9, 9, 7, 4, 5, 7, 9, 9, 6, 7, 4, 9, 12, 14, 6, 4, 4, 5, 7, 7, 9, 8, 12, 10, 14, 16, 18, 23, 20, 18, 17, 17, 9, 14, 11, 11, 15, 12, 12, 10, 5, 2, -1, -4, -4, 6, 8, 8, 21, 25, 30, 30, 23, 18, 12, 15, 1, 3, 6, 10, 14, 15, 16, 19, 23, 26, 24, 29, 27, 25, 23, 21, 21, 19, 18, 15, 11, 12, 12, 9, 5, 5, 11, 16, 18, 22, 18, 17, 19, 20, 16, 14, 12, 7, 5, 7, 7, 9, 11, 14, 15, 14, 15, 17, 14, 18, 20, 23, 20, 18, 14, 18, 17, 16, 15, 18, 18, 13, 2, -8, -19, -27, -21, -17, -9, -6, -1, 3, 6, 5, 9, 11, 13, 15, 17, 28, 30, 36, 38, 38, 37, 29, 11, 11, 21, 11, 16, 18, 18, 15, 15, 10, 11, 9, 0, 0, -3, 0, 5, 6, 10, 11, 17, 20, 16, 9, 4, 3, 4, 2, 2, 5, 6, 10, 9, 13, 14, 15, 14, 13, 12, 8, 8, 4, 8, 10, 11, 11, 11, 6, 5, 3, -5, -4, -9, -10, -10, -10, -7, -7, -4, 0, 2, 2, 3, 2, 1, 1, 0, 0, -3, 6, 1, 2, 1, 2, 3, 2, 1, 3, 2, 3, 9, 10, 11, 11, 12, 12, 12, 10, 9, 8, 8, 6, 6, 5, 6, 6, 7, 6]', '[191, 127, 131, 131, 129, 129, 132, 131, 130, 133, 131, 130, 133, 134, 133, 139, 138, 135, 130, 124, 119, 122, 128, 131, 130, 122, 121, 103, 109, 119, 129, 137, 141, 143, 142, 147, 147, 146, 145, 141, 137, 135, 137, 140, 143, 140, 135, 146, 141, 143, 147, 149, 148, 148, 135, 148, 147, 146, 144, 146, 153, 153, 160, 155, 147, 136, 146, 141, 148, 151, 150, 145, 145, 143, 148, 149, 142, 145, 151, 151, 151, 141, 139, 147, 145, 144, 148, 152, 150, 149, 144, 141, 141, 144, 138, 144, 147, 148, 148, 150, 150, 149, 138, 121, 141, 148, 144, 151, 154, 151, 150, 145, 143, 140, 139, 139, 137, 138, 142, 148, 143, 140, 137, 140, 142, 147, 146, 147, 148, 147, 140, 141, 127, 128, 137, 109, 91, 123, 127, 135, 137, 143, 144, 145, 140, 140, 138, 137, 141, 140, 135, 141, 148, 144, 142, 136, 116, 108, 12