INSERT INTO `ai_analysis_result` VALUES (491, 96.2, 95.2, 96.1, 97.3, '在第4秒至第6秒间，右腿摆动幅度稍显不稳定，可通过加强核心肌群力量训练提升整体稳定性。', '踢球瞬间脚背触球点略有偏差，建议通过慢动作练习强化击球时的精准度控制。', '从第8秒开始出现轻微停顿感，推荐增加连续多组盘踢练习以提高动作衔接流畅性。', '综合来看表现优秀，但需注意避免发力过猛导致身体失衡；同时建议加入节奏感训练，例如配合音乐完成动作，进一步优化自然协调性。', '[6, 4, 4, 4, 4, 4, 7, 7, 7, 7, 7, 6, 6, 6, 5, 5, 5, 6, 6, 6, 6, 8, 10, 10, 10, 10, 9, 9, 9, 9, 9, 9, 9, 10, 12, 13, 13, 13, 11, 10, 2, -5, -11, -14, -19, -18, -17, -16, -11, -10, -9, -14, -11, -10, -9, -4, -4, -3, 1, 1, 0, 1, 2, 1, 1, 0, -1, -4, -5, -7, -5, -10, -12, -14, -15, -19, -18, -16, -15, -17, -16, -19, -22, -21, -21, -14, -11, -10, -6, -5, 0, 5, 7, 6, 6, 6, 8, 12, 14, 15, 7, -2, -14, -27, -39, -45, -51, -53, -51, -50, -34, -27, -13, -2, 5, 8, 4, 1, 0, 0, 0, -1, 0, 0, 1, 0, 1, 6, 8, 8, 2, 5, 0, 3, 3, 2, 1, -1, -1, 0, 1, 0, 0, 1, 1, 1, -2, -1, -3, -7, -9, -10, -14, -13, -9, -7, -7, -2, 2, 1, 2, 1, 1, 1, 1, 2, 1, -1, 2, 2, 1, 4, 5, 7, 5, 4, 0, 1, 1, 0, -1, -1, -1, -3, -4, -3, -3, 1, 2, 3, 4, 10, 18, 19, 21, 17, 13, 10, 1, -4, -7, -7, -4, -5, -6, -7, -8, -17, -3, 1, 14, 37, 47, 43, 32, -4, -7, -13, -19, -14, -11, -9, -11, -9, -13, -18, -17, -12, 7, 33, 47, 52, 50, 42, 31, 8, -11, -15, -17, -14, -12, -9, -5, -8, -10, -11, -7, -1, 6, 14, 15, 11, 5, -4, -7, -12, -10, -11, -11, -12, -12, -12, -9, 2, 14, 24, 33, 31, 25, 8, 7, 4, -1, -6, -8, -8, -9, -6, -4, -4, -1, -1, 2, 2, 2, 1, 3, 1, 1, 1, 2, 3, 1, 3, 4, 2, 2, 3, 3, 3, 3, 3, 3, 3, 4, 3, 3, 5, 6, 6, 7, 6, 6, 7, 6, 6, 6, 6, 6, 5, 5, 5, 5]', '[168, 112, 112, 112, 112, 112, 111, 111, 111, 110, 110, 113, 113, 113, 113, 113, 114, 114, 113, 113, 113, 114, 114, 113, 113, 112, 112, 112, 112, 113, 113, 113, 112, 113, 113, 113, 112, 111, 113, 114, 117, 119, 119, 119, 118, 120, 121, 120, 121, 121, 119, 114, 111, 108, 105, 108, 105, 102, 103, 100, 99, 98, 98, 98, 99, 99, 99, 100, 99, 99, 104, 97, 96, 98, 99, 90, 89, 88, 93, 94, 93, 86, 84, 72, 75, 88, 90, 94, 97, 105, 105, 101, 103, 103, 102, 102, 102, 103, 95, 95, 93, 97, 93, 89, 88, 89, 79, 75, 76, 81, 92, 96, 100, 96