INSERT INTO `ai_analysis_result` VALUES (509, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '右脚单踢-脚外侧踢球', '/files/2025/05/0dcc242736bf456a82a93074037f5195.mp4', 'f4bb907a-2716-43bd-b465-fe0dd9656e89', '进行中', '2025-05-23 23:16:54', '2025-05-23 23:16:54', 1, 1, b'0');
INSERT INTO `ai_analysis_result` VALUES (510, 68.5, 72.5, 65, 68, '在第3秒至第4秒期间，左脚摆动幅度波动较大，建议加强核心肌群稳定性训练，例如通过单腿平衡练习增强支撑能力。', '左脚踢球时的回摆轨迹与标准动作偏差明显，特别是在第6秒附近，需强化对毽球击打点的精准控制，可通过慢速分解动作练习改善。', '动作流畅性不足体现在第2秒和第5秒的衔接阶段，腿部回位速度较慢，建议增加髋关节灵活性训练并结合动态拉伸提升动作连贯性。', '整体动作需注重节奏感，尤其是在第2秒至第5秒的过渡期，通过模拟实战环境练习盘踢动作以提高自然度。此外，可加入弹力带辅助训练来优化腿部力量分配，确保动作更符合生物力学要求。', '[-58, -87, -96, -102, -102, -109, -101, -91, -83, -68, -47, -21, 3, 12, 15, 19, 15, -2, -22, -47, -80, -103, -119, -129, -130, -113, -102, -90, -86, -81, -69, -52, -40, -22, -12, -2, -6, -10, -12, -15, -18, -21, -22, -18, -19, -21, -21, -18, -24, -27, -43, -42, -38, -42, -43, -45, -44, -47, -42, -35, -31, -27, -30, -30, -30, -34, -39, -41, -42, -33, -28, -13, -6, 2, -2, -4, -8, -10, -12, -19, -22, -26, -28, -18, -11, -17, -17, -16, -19, -25, -32, -44, -52, -63, -48, -42, -39, -40, -31, -21, -7, 7, 19, 19, 20, 21, 18, 17, 12, 11, 8, -8, -32, -53, -72, -81, -97, -98, -83, -72, -62, -56, -55, -43, -31, -23, -19, -18, -20, -21, -24, -23, -19, -21, -13, -16, -18, -16, -20, -24, -25, -31, -33, -32, -23, -6, 14, 28, 25, 26, 14, -2, -31, -54, -82, -98, -107, -105, -100, -89, -84, -74, -66, -48, -32, -17, -5, -6, 0, -11, -14, -20, -23, -20, -25, -27, -24, -34, -43, -43, -39, -35, -35, -33, -30, -25, -18, -14, -3, 0, -4, -17, -41, -84, -136, -175, -172, -143, -101, -78, -50, -59, -32, -35, -30, -24, -20, -13, -16, -10, -8, -11, 1, 12, 16, 27, 37, 25, 33, 44, 39, 23]', '[107, 160, 137, 122, 111, 99, 94, 95, 113, 130, 159, 190, 203, 205, 209, 212, 205, 201, 197, 195, 185, 167, 131, 96, 55, 44, 38, 42, 61, 98, 130, 155, 176, 211, 205, 199, 194, 199, 201, 203, 204, 203, 200, 195, 201, 205, 211, 204, 204, 189, 162, 134, 111, 98, 100, 116, 137, 154, 168, 175, 193, 207, 208, 207, 214, 214, 208, 206, 209, 202, 198, 187, 178, 175, 139, 117, 111, 100, 119, 135, 156, 170, 194, 214, 210, 208, 207, 209, 204, 202, 194, 173, 137, 115, 80, 73, 93, 115, 135, 161, 196, 203, 199, 197, 197, 202, 204, 203, 199, 194, 194, 195, 194, 187, 165, 137, 120, 98, 84, 82, 9