INSERT INTO `ai_analysis_result` VALUES (519, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '右脚单踢-脚外侧踢球', '/files/2025/05/f54dd8b1e9ac42bd81cd10bcb1d87b47.mp4', '1dc59442-e195-48c1-87db-7edcbf8d2583', '进行中', '2025-05-23 23:36:21', '2025-05-23 23:36:21', 1, 1, b'0');
INSERT INTO `ai_analysis_result` VALUES (520, 82.07, 85.5, 82.4, 78.3, '在第3秒至第5秒间，支撑脚的摆动幅度偏大，建议加强核心肌群稳定性训练，例如通过单脚站立配合轻微摆腿练习提高平衡能力。', '击球动作的轨迹与标准动作偏差较大，特别是在第6秒时踢击点高度偏低，需强化右脚外侧击球时腿部延展的精准控制，并增加模拟击球分解动作重复练习。', '动作衔接存在停顿现象，尤其是在第4秒和第7秒附近，可通过慢速完整动作演练结合节奏感训练提升整体流畅性。', '建议结合毽球技术训练中的‘三步法’进行调整，前两步用于稳定身体重心，最后一步专注于击球发力；同时记录每次练习视频对比分析改进效果。', '[-17, -34, -31, -29, -26, -27, -26, -21, -20, -19, -16, -12, -12, -10, -9, -9, -9, -13, -13, -12, -14, -20, -24, -35, -42, -53, -60, -62, -58, -57, -53, -43, -29, -23, -17, -10, -9, -11, -18, -30, -39, -54, -67, -84, -82, -80, -81, -62, -54, -47, -37, -24, -21, -22, -20, -21, -30, -39, -60, -106, -117, -124, -121, -114, -108, -100, -88, -56, -41, -28, -23, -21, -24, -26, -35, -73, -93, -109, -124, -131, -122, -108, -96, -92, -66, -45, -29, -1, 3, 2, 2, -4, -5, -10, -17, -39, -44, -55, -62, -73, -72, -66, -74, -58, -48, -42, -36, -12, -8, -2, 0, -1, -8, -18, -29, -57, -69, -77, -88, -59, -78, -81, -67, -50, -42, -27, -22, -1, 2, 7, 5, -8, -13, -23, -32, -58, -65, -79, -80, -76, -73, -58, -52, -40, -23, -14, -6, -3, -5, -6, -7, -17, -22, -28, -29, -39, -48, -48, -48, -24, -19, -16, -22, -7, -1, 5, 5, 5, 5, 5, 0, -2, -12, -24, -45, -83, -98, -102, -104, -86, -83, -73, -61, -38, -26, -20, -16, -14, -13, -23, -40, -94, -118, -140, -137, -125, -119, -115, -105, -80, -61, -45, -27, -15, -17, -16, -19, -19, -20, -20, -22, -25, -23, -28, -28, -38, -41, -47, -55, -65, -71, -67, -57, -34, -20, -6, 5, 25, 27, 27, 21, 18, 18, 21, 20, 19]', '[97, 189, 189, 189, 189, 187, 187, 184, 180, 176, 175, 170, 169, 171, 172, 175, 178, 179, 178, 176, 173, 172, 166, 152, 142, 125, 104, 68, 67, 80, 98, 146, 163, 174, 177, 177, 177, 173, 177, 160, 151, 139, 134, 68, 62, 54, 86, 124, 144, 174, 185, 186, 188, 187, 188, 178, 172, 160, 156, 139, 113, 87, 67, 67, 85, 114, 137, 174, 177, 182, 182, 181, 181, 175, 166, 151, 138, 125, 105, 50, 34, 36, 48, 77, 106, 130, 151, 180, 184, 187, 187, 187, 183, 176, 168, 156, 144, 132, 116, 51, 34, 31, 47, 100, 120, 139, 151, 162, 170,