INSERT INTO `ai_analysis_result` VALUES (589, 90.25, 89.5, 88.75, 91, '在第3秒至第4秒间，摆动幅度略大，建议加强核心肌群的控制力训练以提升腿部动作稳定性。', '踢球时右腿外展角度稍显不足，特别是在第6秒附近，应着重练习髋关节灵活性及外展力量。', '第7秒至第8秒间的过渡存在轻微卡顿，可通过增加连贯性模拟训练改善动作流畅性。', '整体动作完成较好，但需在第3秒至第8秒内加强对支撑腿稳定性的把控，同时强化主力腿的摆动与击球节奏配合。', '[-50, -30, -28, -25, -27, -25, -23, -22, -15, -16, -12, -11, -10, -12, -11, -9, -8, -8, -9, -10, -12, -14, -16, -13, -18, -20, -26, -30, -38, -49, -55, -58, -57, -52, -51, -49, -45, -37, -27, -21, -15, -10, -15, -15, -15, -17, -21, -27, -35, -48, -58, -65, -74, -72, -64, -67, -62, -56, -50, -43, -34, -26, -21, -18, -17, -17, -18, -18, -26, -35, -55, -80, -94, -101, -106, -104, -105, -101, -93, -89, -74, -62, -49, -37, -26, -20, -18, -18, -18, -22, -29, -41, -62, -81, -97, -108, -112, -114, -101, -93, -85, -91, -76, -57, -41, -25, -20, -1, 4, 2, 2, -1, -2, -4, -8, -13, -16, -35, -38, -47, -56, -67, -68, -66, -33, -63, -56, -49, -39, -35, -28, -23, -11, -8, -2, 0, -1, 0, -3, -15, -24, -30, -46, -59, -67, -73, -80, -69, -56, -67, -50, -52, -42, -35, -28, -18, -8, 3, 4, 5, 5, 1, -4, -10, -18, -25, -39, -49, -55, -63, -73, -71, -68, -60, -52, -45, -36, -30, -19, -8, -1, 1, 1, 0, -2, -4, -11, -10, -16, -20, -23, -30, -40, -42, -40, -36, -20, -18, -16, -16, -15, -8, -5, 1, 5, 6, 5, 4, 2, 1, 1, -1, -3, -10, -22, -41, -61, -76, -85, -91, -89, -81, -79, -71, -64, -55, -44, -33, -24, -18, -15, -10, -11, -12, -20, -39, -58, -87, -108, -125, -116, -116, -107, -107, -97, -88, -86, -71, -54, -40, -25, -19, -18, -18, -13, -15, -11, -13, -14, -17, -16, -16, -15, -21, -24, -24, -31, -34, -38, -43, -49, -52, -61, -61, -59, -51, -44, -30, -17, -6, 6, 14, 22, 24, 23, 20, 19, 22, 21, 20, 19, 18, 17]', '[291, 172, 172, 172, 171, 170, 167, 164, 162, 160, 157, 154, 155, 153, 154, 155, 157, 159, 160, 162, 162, 162, 160, 156, 155, 153, 145, 137, 130, 114, 96, 79, 67, 64, 77, 94, 110, 135, 148, 158, 163, 162, 165, 166, 163, 161, 154, 144, 137, 128, 117, 96, 63, 62, 64, 72, 95, 111, 132, 159, 168, 169, 169, 170, 170, 170, 171, 160, 153, 143