INSERT INTO `ai_analysis_result` VALUES (590, 89.5, 88.5, 89.75, 90.25, '在第3-4秒和第6-7秒内，左脚的摆动幅度出现轻微不稳定，建议强化核心肌群力量以增强动作稳定性，尤其是在脚背踢球时注意髋关节的控制。', '左右脚踢球的高度变化与标准动作存在一定偏差，特别是在第10-12秒，踢球点高度偏低，建议加强脚背击球瞬间腿部伸展的精准性训练。', '动作衔接流畅性整体良好，但在第15-16秒右脚回收速度略显迟缓，影响连贯性，建议通过增加踝关节灵活性训练来提升动作切换的自然度。', '整体动作较为规范，但需注意在第3秒和第16秒附近踢球过程中腿部摆动轨迹的一致性。可通过慢动作回放分析并调整踢球角度，同时结合多组分解练习提高动作完整性。', '[10, 5, 5, 7, 7, 7, 7, 9, 10, 11, 10, 10, 8, 9, 8, 6, 6, 5, 3, 3, 5, 5, 6, 5, 1, 3, 6, 7, 9, 4, 3, 2, 4, 4, 5, 6, 6, 8, 8, 9, 10, 12, 16, 13, 12, 12, 11, 6, 10, 7, 8, 10, 7, 7, 7, 4, 2, -1, -3, -2, 4, 5, 6, 13, 17, 20, 20, 15, 12, 8, 10, 3, 2, 3, 6, 9, 10, 11, 13, 15, 18, 16, 19, 18, 16, 15, 14, 14, 13, 12, 10, 7, 9, 8, 6, 3, 3, 7, 9, 11, 15, 12, 11, 12, 14, 11, 9, 8, 5, 3, 5, 4, 6, 7, 9, 9, 10, 10, 12, 9, 12, 14, 15, 13, 12, 10, 12, 12, 11, 10, 12, 12, 9, 2, -5, -13, -19, -15, -12, -6, -5, -1, 2, 4, 3, 5, 8, 8, 10, 11, 19, 21, 24, 25, 25, 25, 20, 7, 6, 15, 8, 10, 12, 12, 10, 10, 7, 8, 6, 1, 0, -2, 0, 4, 4, 6, 7, 12, 13, 11, 6, 3, 2, 2, 2, 1, 3, 4, 6, 6, 9, 10, 10, 9, 9, 8, 5, 5, 3, 5, 7, 7, 7, 7, 7, 4, 2, -3, -3, -5, -6, -6, -7, -4, -4, -2, -1, 1, 1, 2, 1, 1, 0, 0, 0, -1, 4, 1, 1, 1, 1, 1, 1, 1, 3, 1, 2, 6, 7, 7, 8, 8, 8, 8, 7, 6, 6, 6, 5, 5, 4, 4, 5, 5, 5]', '[191, 84, 86, 87, 85, 87, 88, 88, 87, 88, 87, 86, 88, 89, 89, 93, 92, 90, 86, 83, 79, 81, 85, 87, 89, 81, 81, 69, 72, 79, 86, 91, 94, 95, 94, 98, 97, 97, 97, 95, 91, 89, 91, 94, 96, 94, 90, 98, 93, 96, 98, 99, 100, 99, 89, 98, 98, 98, 96, 97, 102, 102, 108, 103, 97, 90, 97, 93, 98, 100, 100, 102, 97, 96, 99, 99, 93, 97, 101, 100, 100, 94, 93, 97, 97, 95, 99, 101, 101, 99, 96, 94, 94, 96, 92, 96, 97, 99, 99, 100, 101, 100, 92, 81, 95, 99, 95, 100, 103, 100, 101, 97, 95, 94, 93, 93, 91, 92, 94, 99, 96, 92, 91, 94, 95, 98, 98, 98, 99, 98, 93, 93, 84, 85, 90, 73, 59, 81, 85, 90, 91, 95, 95, 96, 93, 94, 92, 92, 93, 93, 90, 94, 99, 95, 95, 91, 76, 72, 87, 64, 89, 95, 97, 105, 103, 99, 102, 98, 95, 94, 90, 90, 92, 94, 91, 93, 92, 90, 87, 89, 92, 102, 102, 101, 101,