INSERT INTO `ai_analysis_result` VALUES (599, 82.28, 85.23, 82.17, 79.45, '在第3秒至第5秒期间，支撑脚的摆动幅度存在轻微不稳现象，建议加强核心肌群训练以提升动作稳定性。', '踢球腿的轨迹与标准动作相比稍显偏移，特别是在第7秒左右，建议针对脚外侧触球点进行专项练习，提高精准度。', '动作连贯性在第6秒和第8秒之间出现短暂停顿，建议通过慢动作分解练习改善腿部摆动的流畅性。', '整体动作较为接近标准，但需注重细节优化。建议增加单脚支撑平衡训练、模拟盘踢低强度重复练习，并结合视频回放自我纠正动作偏差。', '[-50, -23, -21, -21, -20, -18, -18, -16, -15, -12, -9, -8, -8, -9, -8, -6, -6, -6, -6, -7, -9, -10, -11, -10, -13, -15, -19, -22, -28, -37, -42, -44, -43, -39, -38, -37, -34, -28, -20, -15, -11, -7, -12, -11, -11, -13, -16, -21, -26, -36, -44, -43, -56, -54, -48, -50, -46, -42, -37, -33, -25, -19, -16, -14, -13, -12, -14, -14, -20, -26, -41, -60, -71, -76, -80, -78, -78, -75, -70, -66, -55, -47, -37, -28, -20, -15, -14, -13, -16, -16, -21, -31, -47, -60, -73, -82, -84, -85, -77, -70, -62, -68, -58, -43, -31, -19, -15, -1, 3, 2, 2, -1, -2, -3, -7, -10, -12, -26, -29, -36, -42, -50, -51, -50, -26, -45, -42, -36, -29, -26, -20, -18, -8, -6, -2, 0, -1, 0, -2, -11, -18, -24, -34, -44, -50, -55, -60, -53, -43, -51, -41, -40, -32, -26, -21, -14, -5, 2, 3, 3, 4, 1, -3, -7, -15, -21, -29, -37, -42, -48, -55, -53, -51, -45, -39, -34, -27, -22, -15, -6, -1, 0, 1, 0, -2, -3, -9, -8, -13, -16, -17, -23, -29, -33, -30, -28, -16, -13, -13, -12, -10, -6, -3, 0, 4, 4, 3, 0, 1, 1, 1, -1, -1, -8, -16, -31, -46, -57, -64, -70, -67, -61, -60, -54, -48, -41, -33, -25, -18, -13, -11, -8, -9, -9, -15, -30, -44, -64, -81, -94, -87, -87, -81, -80, -72, -66, -64, -53, -41, -30, -18, -15, -14, -14, -10, -11, -8, -11, -12, -12, -13, -12, -13, -16, -18, -19, -23, -26, -28, -33, -37, -40, -46, -46, -44, -39, -33, -23, -13, -4, 5, 10, 17, 18, 18, 15, 14, 17, 16, 16, 14, 13, 13]', '[291, 129, 129, 128, 128, 127, 125, 124, 121, 120, 118, 117, 116, 115, 116, 116, 117, 119, 120, 120, 122, 121, 119, 117, 116, 114, 109, 103, 97, 85, 72, 59, 50, 48, 57, 70, 83, 101, 111, 118, 122, 122, 125, 124, 123, 121, 116, 108, 103, 96, 88, 71, 47, 46, 48, 54, 71, 84, 99, 119, 126, 127, 126, 127, 128, 128, 128, 120, 115, 107, 10