INSERT INTO `ai_content_info` VALUES (944, 448, NULL, 'text', '看起来你可能是在请求查看原始运动数据的具体内容，但根据之前的指示，我们不应该直接展示原始数据，而是应该用“第几帧”来代替。如果你能告诉我具体想要分析哪一帧的数据，或者提供更多的上下文信息，我可以帮助你更好地理解该帧数据的稳定性。\n\n请告诉我你想要分析的具体帧数或提供更多背景信息。这样我们可以继续进行更深入的讨论。', 'ai', '2025-04-20 15:40:00', 1);
