INSERT INTO `ai_content_info` VALUES (1278, 627, NULL, 'text', '您的动作整体表现较好，但在第4秒和第6秒时，击球点精准度需提升，建议通过固定目标练习强化脚外侧踢球的准确性。第5秒到第7秒间出现卡顿，可尝试慢速盘踢练习增强连贯性。核心肌群控制不足导致第2秒至第3秒摆动较大，建议加强平板支撑与单腿平衡训练。同时，注意发力一致性与重心调整，以提升整体稳定性与流畅性。', 'ai', '2025-05-24 13:42:38', 1);
INSERT INTO `ai_content_info` VALUES (1279, 628, 517, 'card', NULL, 'user', '2025-05-24 13:50:58', 1);
