INSERT INTO `ai_content_info` VALUES (1287, 630, NULL, 'text', '您的动作整体流畅性较好，但第5秒和第7秒出现卡顿，建议加强盘踢节奏训练。左脚踢球时，第6秒踢球点偏低，需调整角度与力度控制。第3秒至第4秒间动作幅度波动较大，应强化核心肌群稳定性训练，减少多余摆动，提升精准度与连贯性。多组分解练习有助于优化表现。', 'ai', '2025-05-24 15:09:56', 1);
