INSERT INTO `ai_content_info` VALUES (1334, 826, NULL, 'text', '您的动作在第3秒到第4秒间存在稳定性不足，建议加强核心肌群训练，尤其是髋关节和膝关节的协调性。同时，在第5秒附近出现短暂卡顿，可通过慢速分解练习提升流畅性。注意调整身体重心转移，优化发力点精准度，增加单腿平衡训练以改善整体表现。', 'ai', '2025-07-04 20:30:20', 1);
