INSERT INTO `ai_note_info` VALUES (79, NULL, 29, 'http://10.200.70.15:9002/files/2025/03/b0ef9307c9a44cbf810acf6ec3a9a28b.mp4', '2dec838d71714709a2c1fd58b5c93107', '视频笔记分析任务81', NULL, NULL, NULL, NULL, '失败', '2025-04-11 20:16:27', NULL, 1, NULL, 1);
INSERT INTO `ai_note_info` VALUES (80, NULL, NULL, 'http://www.tenir.cn/2.mp4', 'b9b3db1e0a2941a991976ac8739bf399', '视频笔记分析任务91', '\"[{\\\"Id\\\":1,\\\"Start\\\":230,\\\"End\\\":242370,\\\"Headline\\\":\\\"足球技战术综合运用与训练方法\\\",\\\"Summary\\\":\\\"讨论了足球比赛中各项技术的综合运用及其重要性，强调了反复强化训练的必要性。涵盖了单人、双人以及三人战术传球练习，以及针对前锋、中场球员的组合传球练习。同时，详细介绍了发球和接发球技术的训练，包括快速控球、变化球、接发球组织进攻等关键环节，旨在提高发球的目的性、准确性和多样性，以及接发球的成功率和战术效果。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"对话深入探讨排球训练中的关键技术和战术，包括单人、双人及三人传踢球练习，强调\'2525\'和\'71274\'组合传球提升主攻手和二传手技能。发球技术被定位为比赛起点和重要进攻手段，需追求快速、控点和变化。接发球技术是组织进攻和争取主动的关键，正确的挑高送前至关重要。讨论了不同方向、落点和速度的来球处理，以及战术性接发球和快速攻球练习，突出观察、快速启动和精准选位的重要性。整体强调技术在比赛中的综合运用和反复强化训练的必要性。\\\",\\\"ParagraphTitle\\\":\\\"排球训练关键技术与战术实践\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了踢球技术在比赛中的核心地位，认为它是技战术实施的关键，需通过反复强化训练提升。他介绍了多样化的踢球练习，涵盖单人、双人、三人战术性传踢球，以及主攻手与二传手的组合传球，旨在全面提高球员技能。他突出了发球的重要性，不仅作为比赛的开端，更是有效的进攻手段，应追求快速、控点与变化，具体技巧包括快速发球、控点发球及组合变化发球。接发球被视为组织进攻的关键环节，他演示了应对不同方向、落点和速度的接发球技巧，以及战术性接发球和快练攻球策略，特别强调了观察球、迅速启动和准确选位接球的重要性。通过这些综合训练，旨在全面提升球队的技战术水平。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在排球比赛中，各项踢球技术如何在比赛实践中的综合运用，并起到什么作用？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"各项踢球技术在比赛实践中扮演着串联和纽带的角色，是实施各种技战术的基础保障。通过反复强化训练，这些技术能够帮助球员在比赛中灵活应对不同情况。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]},{\\\"Question\\\":\\\"训练中包含哪些踢球技术组合练习？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"训练包括单人船踢球练习、双人传踢球练习、双人战术性传踢球练习以及三人战术性传踢球练习。此外，还有针对主攻手改做二传手的组合传球练习，以及提高二传手战术球组合传球能力的练习。\\\",\\\"SentenceIdsOfAnswer\\\":[7,8]},{\\\"Question\\\":\\\"发球在排球比赛中的重要性和基本要求是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14],\\\"Answer\\\":\\\"发球不仅是比赛的开始，也是一项重要的进攻手段。它可以直接得分，破坏对手的一传和二传，削弱其攻击威力，为本队防守反击创造有利条件。无论采用何种发球姿势，都应以发快速球、控点球和变化球为目的，尤其要注重提高发球的目的性、准确性和变化性。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14]},{\\\"Question\\\":\\\"接发球在排球比赛中的意义及关键技术点是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[15,16,17],\\\"Answer\\\":\\\"接发球是组织进攻和争取主动的关键环节，除快攻外，成功的一脚挑高送前是衡量接发球成功与否的重要标志。运动员需具备根据来球方向、落点和速度进行不同方向和不同高度的挑高送球能力，从而为本队创造进攻机会。\\\",\\\"SentenceIdsOfAnswer\\\":[15,16,17]},{\\\"Question\\\":\\\"战术性接发球和相关练习内容有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[18,19],\\\"Answer\\\":\\\"战术性接发球包括一挑背攻和一接一传等技术，旨在通过精确的接球技术和合理的位置选位，确保有效组织二次进攻。同时，还强调看球启动、判断发球方位并快速启动接球的动作协调性。\\\",\\\"SentenceIdsOfAnswer\\\":[20]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"足球技战术综合训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人船踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"强调个人技术的综合运用\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"串联和纽带作用\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"实施技战术的保障\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"反复强化性训练\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"双人传踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"提升两人之间的配合\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"战术性传踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"加强默契和准确性\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"三人战术性传踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"复杂战术配合的训练\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高团队协作能力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"组合传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"2525: 提高主攻手改做二传的能力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"71274: 提升二传手二传战术球技巧\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"发球技术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"比赛开始与进攻手段\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快速控点和变化球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快速球、低点扫发、高点扫发近网球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合变化球、点区发、打准发、变现发、变点发、交叉发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屄腿发、椎胸发\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"接发球技术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"组织进攻、争取主动的关键\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"挑高送前作为成功标志\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"不同方向、落点、速度的来球处理\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"挑高送前，争取供求\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"战术性接发球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一挑背攻、一接一传\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快练攻球\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"观察与启动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"看球启动，判断方位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快速启动，选位接球\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"传踢球\\\",\\\"战术\\\",\\\"接发球\\\",\\\"组合传球\\\",\\\"二传\\\",\\\"比赛\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":230,\\\"End\\\":11882,\\\"Text\\\":\\\"是各项踢球技术在比赛实践中的综合运用，它起着十分重要的串联和纽带作用，是实施各项技战术的基础。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":12370,\\\"End\\\":14830,\\\"Text\\\":\\\"应反复进行强化训练。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":11,\\\"Start\\\":130010,\\\"End\\\":157017,\\\"Text\\\":\\\"无论采用哪种发球姿势，都应以发出快速控点和变化球为目标。在基本掌握了快速发球和控点球的基础上，应着重提高发球的目的性、准确性和变化性。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.17263092,\\\"Lecture\\\":0.6028193,\\\"Meeting\\\":0.22454973}}\"', NULL, '已完成', '2025-04-11 20:16:46', NULL, 1, NULL, 1);
INSERT INTO `ai_note_info` VALUES (81, NULL, NULL, 'http://www.tenir.cn/2.mp4', 'ae5cb6b57e3a4ef0899ed86683e9e31e', '视频笔记分析任务101', '\"[{\\\"Id\\\":1,\\\"Start\\\":230,\\\"End\\\":242370,\\\"Headline\\\":\\\"足球技战术综合运用与训练方法\\\",\\\"Summary\\\":\\\"讨论了足球比赛中各项技术的综合运用及其重要性，强调了反复强化训练的必要性。涵盖了单人、双人及三人战术传球练习，以及针对前锋和中场球员的组合传球练习。同时，详细介绍了发球、接发球技术的训练，包括快速控点、变化球路、接发球组织进攻等关键环节，旨在提高技战术的目的性、准确性和多变性。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"对话深入探讨排球训练中的关键技术和战术，包括单人、双人及三人传踢球练习，强调\'2525\'和\'71274\'组合传球提升主攻手和二传手技能。发球技术被定位为比赛起点和重要进攻手段，需追求快速、控点和变化。接发球技术是组织进攻和争取主动的关键，正确的挑高送前至关重要。讨论了不同方向、落点和速度的来球处理，以及战术性接发球和快速攻球练习，突出观察、快速启动和精准选位的重要性。整体强调技术在比赛中的综合运用和反复强化训练的必要性。\\\",\\\"ParagraphTitle\\\":\\\"排球训练关键技术与战术实践\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了踢球技术在比赛中综合运用的重要性，认为它是技战术实施的基石，需通过反复强化性训练提升。他介绍了多种踢球练习形式，包括单人、双人、三人战术性传踢球，以及主攻手与二传手的组合传球练习，旨在全面提高球员技能。他突出了发球作为比赛开局与进攻手段的关键作用，主张发球应追求快速、控点和变化，分享了快速球、控点球、组合变化球等技巧。此外，他强调接发球是组织进攻和争取主动的决定性环节，提及了处理不同方向、落点和速度来球的策略，以及挑高送前、战术性接发球等技巧，特别指出看球启动、快速选位对于接发球的重要性。总之，他的发言围绕踢球技术、发球和接发球的训练与策略展开，旨在全面提升球队的技战术水平。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在排球比赛中，各项踢球技术如何在比赛实践中的综合运用，并起到什么作用？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"各项踢球技术在比赛实践中扮演着串联和纽带的角色，是实施各种技战术的基础和保障。在训练中应反复进行强化性训练。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]},{\\\"Question\\\":\\\"单人船踢球练习的目标是什么？双人传踢球练习主要在训练什么内容？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"单人船踢球练习可能是为了练习个人控球能力和基本技术。双人传踢球练习主要在提高两人之间的配合和战术执行能力。\\\",\\\"SentenceIdsOfAnswer\\\":[4,5]},{\\\"Question\\\":\\\"双人战术性传踢球练习的重点是什么？三人战术性传踢球练习的目标为何？\\\",\\\"SentenceIdsOfQuestion\\\":[5],\\\"Answer\\\":\\\"双人战术性传踢球练习重点在于提升特定战术配合下的传球技巧和策略运用。三人战术性传踢球练习旨在增强团队内部多位置间的协同作战能力和战术灵活性。\\\",\\\"SentenceIdsOfAnswer\\\":[5,6]},{\\\"Question\\\":\\\"2525和71274练习是针对哪类球员的传球配合训练？\\\",\\\"SentenceIdsOfQuestion\\\":[7,8],\\\"Answer\\\":\\\"2525练习是为主攻手改做二传手时的组合传球练习，71274则是提高二传手进行战术球组合传球的能力。\\\",\\\"SentenceIdsOfAnswer\\\":[7,8]},{\\\"Question\\\":\\\"发球在排球比赛中的重要性和基本要求是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14],\\\"Answer\\\":\\\"发球是比赛开始和进攻手段之一，可以直接得分或破坏对手的一传、二传，削弱其攻击威力。发球应以发快速球、控点球和变化球为目标，尤其需要提升发球的目的性、准确性和变化性。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14]},{\\\"Question\\\":\\\"接发球在排球比赛中的关键性和具体要求是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[15,16,17],\\\"Answer\\\":\\\"接发球是组织进攻和争取主动的重要环节，成功与否通常取决于能否成功挑高送前。此外，还需针对不同方向、落点和速度变化进行有效接球，如战术性接发球中的快练攻球和一挑背攻等技巧。\\\",\\\"SentenceIdsOfAnswer\\\":[15,16,17]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"足球技术综合运用与训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人船踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"强调个人技术的综合运用\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"串联和纽带作用\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"实施技战术的保障\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"反复强化性训练\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"双人传踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"提升二人之间的配合\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"战术性传踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"加强战术理解和执行\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"三人战术性传踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"复杂战术的实践\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升团队协作和战术执行能力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"组合传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"2525: 提高主攻手改做二传的能力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"71274: 提升二传手二传战术球的组合传球技巧\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"发球技术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"比赛开始与进攻手段\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"直接得分与破坏对手一传、二传\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快速控点和变化球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高目的性、准确性和变化性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"发快速球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"低点扫发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"高点扫发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"近网球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合变化球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"点区发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"打准发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"变现发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"变点发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"交叉发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屄腿发\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"椎胸发\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"接发球技术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"组织进攻与争取主动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"挑高送前作为成功标志\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"不同方向、落点、速度的来球处理\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"挑高送钱，争取供求\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"战术性接发球与快练攻球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一挑背攻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"一接一传\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"看球启动，快速选位接球\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"快启动与选位\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"准确选位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"接好球，为后续战术创造条件\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"传踢球\\\",\\\"战术\\\",\\\"接发球\\\",\\\"组合传球\\\",\\\"二传\\\",\\\"比赛\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":230,\\\"End\\\":11882,\\\"Text\\\":\\\"是各项踢球技术在比赛实践中的综合运用，它起着十分重要的串联和纽带作用，是实施各项技战术的保证。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":12370,\\\"End\\\":14830,\\\"Text\\\":\\\"应反复进行强化训练。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":11,\\\"Start\\\":130010,\\\"End\\\":157017,\\\"Text\\\":\\\"无论采用哪种发球姿势，都应以发出快速、控制点位及变化多端的球为目标。在掌握了快速发球和定点发球的基础上，应着力提高发球的目的性、准确性和多样性。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.17263092,\\\"Lecture\\\":0.6028193,\\\"Meeting\\\":0.22454973}}\"', '发球是比赛开始和进攻手段之一，可以直接得分或破坏对手的一传、二传，削弱其攻击威力。发球应以发快速球、控点球和变化球为目标，尤其需要提升发球的目的性、准确性和变化性。', '已完成', '2025-04-11 20:18:52', '2025-04-11 22:00:00', 1, 1, 1);
