INSERT INTO `ai_note_info` VALUES (184, NULL, 39, 'https://lxzj.tenir.cn/lxzj/files/2025/04/cbafb88588a045a7a25601db2098f728.mp4', '95cdd90cdc544bb4989cd1c27a3458e9', '视频笔记分析任务51', NULL, NULL, NULL, NULL, '进行中', '2025-04-20 16:01:30', NULL, 1, NULL, 1);
INSERT INTO `ai_note_info` VALUES (185, NULL, 39, 'https://lxzj.tenir.cn/lxzj/files/2025/04/cbafb88588a045a7a25601db2098f728.mp4', '9ab6429d3d0a400cb022606ce8c8a825', '视频笔记分析任务51', '\"[{\\\"Id\\\":1,\\\"Start\\\":6230,\\\"End\\\":144080,\\\"Headline\\\":\\\"健子老师教你十个踢毽子技巧\\\",\\\"Summary\\\":\\\"本教程详细介绍了十个踢毽子的基础技巧，包括正确的拿毽方法以及用脚内侧、膝盖、正脚背、脚外侧踢毽的不同方式。同时，还教授了如何用脚内侧、正脚背、前额和后背停毽的方法，以及跳踢和剪跳等高级技巧，旨在帮助初学者快速掌握踢毽子的基本动作和技术。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"健子老师强调了传承民族体育精神的重要性，并详细分享了十个踢毽子技巧，包括正确的拿毽子方法、手模拟踢毽动作以感受飞行轨迹和掌握节奏，以及脚内侧踢、膝盖踢、正脚背踢、脚外侧踢、正脚背停毽、脚内侧停毽、前额停毽、后背停毽、跳踢和剪跳等具体动作及其操作步骤，如膝关节外转、小腿上摆、勾脚尖等，以及空中停毽和踢毽时的缓冲技巧。通过这些技巧的练习，旨在帮助大家更好地享受踢毽子带来的健康和快乐。\\\",\\\"ParagraphTitle\\\":\\\"健子老师分享踢毽子技巧与传承民族体育精神\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"健子老师强调了传承民族体育的重要性，特别是踢毽子这一传统运动。他分享了踢毽子的十个基本技巧，首先指导正确的拿毽子方法，即从底部拿取以保护云毛，建议初学者通过手模拟拍打毽子来感受其空中翻腾和掌握节奏。接着，详细讲解了十个技巧：脚内侧踢、膝盖踢、正脚背踢、脚外侧踢、正脚背停毽、脚内侧停毽、前额停毽、后背停毽、跳踢和剪跳。每个动作都配有具体的操作描述，如膝关节的转动、小腿的上摆以及脚部特定部位的运用，旨在帮助学习者全面掌握踢毽子的技巧，从而更好地传承和发扬民族体育文化。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习踢毽子时，如何正确拿取毽子并适应初学者的训练？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"在开始学习踢毽子时，首先要掌握拿毽子的方法，正确的拿法是用手抓住毽子底部，避免触碰到云毛。对于初学者来说，由于用脚直接踢毽子可能有难度，建议先用手模拟拍打毽子的动作，以感受毽子在空中的翻转和掌握踢毽的节奏。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]},{\\\"Question\\\":\\\"踢毽子时有哪些基础的动作技巧？除了基础的踢腿动作外，还有哪些进阶的动作技巧？\\\",\\\"SentenceIdsOfQuestion\\\":[5,6,7,8,9],\\\"Answer\\\":\\\"首先介绍的是脚内侧踢的动作，通过膝关节外转、小腿上摆并用脚内侧触球来完成。接下来是五个不同的踢腿动作，包括膝盖踢、正脚背踢、脚外侧踢以及正脚背停毽（缓冲）和脚内侧停毽（缓冲），这些动作都要求随着毽子下落时做出相应的由上至下的缓冲动作。还包含了跳踢和剪跳两种进阶动作。跳踢是右腿自然抬起，左腿发力蹬地起跳，在空中形成交叉姿势，然后用左脚内侧踢毽，落地时右脚先接触地面；剪跳则是双脚同时起跳，在空中呈剪刀状折叠，用右脚正脚背踢毽。\\\",\\\"SentenceIdsOfAnswer\\\":[5,6,7,8,9,13,14,15]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽子技巧教学\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基础技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"拿毽子方法\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"拿毽子底部\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"避免碰到云毛\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"初学者建议先用手模拟拍打\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"十大技巧详解\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"1. 脚内侧踢大腿\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"抬起膝关节\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿上摆脚往内翻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用脚内侧踢球\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"2. 膝盖踢大腿\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"带动小腿上踢\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝用大腿中前部踢球\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"3. 正脚背踢大腿\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"带动小腿前摆\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用正脚背踢球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢球时勾脚尖\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"4. 脚外侧踢大腿\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"抬起膝关节内翻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿上摆，勾脚尖\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用脚外侧踢球\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"5. 正脚背停毽\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿抬起\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"缓冲动作停毽子于三角区\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"6. 脚内侧停毽\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿抬起，小腿上摆脚往内翻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"缓冲动作停毽子于脚内侧\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"7. 前额停毽\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"将毽子踢至身体后上方\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬头用前额停毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双腿可屈膝缓冲\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"8. 后背停毽\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"将毽子踢至身体前上方\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"腰部前屈，用后脑至背部之间停毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双腿可屈膝放松\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"9. 跳踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右腿自然抬起，左腿发力蹬地起跳\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"空中形成右腿在上、左腿在下交叉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用左脚内侧踢毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"落地时右脚先落地\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"10. 剪跳\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚全身同时起跳\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"空中形成剪刀状折叠\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用右脚正脚背踢毽\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽子\\\",\\\"健子老师\\\",\\\"技巧\\\",\\\"拿毽子\\\",\\\"底部\\\",\\\"云毛\\\",\\\"初学者\\\",\\\"节奏\\\",\\\"脚内侧踢\\\",\\\"膝盖踢\\\",\\\"正脚背踢\\\",\\\"脚外侧踢\\\",\\\"正脚背停毽\\\",\\\"脚内侧停毽\\\",\\\"前额停毽\\\",\\\"后背停毽\\\",\\\"跳踢\\\",\\\"剪跳\\\",\\\"剪刀状折叠\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":6230,\\\"End\\\":9076,\\\"Text\\\":\\\"传承民族体育，共享健康快乐。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":9080,\\\"End\\\":14136,\\\"Text\\\":\\\"大家好，我是你们的健子老师，今天我将会教大家十个踢毽子的技巧。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.310652,\\\"Lecture\\\":0.5168338,\\\"Meeting\\\":0.17251423}}\"', '<p><br></p>', '已完成', '2025-04-21 02:30:29', '2025-05-19 04:00:24', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (186, NULL, 77, 'https://lxzj.tenir.cn/lxzj/files/2025/04/44b22e3ebadf4cd394a690a64ec9a53f.mp4', '7eeffe130cf941b48a3e79de3100017c', '视频笔记分析任务61', '\"[{\\\"Id\\\":1,\\\"Start\\\":90,\\\"End\\\":50400,\\\"Headline\\\":\\\"教你五个踢毽球的技巧\\\",\\\"Summary\\\":\\\"本内容介绍了五个踢毽球的技巧，包括脚内侧踢、膝盖踢、正脚背踢、脚外侧踢以及正脚背停毽等动作的详细操作方法。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽球的五项基础技巧，包括：1) 脚内侧踢，通过膝关节外转和小腿上摆用脚内侧击球；2) 膝盖踢，带动小腿上踢，用大腿中前部击球；3) 正脚背踢，大腿带动小腿前摆，勾脚尖用正脚背击球；4) 脚外侧踢，膝关节内翻，小腿上摆，勾脚尖用脚外侧击球；5) 正脚背停球，大腿抬起，随着毽子下落做出缓冲动作，将毽子停在正脚背上。这些技巧有助于学习者掌握踢毽球的基本动作。\\\",\\\"ParagraphTitle\\\":\\\"掌握踢毽球：五项基础技巧详解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"分享了五种踢毽球的技巧，旨在提升踢毽技巧和控制力。首先，脚内侧踢技巧，通过膝关节外转与小腿上摆，利用脚内侧部位精准触球。其次，膝盖踢技巧，运用小腿上踢与屈膝动作，以大腿中前部接触毽球。第三，正脚背踢技巧，通过小腿前摆并勾脚尖，用正脚背部位踢球。第四，脚外侧踢技巧，借助膝关节内翻、小腿上摆及勾脚尖，使用脚外侧踢球。最后，正脚背停球技巧，通过大腿抬起与由上至下的缓冲动作，将毽子稳稳停在正脚背。这些技巧强调了身体各部位的协调运用，以及对毽球的精准控制。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在踢毽球时，第一个要学习的动作是什么？第二个踢毽球的动作是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5,6],\\\"Answer\\\":\\\"第一个动作是脚内侧踢，具体操作为抬起膝关节外转小腿上摆，然后用脚内侧去踢球。第二个动作是膝盖踢，即带动小腿上踢并屈膝，用大腿中前部去踢球。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5,6]},{\\\"Question\\\":\\\"第三个踢毽球的动作是什么？第四个踢毽球的动作如何进行？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5,6],\\\"Answer\\\":\\\"第三个动作是正脚背踢，带动小腿前摆，并且在踢球时需要勾脚尖，用正脚背接触球体。第四个动作是脚外侧踢，首先抬起膝关节内翻，接着小腿上摆并勾脚尖，最后用脚外侧来踢球。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5,6]},{\\\"Question\\\":\\\"第五个踢毽球的动作是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5,6],\\\"Answer\\\":\\\"第五个动作是正脚背停球，当毽子下落时，大腿抬起并做出由上至下的缓冲动作，将毽子稳稳停在正脚背上。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5,6]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽球技巧脑图摘要\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技巧一: 脚内侧踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"抬起膝关节\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"外转小腿上摆\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚往内翻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用脚内侧踢球\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧二: 膝盖踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"带动小腿上踢\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用大腿中前部踢球\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧三: 正脚背踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿带动小腿前摆\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用正脚背踢球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢球时勾脚尖\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧四: 脚外侧踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"抬起膝关节内翻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿上摆\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"勾脚尖\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用脚外侧踢球\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧五: 正脚背停球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿抬起\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"随着毽子下落做出由上至下的缓冲动作\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"将毽子停在正脚背\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽球\\\",\\\"技巧\\\",\\\"脚内侧踢\\\",\\\"膝盖踢\\\",\\\"正脚背踢\\\",\\\"脚外侧踢\\\",\\\"正脚背停毽\\\",\\\"抬起膝关节\\\",\\\"小腿上摆\\\",\\\"勾脚尖\\\",\\\"缓冲动作\\\",\\\"毽子\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.028289448,\\\"Lecture\\\":0.9315202,\\\"Meeting\\\":0.04019024}}\"', '<p><br></p>', '已完成', '2025-04-21 06:55:40', '2025-05-13 15:05:38', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (187, NULL, 78, 'https://lxzj.tenir.cn/lxzj/files/2025/04/fab7366229f943d7a86f63bd1faa9ea6.mp4', '7a3ebbc1c12c44eb955dbdd301e43aea', '视频笔记分析任务71', '\"[{\\\"Id\\\":1,\\\"Start\\\":90,\\\"End\\\":28170,\\\"Headline\\\":\\\"教授三种踢毽球技巧\\\",\\\"Summary\\\":\\\"介绍了三种踢毽球的技巧：使用脚内侧踢球、用大腿中部踢球以及用正脚背踢球的方法和动作要领。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽球的三项基本技巧：1. 使用脚内侧踢球，通过膝关节抬起并外转小腿，使脚内侧接触毽球；2. 采用膝盖踢法，通过小腿上踢并屈膝，用大腿中前部击球；3. 使用正脚背踢球，大腿带动小腿前摆，踢球时需勾脚尖，以正脚背部位击球。强调了这三个技巧的重要性。\\\",\\\"ParagraphTitle\\\":\\\"踢毽球基础技巧教学\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"分享了三种踢毽球的基本技巧。首先，脚内侧踢球技巧，通过膝关节向外旋转并配合小腿向上摆动，利用脚内侧部位接触并控制毽球。其次，膝盖踢球技巧，此技巧需要通过小腿的上踢和膝盖的弯曲动作，使用大腿中前部来踢毽球，实现对毽球的精准控制。最后，正脚背踢球技巧，通过大腿带动小腿向前摆动，利用正脚背部位踢毽球，同时在踢球的过程中需要勾起脚尖，以增加踢球的准确性和力量。他的分享详细地介绍了这三种技巧的动作要领，为毽球爱好者提供了实用的技巧指导。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在踢毽球时，第一个要学习的动作是什么？第二个踢毽球的动作是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"第一个动作是脚内侧踢球，具体操作为抬起膝关节，外转小腿上摆，然后用脚内侧去踢球。第二个动作是膝盖踢球，即带动小腿上踢并屈膝，用大腿中前部去踢球。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]},{\\\"Question\\\":\\\"第三个要掌握的踢毽球动作是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"第三个动作是正脚背踢球，具体是带动小腿前摆，用正脚背踢球，并且在踢球时需要勾脚尖。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽球技巧教学\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技巧一: 脚内侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作细节:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"抬起膝关节\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"外转小腿上摆\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚往内翻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用脚内侧部位踢球\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧二: 膝盖踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作细节:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"带动小腿上踢\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝动作\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用大腿中前部踢球\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧三: 正脚背踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作细节:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿带动小腿前摆\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"使用正脚背部位踢球\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢球时需勾脚尖\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽球\\\",\\\"技巧\\\",\\\"脚内侧踢大腿\\\",\\\"膝关节外转\\\",\\\"小腿上摆\\\",\\\"脚内侧\\\",\\\"膝盖顶大腿\\\",\\\"小腿上踢\\\",\\\"屈膝\\\",\\\"大腿中前部\\\",\\\"正脚背踢大腿\\\",\\\"小腿前摆\\\",\\\"正脚背\\\",\\\"勾脚尖\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.032239523,\\\"Lecture\\\":0.9267904,\\\"Meeting\\\":0.040970046}}\"', '<p><br></p>', '已完成', '2025-04-21 07:44:28', '2025-05-13 15:05:42', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (188, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E6%88%98%E6%9C%AF%E6%AD%A5%E6%B3%95%E8%B8%A2%E7%90%83%E7%BB%83%E4%B9%A0.mp4', '2b3759bc3698442a9b9324e20550cfe8', '视频笔记分析任务81', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":147768,\\\"Headline\\\":\\\"毽球基本战术与技术训练概述\\\",\\\"Summary\\\":\\\"毽球的基本战术分为进攻和防守两部分。进攻战术包括单一倒钩型、踩踏型及综合型配置，阵容配置有1-1-2、2-2-1、3-3-3等三种形式，打法多样，如高举高打、快球进攻、中路进攻等。防守战术则有小弧形、一拦二防、拦堵防、二拦一防四种基本阵型。毽球技术训练是毽球训练的基础，强化每一项技术训练是提升水平的关键。\\\"},{\\\"Id\\\":2,\\\"Start\\\":148360,\\\"End\\\":307370,\\\"Headline\\\":\\\"毽球运动员的步法训练方法\\\",\\\"Summary\\\":\\\"毽球运动员在场上的移动始于准备姿势，通过五步法进行训练，包括双脚与肩同宽站立、脚掌外转、脚跟外移形成内八字、下降重心并前倾身体、全身放松注视来球。训练从单人练习逐步过渡到集体、综合以及带球实战，注重动作的规范性和连贯性。\\\"},{\\\"Id\\\":3,\\\"Start\\\":323530,\\\"End\\\":460090,\\\"Headline\\\":\\\"踢球练习与传球技术训练方法\\\",\\\"Summary\\\":\\\"踢球练习作为传球训练的基础，强调正确的脚型、单人练习时的协调连贯、双人及隔网对踢时的放松自如，以及结合步伐的综合行进练习。触球练习作为过渡性技术，需紧密结合实践进行，包括单人、双人互打杂处踢球练习，以及结合步伐与实战的触踢球练习和组合式综合性触球练习。传球练习涵盖了各项踢球技术的综合应用。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球战术分为进攻和防守两部分。进攻战术包括单一倒钩型、单一踩踏型和倒钩踩踏综合型技术配备，以及一一二、221、333三种阵容配备，还有多种打法如高举高打、快球进攻等。防守战术有小弧形、一篮二防、拦堵防、二拦一防四种基本阵型。技术训练是毽球训练的基础，强调基本功的重要性，包括运动员的移动、步法练习、踢球练习和触球练习。训练原则为单一练习规范、统一练习一致、综合练习连贯、带球练习实战。整个训练过程包括单人、双人、隔网对踢和组合式综合触球练习，旨在全面提升运动员的技术水平和实战能力。\\\",\\\"ParagraphTitle\\\":\\\"毽球战术、技术和训练方法综述\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"详细阐述了毽球基本战术的构成与分类，强调了进攻与防守战术的多样性。进攻战术包括单一倒钩型、单一踩踏型及倒钩踩踏综合型，阵容配备分为一一二、221、333三种，打法配备涵盖高举高打型、快球进攻型等八种类型。防守战术则有小弧形、一篮二防等四种基本阵型。他特别强调技术训练的重要性，指出准备姿势的五个步骤，以及步法、踢球和触球练习作为基本功的必要性。在训练原则方面，提出了“单一练习规范、统一练习不走样、综合练习连贯、带球练习进实战”的理念，展示了从单人到集体、综合、带球的训练过程，强调了脚型练习的规范性、踢球练习的连贯性，以及触球练习与实战结合的重要性。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球基本战术包含哪些部分以及进攻战术有哪些配备和技术？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分。在进攻战术中，技术配备有单一倒钩型、单一踩踏型以及倒钩踩踏综合型。此外，进攻战术的阵容配备有三种形式，分别是“一一二”阵容配备、“221”阵容配备和“333”阵容配备。具体的打法配备包括高举高打型、快球进攻型、中路进攻型、四边路进攻型、自调进攻型、背溜进攻型、掩护进攻型和交叉进攻型。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,5,6]},{\\\"Question\\\":\\\"毽球防守战术有多少种基本防守阵型？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14,15,16],\\\"Answer\\\":\\\"毽球防守战术共有四种基本防守阵型，分别是小弧形防守阵型、一篮二防防守阵型、拦堵防防守阵型以及二拦一防防守阵型。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14,15,16]},{\\\"Question\\\":\\\"毽球运动员如何进行准备姿势训练，并描述了哪几种常见的准备姿势？\\\",\\\"SentenceIdsOfQuestion\\\":[17,18,19,20,21,22],\\\"Answer\\\":\\\"毽球运动员在场上比赛时的移动从准备姿势开始。一般准备姿势的脚距丈量因人而异，可以分为五步进行：两脚与肩同宽平行开立、以脚跟为轴两脚掌外转接近平行、以脚尖为轴两脚跟外移呈内八字形站位、重心下降上体稍前倾膝关节内扣以及两手臂自然弯曲于体前。在单人练习成型后，要求一步到位并体会用脚尖内侧迅速发力蹬地，重心被推移的感觉。\\\",\\\"SentenceIdsOfAnswer\\\":[17,18,19,20,21,22]},{\\\"Question\\\":\\\"步法练习在毽球运动员训练中的重要性是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[25,26,27,28],\\\"Answer\\\":\\\"步法练习是毽球运动员临场比赛的一大基本功，它能确保人与球的最佳位置。训练中应坚持单一练习要规范统一，综合练习要连贯，带球练习进实战的原则。通过反复练习蹬地的感觉和步法动作，以提高运动员的灵活性和位置调整能力。\\\",\\\"SentenceIdsOfAnswer\\\":[25,26,27,28]},{\\\"Question\\\":\\\"传球训练的基础是什么？并且详细列举了哪些练习方式？\\\",\\\"SentenceIdsOfQuestion\\\":[32,33,34],\\\"Answer\\\":\\\"踢球练习是传球训练的基础，也是重要的基本功。脚型练习需规范严格，单人练习要求协调连贯，组合练习需放松自如，综合行进练习则需结合步伐。具体包括单人练习、双人练习、隔网对踢练习等多种形式，最终目的是使触球练习这一过渡性技术训练能与实践紧密结合，逐步提高实战能力。\\\",\\\"SentenceIdsOfAnswer\\\":[32,33,34]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本战术与技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"毽球基本战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"进攻战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一倒钩型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单一踩踏型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"倒钩踩踏综合型配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"阵容配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一一二阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"221阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"333阵容配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"打法配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"高举高打型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快球进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"中路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"四边路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"自调进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"背溜进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"掩护进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"交叉进攻型\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本防守阵型\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小弧形防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"一篮2防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"拦堵防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"二拦一防防守阵型\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"准备姿势与移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"五步进行\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两脚与肩同宽，平行开立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚跟为轴，两脚掌外转接近平行\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚尖为轴，两脚跟外移，呈内八字形站位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"全身放松，目视来球静中带动\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"步法练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一练习要规范\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"统一练习不走样\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合练习要连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带球练习进实战\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚型练习应规范严格\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单人练习要协调连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合练习要放松自如\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合行进练习要结合步伐\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"触球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人互打杂处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带步法的与实战结合的触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合式综合性触球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"各项踢球技术的基础\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本战术\\\",\\\"进攻战术\\\",\\\"防守战术\\\",\\\"高举高打型\\\",\\\"快球进攻型\\\",\\\"中路进攻型\\\",\\\"四边路进攻型\\\",\\\"自调进攻型\\\",\\\"背溜进攻型\\\",\\\"掩护进攻型\\\",\\\"交叉进攻型\\\",\\\"技术训练\\\",\\\"准备姿势\\\",\\\"移动\\\",\\\"步法练习\\\",\\\"踢球练习\\\",\\\"脚型练习\\\",\\\"触球练习\\\",\\\"传球练习\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":8254,\\\"Text\\\":\\\"毽球基本战术是毽球队员在比赛中相互配合运用各项基本技术的组合。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":8990,\\\"End\\\":20310,\\\"Text\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分，进攻战术的技术配备有单一倒钩型。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":5,\\\"Start\\\":46250,\\\"End\\\":59607,\\\"Text\\\":\\\"进攻战术的阵容配备有以下三种：一一二阵容、二二一阵容和三三一阵容。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":6,\\\"Start\\\":60830,\\\"End\\\":67390,\\\"Text\\\":\\\"进攻战术的打法配备有多种，其中包括高举高打型。\\\"},{\\\"Id\\\":5,\\\"SentenceId\\\":40,\\\"Start\\\":413510,\\\"End\\\":420830,\\\"Text\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，应与实践紧密结合进行。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.13368736,\\\"Lecture\\\":0.28069776,\\\"Meeting\\\":0.5856148}}\"', '<p><br></p>', '已完成', '2025-04-24 09:37:05', '2025-05-20 02:57:00', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (189, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E8%8A%B1%E6%AF%BD-%E6%8B%90%E8%B8%A2-%E8%B7%B3%E8%B8%A2-%E8%90%BD%E8%B8%A2-%E6%8A%B9%E8%B8%A2-%E8%B9%81%E8%B8%A2.mp4', 'a4d71853340b4d79839700f18b8daf75', '视频笔记分析任务91', '\"[{\\\"Id\\\":1,\\\"Start\\\":5210,\\\"End\\\":202790,\\\"Headline\\\":\\\"花毽基本动作：盘踢、磕踢和崩踢\\\",\\\"Summary\\\":\\\"介绍了花毽运动中的基本动作，包括盘踢、磕踢和崩踢的技术要点及练习技巧。盘踢使用双脚内侧交替踢毽，磕踢利用大腿靠近膝关节的部位踢毽，而崩踢则是通过抬起大腿带动小腿发力，用脚面触毽。这些技巧对花毽爱好者提高技术水平具有指导意义。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"国家级社会体育指导员穆丹介绍了花毽运动的历史渊源，指出踢毽起源于汉代，东汉山东济宁出土的画像砖上有相关图案。唐宋时期，花毽的基本技术已有图形记录。她详细讲解了花毽的三个基本动作：盘踢、磕踢和崩踢。盘踢使用双脚内侧交替踢毽，要求膝关节外展，小腿发力；磕踢用大腿靠近膝关节的部位踢毽，大腿抬起与身体呈90度；崩踢则用脚背踢毽，小腿向正上方摆动。穆丹强调了练习这些动作时的技巧，帮助爱好者掌握技术要领。此指导视频由中国社会体育指导员协会和中国篮球协会共同录制。\\\",\\\"ParagraphTitle\\\":\\\"国家级社会体育指导员详解花毽运动历史与基本技巧\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他，国家级社会体育指导员穆丹，介绍了踢毽运动的历史起源及其在唐宋时期的发展，强调踢毽运动起源于汉代，并在东汉画像砖中已出现簇毛丸的图案，证明了其悠久的历史。他向广大社会体育指导员和健身爱好者详细讲解了花毽基本动作中的盘踢、磕踢和崩踢。盘踢是用双脚内侧交替踢毽的最基本动作，适用于初学者；磕踢是用大腿靠近膝关节的部位踢毽，需要一定的身体协调性；而崩踢是用脚背踢毽，大腿抬起，小腿向正上方摆动，是对腿部力量和灵活性的考验。他不仅阐述了每个动作的技术要领，还分享了练习技巧，旨在帮助花毽爱好者更好地掌握这些基本动作，提升运动技能。通过他的讲解，听众可以更深入地理解踢毽运动的历史背景，同时掌握其基本技巧，促进全民健身活动的开展。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"花毽运动起源于何时，其历史发展如何？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5,6],\\\"Answer\\\":\\\"花毽起源于汉代，从山东济宁出土的东汉画像砖中可以找到簇毛丸的图案。到了唐宋时期，花毽的部分基本技术已经有了图形记载。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5,6]},{\\\"Question\\\":\\\"盘踢作为花毽基本动作，具体是如何进行的？盘踢的技术要点有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[7,8,9,10,11],\\\"Answer\\\":\\\"盘踢是用双脚内侧交替踢毽，进行时膝关节外展，手臂自然下垂，依靠膝关节、小腿发力向上摆动，用足内侧将毽子踢至胸前。同时，身体保持直立，双手放于体前，手心朝下，脚带动小腿发力完成踢腿动作。练习盘踢时，需要掌握以下两点技巧：一是脚内侧端平，确保毽子下落至腰部位置；二是脚带动小腿向上翻转，以正确执行盘踢动作。\\\",\\\"SentenceIdsOfAnswer\\\":[7,8,9,10,11]},{\\\"Question\\\":\\\"科踢（又称磕踢）的动作要如何完成？\\\",\\\"SentenceIdsOfQuestion\\\":[7,8,9,10,11],\\\"Answer\\\":\\\"磕踢要求上身直立，大腿抬起接近膝关节，触键时与身体呈90度角，小腿自然下垂，脚尖朝地。利用膝关节带动大腿处发力，双手指尖相对放于腹前，膝关节带动大腿撞击手心，脚尖朝下绷直，手持毽子靠近膝关节的位置触键，膝关节带动大腿发力，脚尖朝下将毽子向前翻滚。\\\",\\\"SentenceIdsOfAnswer\\\":[12,13,14]},{\\\"Question\\\":\\\"崩提动作是如何执行的？\\\",\\\"SentenceIdsOfQuestion\\\":[15,16],\\\"Answer\\\":\\\"崩踢是用脚背踢毽，执行时大腿稍抬起，小腿向正上方摆动，脚面触键，踝关节稍发力将毽子踢起，随后大腿抬起带动小腿发力，脚尖同时挑起，用足三指辅助踢键，将毽子向前翻滚。\\\",\\\"SentenceIdsOfAnswer\\\":[15,16]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"花毽基本动作与技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"起源与发展\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"踢毽起源于汉代\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"山东济宁出土的东汉画像砖中有簇毛丸图案\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"唐宋时期，花毽部分基本技术已有图形\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚内侧交替踢毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"膝关节外展，手臂自然下垂\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"膝关节、小腿发力向上摆动，用足内侧将毽子踢至胸前\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚内侧端平，毽子下落至腰部位置\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚带动小腿向上翻转\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"磕踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"用大腿靠近膝关节的部位踢毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"上身直立，大腿抬起，触毽时与身体呈90度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿自然下垂，脚尖朝地面方向\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"膝关节带动大腿发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚尖朝下，踢起的毽子应向前翻滚\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"崩踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿稍抬起，小腿向正上方摆动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚面触毽，踝关节稍发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚尖同时挑起，用足三趾指出毽\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿抬起，带动小腿发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚尖挑起，用足三趾指出毽\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"结语\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"以上为花毽运动中的盘踢、磕踢和崩踢的动作展示和技术要点说明\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"希望对广大花毽爱好者有所帮助\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽\\\",\\\"汉代\\\",\\\"东汉画像砖\\\",\\\"唐宋时期\\\",\\\"健身爱好者\\\",\\\"盘踢\\\",\\\"崩提\\\",\\\"膝关节外展\\\",\\\"足内侧\\\",\\\"身体直立\\\",\\\"大腿抬起\\\",\\\"小腿发力\\\",\\\"脚尖朝前\\\",\\\"脚背踢\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":2,\\\"Start\\\":14900,\\\"End\\\":20330,\\\"Text\\\":\\\"到唐宋时期，花毽的基本技术已经有了图形。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.18993779,\\\"Lecture\\\":0.57687116,\\\"Meeting\\\":0.23319101}}\"', '<p>您好！</p>', '已完成', '2025-04-24 09:48:05', '2025-05-19 03:57:36', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (190, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E6%88%98%E6%9C%AF%E6%AD%A5%E6%B3%95%E8%B8%A2%E7%90%83%E7%BB%83%E4%B9%A0.mp4', '18bd40d047c8433db343fa0c57679c1a', '视频笔记分析任务91', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":147768,\\\"Headline\\\":\\\"毽球基本战术与技术训练解析\\\",\\\"Summary\\\":\\\"介绍了毽球比赛中的基本战术，包括进攻和防守两大部分。进攻战术涵盖了单一倒钩型、踩踏型及综合型配备，以及多种阵容和打法。防守战术则包括四种基本防守阵型。强调了毽球技术训练作为基础环节的重要性，指出每一项技术的强化训练是未来发展的根基。\\\"},{\\\"Id\\\":2,\\\"Start\\\":148360,\\\"End\\\":307370,\\\"Headline\\\":\\\"毽球运动员的步法训练方法\\\",\\\"Summary\\\":\\\"毽球运动员在场上的移动始于准备姿势，通过五步法进行训练，包括双脚与肩同宽站立、脚掌外转、脚跟外移成内八字、降低重心和全身放松等步骤。训练强调规范单一练习、统一练习、综合练习以及带球实战，以提高调整人与球最佳位置的能力。\\\"},{\\\"Id\\\":3,\\\"Start\\\":323530,\\\"End\\\":460090,\\\"Headline\\\":\\\"足球踢球与传球技术训练方法\\\",\\\"Summary\\\":\\\"介绍了足球训练中的踢球和传球技术的基础练习，包括脚型规范、单人与双人练习、隔网对踢、触球练习以及与实战结合的综合性训练，强调了这些练习对于提升足球技能的重要性。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球战术分为进攻和防守两部分。进攻战术包括单一倒钩型、单一踩踏型和倒钩踩踏综合型技术配备，以及一一二、221、333三种阵容配备，还有高举高打、快球进攻、中路进攻、边路进攻、自调进攻、背溜进攻、掩护进攻、交叉进攻等多种打法。防守战术则有小弧形、一篮二防、拦堵防、二拦一防四种基本阵型。技术训练是毽球训练的基础，每一项技术的强化训练都是基本功和未来发展的根基。运动员的移动从准备姿势开始，通过五步法调整站位和重心，确保全身放松并目视来球。步法练习是调整人与球最佳位置的基本功，训练中需遵循单一练习规范、统一练习一致、综合练习连贯、带球练习实战的原则。踢球练习是传球训练的基础，脚型练习应规范严格，单人练习协调连贯，组合练习放松自如，综合行进练习结合步伐。触球练习是过渡性技术训练，应与实践紧密结合。整个训练过程包括单人、双人、隔网对踢和组合式综合触球练习，旨在全面提升毽球运动员的技术水平和实战能力。\\\",\\\"ParagraphTitle\\\":\\\"毽球战术、技术和训练方法综述\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他详细阐述了毽球基本战术的构成与分类，强调了进攻与防守战术的多样性。进攻战术包括单一倒钩型、单一踩踏型及倒钩踩踏综合型配备，阵容配备分为一一二、221和333三种，打法配备涵盖高举高打型、快球进攻型等八种类型。防守战术则有小弧形、一篮二防等四种基本阵型。他特别强调了技术训练的重要性，指出准备姿势的五个步骤、步法练习、踢球练习和触球练习是基本功的关键。训练中应遵循单一练习规范、统一练习不走样、综合练习连贯和带球练习进实战的原则。此外，他介绍了单人、双人、隔网对踢和综合行进练习等不同类型的练习，强调传球练习是踢球技术的基础，触球练习与实践应紧密结合。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球基本战术包含哪些部分以及进攻战术有哪些配备和技术？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分。在进攻战术中，技术配备有单一倒钩型、单一踩踏型以及倒钩踩踏综合型。此外，进攻战术的阵容配备有三种类型，分别是一一二阵容配备、221阵容配备和333阵容配备，并且具体打法包括高举高打型、快球进攻型、中路进攻型、边路进攻型、自调进攻型、背溜进攻型、掩护进攻型和交叉进攻型。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,5,6]},{\\\"Question\\\":\\\"毽球防守战术有哪几种基本阵型？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14,15,16],\\\"Answer\\\":\\\"毽球防守战术有四种基本防守阵型，分别是小弧形防守阵型、一篮二防防守阵型、拦堵防防守阵型和二拦一防防守阵型。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14,15,16]},{\\\"Question\\\":\\\"毽球运动员在比赛中的移动准备姿势是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[17,18,19,20,21,22],\\\"Answer\\\":\\\"毽球运动员在场上比赛时的准备姿势要求五步进行，包括两脚与肩同宽平行开立、以脚跟为轴两脚掌外转接近平行、以脚尖为轴两脚跟外移呈内八字形站位、重心下降上体稍前倾、膝关节内扣两手臂自然弯曲于体前，以及全身放松目视来球。待单人练习成型后，要求一步到位并体会用脚尖内侧迅速发力蹬地，使重心被推移的感觉。\\\",\\\"SentenceIdsOfAnswer\\\":[17,18,19,20,21,22]},{\\\"Question\\\":\\\"如何进行踢球（传球）训练的基础练习？\\\",\\\"SentenceIdsOfQuestion\\\":[45],\\\"Answer\\\":\\\"踢球（传球）训练的基础是脚型练习，单人练习需协调连贯，组合练习要放松自如，综合行进练习则需结合步伐。具体包括单人练习、双人练习、隔网对踢练习等，强调踢球练习是传球训练的基础，要求规范严格，逐步过渡到实战应用。同时，触球练习作为不可或缺的技术训练，应与实践紧密结合，包括单人、双人互打和带球法与实战结合的触踢球练习，以及组合式综合性触球练习。\\\",\\\"SentenceIdsOfAnswer\\\":[45]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本战术与技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"毽球基本战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"进攻战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一倒钩型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单一踩踏型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"倒钩踩踏综合型配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"阵容配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一一二阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"221阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"333阵容配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"打法配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"高举高打型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快球进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"中路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"边路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"自调进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"背溜进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"掩护进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"交叉进攻型\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本防守阵型\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小弧形防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"一篮二防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"拦堵防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"二拦一防防守阵型\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"准备姿势与移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"五步进行\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两脚与肩同宽，平行开立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚跟为轴，两脚掌外转接近平行\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚尖为轴，两脚跟外移，呈内八字形站位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"全身放松，目视来球静中带动\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"步法练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一练习要规范\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"统一练习不走样\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合练习要连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带球练习进实战\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚型练习应规范严格\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单人练习要协调连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合练习要放松自如\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合行进练习要结合步伐\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"触球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人触球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人触球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人互打动触球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带球法与实战结合的触球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合式综合性触球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"各项踢球技术的基础\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本战术\\\",\\\"进攻战术\\\",\\\"防守战术\\\",\\\"高举高打型\\\",\\\"快球进攻型\\\",\\\"中路进攻型\\\",\\\"四边路进攻型\\\",\\\"自调进攻型\\\",\\\"背溜进攻型\\\",\\\"掩护进攻型\\\",\\\"交叉进攻型\\\",\\\"技术训练\\\",\\\"准备姿势\\\",\\\"移动\\\",\\\"步法练习\\\",\\\"踢球练习\\\",\\\"脚型练习\\\",\\\"触球练习\\\",\\\"传球练习\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":8254,\\\"Text\\\":\\\"毽球基本战术是毽球队员在比赛中将各项基本技术相互配合的综合运用。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":8990,\\\"End\\\":20310,\\\"Text\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分，进攻战术的技术配备有单一倒钩型配备。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":5,\\\"Start\\\":46250,\\\"End\\\":59607,\\\"Text\\\":\\\"进攻战术的阵容配备有以下三种：一一二阵容、二二一阵容和三三三阵容。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":6,\\\"Start\\\":60830,\\\"End\\\":67390,\\\"Text\\\":\\\"进攻战术的打法配备有多种，其中包括高举高打型。\\\"},{\\\"Id\\\":5,\\\"SentenceId\\\":40,\\\"Start\\\":413510,\\\"End\\\":420830,\\\"Text\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，应与实战紧密结合进行。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.13368736,\\\"Lecture\\\":0.28069776,\\\"Meeting\\\":0.5856148}}\"', '<p>本人拥有坚实的专业基础和丰富的实践经验。在项目开发过程中，我热衷于编写强类型、高可读性和高可维护性的代码，能够灵活运用所学知识，从需求分析到系统实现全程参与，积累了完整的项目经验，展现出较强的学习与实践能力。<br>在团队协作方面，我曾担任班级副班长，负责管理班级事务；同时作为学院组织部成员，承担学生档案管理工作，展现出优秀的组织协调与沟通能力。<br>性格开朗，善于与人相处，具备强烈的团队荣誉感和责任感，能够快速适应新环境并主动学习新知识，拥有较强的综合能力。</p>', '已完成', '2025-05-19 11:32:41', '2025-05-21 02:46:30', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (191, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E6%88%98%E6%9C%AF%E6%AD%A5%E6%B3%95%E8%B8%A2%E7%90%83%E7%BB%83%E4%B9%A0.mp4', '5af4e813108c4ae5badc5fdcf6be815d', '视频笔记分析任务01', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":147768,\\\"Headline\\\":\\\"毽球基本战术与技术训练解析\\\",\\\"Summary\\\":\\\"毽球的基本战术分为进攻和防守两部分。进攻战术包括单一倒钩型、踩踏型及综合型配备，阵容配置有1-1-2、2-2-1、3-3-3等三种形式，打法多样，如高举高打、快攻、中路进攻等。防守战术则有小弧形、一拦二防、拦堵结合和二拦一防四种基本阵型。技术训练是毽球训练的基础，强化每一项技术对于发展毽球技能至关重要。\\\"},{\\\"Id\\\":2,\\\"Start\\\":148360,\\\"End\\\":307370,\\\"Headline\\\":\\\"毽球运动员步法训练方法解析\\\",\\\"Summary\\\":\\\"毽球运动员在场上的移动始于准备姿势，通过五步法进行脚距测量和站位调整，包括双脚与肩同宽站立、外转脚掌、内八字站位、降低重心和全身放松等步骤。单人练习熟练后，应进一步体会用脚尖内侧快速蹬地的感觉。步法训练是毽球运动员比赛中的基本功，应遵循从简单到复杂、由单一到综合的原则，并结合带球练习，以确保人与球的最佳位置调整。\\\"},{\\\"Id\\\":3,\\\"Start\\\":323530,\\\"End\\\":460090,\\\"Headline\\\":\\\"足球踢球与传球技术训练方法\\\",\\\"Summary\\\":\\\"介绍了足球训练中踢球和传球技术的基础练习，包括正确的脚型使用、单人与双人练习、隔网对踢、触球练习以及结合实战的综合性训练，强调了这些练习对于提升足球技能的重要性。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球训练涵盖基本战术、技术和移动技巧。战术分为进攻与防守，进攻包括单一倒钩型、单一踩踏型、倒钩踩踏综合型及三种阵容和八种打法配备；防守有四种基本阵型。技术训练基础为准备姿势五步法、步法练习及踢球、触球、传球等基本功，遵循从单人到综合再到带球实战的训练原则。移动技巧始于准备姿势，通过规范步法调整至最佳位置。训练强调从基础到综合再到实战的应用。\\\",\\\"ParagraphTitle\\\":\\\"毽球战术、技术和移动技巧训练概述\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"详细阐述了毽球基本战术的构成与分类，强调了进攻与防守战术的多样性。进攻战术包括单一倒钩型、单一踩踏型及倒钩踩踏综合型配备，阵容配备分为一一二、221、333三种，打法配备涵盖高举高打型、快球进攻型等八种类型。防守战术则有小弧形、一篮二防等四种基本阵型。他特别强调了技术训练的重要性，指出准备姿势的五个步骤、步法、踢球和触球练习是基本功的关键，训练应遵循从单人到综合再到实战的原则。此外，他还提到了多种形式的练习，包括单人、双人、隔网对踢、组合式综合触球练习以及传球练习，认为这些是踢球技术的基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球基本战术包含哪些部分以及进攻战术有哪些配备和技术？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分。在进攻战术中，技术配备有单一倒钩型、单一踩踏型以及倒钩踩踏综合型。此外，进攻战术的阵容配备有三种形式，分别是“一一二”阵容配备、“221”阵容配备和“333”阵容配备。具体的打法配备包括高举高打型、快球进攻型、中路进攻型、四边路进攻型、自调进攻型、背溜进攻型、掩护进攻型和交叉进攻型。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,5,6]},{\\\"Question\\\":\\\"毽球防守战术有多少种基本防守阵型？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14,15,16],\\\"Answer\\\":\\\"毽球防守战术共有四种基本防守阵型，分别是“一小弧形防守阵型”，“二一篮二防防守阵型”，“三拦堵防防守阵型”，以及“四二兰一防防守阵型”。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14,15,16]},{\\\"Question\\\":\\\"毽球运动员如何进行准备姿势训练，并描述了哪几种常见的准备姿势？\\\",\\\"SentenceIdsOfQuestion\\\":[17,18,19,20,21,22],\\\"Answer\\\":\\\"毽球运动员在场上比赛时的移动都是从准备姿势开始的。一般准备姿势的脚距丈量应因人而异，可分五步进行。具体为：第一步，两脚与肩同宽，平行开立；第二步，以脚跟为轴，两脚掌外转接近平行；第三步，以脚尖为轴，两脚跟外移呈内八字形站位；第四步，重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前；第五步，全身放松，目视来球。待单人练习成型后，可要求一步到位，体会用脚尖内侧迅速发力蹬地，重心被推移的感觉。\\\",\\\"SentenceIdsOfAnswer\\\":[17,18,19,20,21,22]},{\\\"Question\\\":\\\"步法练习对于毽球运动员的重要性以及训练原则是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[25,26,27,28],\\\"Answer\\\":\\\"步法练习是毽球运动员临场比赛的一大基本功，它确保了人与球的最佳位置。在训练中应贯彻单一练习要规范，统一练习不走样，综合练习要连贯，带球练习进实战的原则。\\\",\\\"SentenceIdsOfAnswer\\\":[25,26,27,28]},{\\\"Question\\\":\\\"踢球练习（传球训练）的基础和技术要求是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[32,33,34],\\\"Answer\\\":\\\"踢球练习是传球训练的基础，也是一项重要的基本功。脚型练习应规范严格，单人练习要协调连贯，组合练习要放松自如，综合行进练习要结合步伐。\\\",\\\"SentenceIdsOfAnswer\\\":[32,33,34]},{\\\"Question\\\":\\\"触球练习在毽球训练中的地位及其结合实战的方式是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[40,41,42,43,44],\\\"Answer\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，应与实践紧密结合进行。可以通过单人触踢球练习、双人触踢球练习、隔网对踢练习等多种形式进行，并结合实战进行触球练习，如代步法与实战结合的触踢球练习以及组合式综合性触球练习。\\\",\\\"SentenceIdsOfAnswer\\\":[40,41,42,43,44]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本战术与技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"毽球基本战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"进攻战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一倒钩型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单一踩踏型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"倒钩踩踏综合型配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"阵容配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一一二阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"221阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"333阵容配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"打法配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"高举高打型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快球进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"中路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"四边路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"自调进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"背溜进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"掩护进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"交叉进攻型\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本防守阵型\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小弧形防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"一篮二防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"拦堵防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"四二兰一防防守阵型\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"准备姿势与移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"五步进行\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两脚与肩同宽，平行开立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚跟为轴，两脚掌外转接近平行\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚尖为轴，两脚跟外移，呈内八字形站位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"全身放松，目视来球静中带动\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"步法练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一练习要规范\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"统一练习不走样\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合练习要连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带球练习进实战\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚型练习应规范严格\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单人练习要协调连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合练习要放松自如\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合行进练习要结合步伐\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"触球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人互打杂触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"代步法与实战结合的触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合式综合性触球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"各项踢球技术的基础\\\",\\\"Topic\\\":[]}]}]}]}}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本战术\\\",\\\"进攻战术\\\",\\\"防守战术\\\",\\\"高举高打型\\\",\\\"快球进攻型\\\",\\\"中路进攻型\\\",\\\"四边路进攻型\\\",\\\"自调进攻型\\\",\\\"背溜进攻型\\\",\\\"掩护进攻型\\\",\\\"交叉进攻型\\\",\\\"技术训练\\\",\\\"准备姿势\\\",\\\"移动\\\",\\\"步法练习\\\",\\\"踢球练习\\\",\\\"脚型练习\\\",\\\"触球练习\\\",\\\"传球练习\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":8254,\\\"Text\\\":\\\"毽球基本战术就是毽球队员在比赛中将各项基本技术相互配合的组合运用。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":8990,\\\"End\\\":20310,\\\"Text\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分，进攻战术的技术配备有单一倒钩型。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":5,\\\"Start\\\":46250,\\\"End\\\":59607,\\\"Text\\\":\\\"进攻战术的阵容配备有以下三种：一一二阵容、二二一阵容、三三三阵容。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":6,\\\"Start\\\":60830,\\\"End\\\":67390,\\\"Text\\\":\\\"进攻战术的打法配备有多种，第一种是高举高打型。\\\"},{\\\"Id\\\":5,\\\"SentenceId\\\":40,\\\"Start\\\":413510,\\\"End\\\":420830,\\\"Text\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，应与实战紧密结合进行。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.13368736,\\\"Lecture\\\":0.28069776,\\\"Meeting\\\":0.5856148}}\"', '准备姿势：在接近球之前，保持身体放松，两脚与肩同宽站立。确保非踢球脚（支撑脚）位于球的一侧，大约距离球一脚远的位置，这样可以给踢球腿留出足够的摆动空间。\n\n支撑脚的放置：将支撑脚指向你想要踢球的方向，并且稍微弯曲膝盖以增加稳定性。支撑脚应大致与球平行或略微偏前一点。\n\n踢球腿的动作：\n\n从后方开始向前摆动踢球腿。\n当踢球腿接近球时，用大腿带动小腿快速加速。\n在接触球的瞬间，尽量使脚踝保持固定状态，使用脚内侧（即足弓部分）来击打球。\n击球点：理想的击球位置是在球的中心稍偏下一点的地方。这样可以帮助提高球的速度和方向控制。\n\n随球动作：完成击球后，踢球腿继续沿着目标方向跟随出去，这有助于保持踢球的力量和准确性。同时，上半身也可以随着踢球的方向转动，以增加整体力量。', '已完成', '2025-05-19 12:45:43', '2025-05-19 12:48:24', 32, 32, 0);
INSERT INTO `ai_note_info` VALUES (192, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E6%88%98%E6%9C%AF%E6%AD%A5%E6%B3%95%E8%B8%A2%E7%90%83%E7%BB%83%E4%B9%A0.mp4', 'ea914a1e855b41668e050fefd9239dc7', '视频笔记分析任务101', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":147768,\\\"Headline\\\":\\\"毽球基本战术与技术训练解析\\\",\\\"Summary\\\":\\\"毽球的基本战术分为进攻和防守两部分。进攻战术包括单一倒钩型、踩踏型及综合型配备，阵容配备有1-1-2、2-2-1、3-3-3等三种形式，打法多样，如高举高打、快球进攻、中路进攻等。防守战术则有小弧形、一拦二防、拦堵防和二拦一防四种基本阵型。技术训练是毽球训练的基础，强化每一项技术是未来发展的关键。\\\"},{\\\"Id\\\":2,\\\"Start\\\":148360,\\\"End\\\":307370,\\\"Headline\\\":\\\"毽球运动员的步法训练方法\\\",\\\"Summary\\\":\\\"毽球运动员在场上的移动始于准备姿势，通过五步法进行训练，包括双脚与肩同宽站立、脚掌外转、脚跟向外移动形成内八字、降低重心并前倾、全身放松并目视来球。步法练习是基本功之一，用于调整人与球的最佳位置。训练原则包括单一练习的规范性、统一练习的一致性、综合练习的连贯性以及带球练习的实际应用。\\\"},{\\\"Id\\\":3,\\\"Start\\\":323530,\\\"End\\\":460090,\\\"Headline\\\":\\\"足球踢球与传球技术训练方法\\\",\\\"Summary\\\":\\\"介绍了足球训练中的踢球和传球技术的基础练习，包括正确的脚型、单人与双人练习、隔网对踢、触球练习以及结合实战的综合性训练，强调了这些练习对于提升足球技能的重要性。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球战术分为进攻和防守两部分。进攻战术包括单一倒钩型、单一踩踏型和倒钩踩踏综合型技术配备，以及一一二、221、333三种阵容配备，还有多种打法如高举高打、快球进攻等。防守战术有小弧形、一篮二防、拦堵防、二拦一防四种基本阵型。技术训练是毽球训练的基础，强调基本功的重要性，包括运动员的移动、步法练习、踢球练习和触球练习。训练原则为单一练习规范、统一练习一致、综合练习连贯、带球练习实战。整个训练过程包括单人、双人、隔网对踢和组合式综合触球练习，旨在全面提升运动员的技术水平和实战能力。\\\",\\\"ParagraphTitle\\\":\\\"毽球战术、技术和训练方法综述\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"详细阐述了毽球基本战术的构成与分类，强调了进攻与防守战术的多样性。进攻战术包括单一倒钩型、单一踩踏型及倒钩踩踏综合型配备，阵容配备分为一一二、221、333三种，打法配备涵盖高举高打型、快球进攻型等八种类型。防守战术则有小弧形、一篮二防等四种基本阵型。他特别强调了技术训练的重要性，指出准备姿势的五个步骤、步法练习、踢球练习和触球练习是基本功的基石。训练原则应遵循单一练习规范、统一练习不走样、综合练习连贯和带球练习进实战。此外，他介绍了单人、双人、隔网对踢和综合行进练习等不同形式的练习，强调传球练习是踢球技术的基础，触球练习与实践的结合至关重要。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球基本战术包含哪些部分以及进攻战术有哪些配备和技术？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分。在进攻战术中，技术配备有单一倒钩型、单一踩踏型以及倒钩踩踏综合型。此外，进攻战术的阵容配备有三种形式，分别是“一一二”阵容配备、“221”阵容配备和“333”阵容配备。具体的打法配备包括高举高打型、快球进攻型、中路进攻型、四边路进攻型、自调进攻型、背溜进攻型、掩护进攻型和交叉进攻型。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,5,6]},{\\\"Question\\\":\\\"毽球防守战术有哪四种基本防守阵型？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14,15,16],\\\"Answer\\\":\\\"毽球防守战术有四种基本防守阵型，分别是“小弧形”防守阵型、“一篮二防”防守阵型、“拦堵防”防守阵型和“二拦一防”防守阵型。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14,15,16]},{\\\"Question\\\":\\\"如何进行毽球运动员的准备姿势训练？\\\",\\\"SentenceIdsOfQuestion\\\":[17,18,19,20,21,22],\\\"Answer\\\":\\\"毽球运动员在场上比赛时的移动都是从准备姿势开始的。一般准备姿势的脚距丈量应因人而异，通常包括五步进行法：两脚与肩同宽平行开立，以脚跟为轴两脚掌外转接近平行，以脚尖为轴两脚跟外移呈内八字形站位，重心下降上体稍前倾，膝关节内扣，两手臂自然弯曲于体前，全身放松目视来球。待单人练习成型后，要求一步到位并体会用脚尖内侧迅速发力蹬地的感觉。\\\",\\\"SentenceIdsOfAnswer\\\":[17,18,19,20,21,22]},{\\\"Question\\\":\\\"步法练习在毽球运动中的重要性和训练原则是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[25,26,27,28],\\\"Answer\\\":\\\"步法练习是毽球运动员临场比赛的一大基本功，它确保人与球的最佳位置。训练中应坚持单一练习要规范统一，综合练习要连贯，带球练习进实战的原则。\\\",\\\"SentenceIdsOfAnswer\\\":[25,26,27,28]},{\\\"Question\\\":\\\"踢球练习（传球训练）的基础和训练要点是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[32,33,34],\\\"Answer\\\":\\\"踢球练习是传球训练的基础，也是一项重要的基本功。其中，脚型练习需规范严格，单人练习要求协调连贯，组合练习需放松自如，综合行进练习则需结合步伐。\\\",\\\"SentenceIdsOfAnswer\\\":[32,33,34]},{\\\"Question\\\":\\\"触球练习为何是不可或缺的过渡性技术训练，如何与实践结合进行？\\\",\\\"SentenceIdsOfQuestion\\\":[40,41,42,43,44],\\\"Answer\\\":\\\"触球练习是一项与实践紧密结合的过渡性技术训练，包括单人触踢球练习、双人触踢球练习、隔网对踢练习以及代步法与实战结合的触踢球练习，还有组合式综合性触球练习等。\\\",\\\"SentenceIdsOfAnswer\\\":[40,41,42,43,44]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本战术与技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"毽球基本战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"进攻战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一倒钩型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单一踩踏型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"倒钩踩踏综合型配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"阵容配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一一二阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"221阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"333阵容配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"打法配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"高举高打型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快球进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"中路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"四边路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"自调进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"背溜进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"掩护进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"交叉进攻型\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本防守阵型\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小弧形防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"一篮二防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"拦堵防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"二拦一防防守阵型\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"准备姿势与移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"五步进行\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两脚与肩同宽，平行开立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚跟为轴，两脚掌外转接近平行\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚尖为轴，两脚跟外移，呈内八字形站位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"全身放松，目视来球静中带动\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"步法练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一练习要规范\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"统一练习不走样\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合练习要连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带球练习进实战\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚型练习应规范严格\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单人练习要协调连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合练习要放松自如\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合行进练习要结合步伐\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"触球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人互打杂触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"代步法与实战结合的触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合式综合性触球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"各项踢球技术的基础\\\",\\\"Topic\\\":[]}]}]}]}}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本战术\\\",\\\"进攻战术\\\",\\\"防守战术\\\",\\\"高举高打型\\\",\\\"快球进攻型\\\",\\\"中路进攻型\\\",\\\"四边路进攻型\\\",\\\"自调进攻型\\\",\\\"背溜进攻型\\\",\\\"掩护进攻型\\\",\\\"交叉进攻型\\\",\\\"技术训练\\\",\\\"准备姿势\\\",\\\"移动\\\",\\\"步法练习\\\",\\\"踢球练习\\\",\\\"脚型练习\\\",\\\"触球练习\\\",\\\"传球练习\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":8254,\\\"Text\\\":\\\"毽球基本战术就是毽球队员各项基本技术在比赛实战中的相互配合和组合运用。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":8990,\\\"End\\\":20310,\\\"Text\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分，进攻战术的技术配备有单一倒钩型。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":5,\\\"Start\\\":46250,\\\"End\\\":59607,\\\"Text\\\":\\\"进攻战术的阵容配备有以下三种：一一二阵容、二二一阵容和三三三阵容。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":6,\\\"Start\\\":60830,\\\"End\\\":67390,\\\"Text\\\":\\\"进攻战术的打法配备有多种，其中包括高举高打型。\\\"},{\\\"Id\\\":5,\\\"SentenceId\\\":40,\\\"Start\\\":413510,\\\"End\\\":420830,\\\"Text\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，应与实践紧密结合进行。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.13368736,\\\"Lecture\\\":0.28069776,\\\"Meeting\\\":0.5856148}}\"', '<ol><li>进攻战术中的技术配备：包括单一倒钩型、单一踩踏型以及倒钩踩踏综合型。</li><li>进攻战术的阵容配置：可采用一一二（1-1-2）阵容、二二一（2-2-1）阵容或三三三（3-3-3）阵容。</li><li>进攻战术的打法策略：涵盖高举高打、快球进攻、中路突破、四边路进攻、自调进攻、背溜进攻、掩护进攻及交叉进攻等多种方式。</li><li>防守战术的基本阵型：主要有小弧形布局、一拦二防模式、拦堵防御体系和二拦一防结构等。</li><li>准备姿势与移动技巧：保持两脚与肩同宽站立，同时使脚掌略微向外旋转。</li></ol>', '已完成', '2025-05-19 12:52:59', '2025-05-21 02:46:17', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (193, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E8%8A%B1%E6%AF%BD-%E6%8B%90%E8%B8%A2-%E8%B7%B3%E8%B8%A2-%E8%90%BD%E8%B8%A2-%E6%8A%B9%E8%B8%A2-%E8%B9%81%E8%B8%A2.mp4', '91a5b0b7f7f748149e2f2c8014683f04', '科学的动作的技巧和要领', '\"[{\\\"Id\\\":1,\\\"Start\\\":5210,\\\"End\\\":202790,\\\"Headline\\\":\\\"花毽基本动作教学：盘踢、磕踢和崩踢\\\",\\\"Summary\\\":\\\"介绍了花毽运动中盘踢、磕踢和崩踢三个基本动作的技巧和要领，包括膝关节外展、脚内侧端平、大腿发力等关键点，旨在帮助花毽爱好者更好地掌握这些技术。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"国家级社会体育指导员穆丹介绍了花毽运动的起源可追溯至汉代，东汉山东济宁出土的画像砖上已有相关图案记载。到唐宋时期，花毽的基本技术已有图形记载。她详细讲解了花毽的三个基本动作：盘踢、磕踢和崩踢，分别用双脚内侧、大腿靠近膝关节的部位和脚背踢毽，并强调了练习这些动作时需掌握的技巧。此指导视频由中国社会体育指导员协会与中国篮球协会共同录制，旨在提供科学健身公益指导。\\\",\\\"ParagraphTitle\\\":\\\"国家级社会体育指导员详解花毽运动历史与基本技巧\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"作为国家级社会体育指导员，穆丹介绍了踢毽运动的历史起源及其在唐宋时期的发展，指出踢毽起源于汉代，并在东汉画像砖中已有簇毛丸的图案。她向广大社会体育指导员和健身爱好者详细讲解了花毽基本动作中的盘踢、磕踢和崩踢。盘踢是用双脚内侧交换踢毽，要求膝关节外展，手臂自然下垂，依靠膝关节和小腿发力向上摆动，用足内侧将毽子踢至胸前。磕踢则是用大腿靠近膝关节的部位踢毽，要求上身直立，大腿抬起，小腿自然下垂。崩踢则是大腿稍抬起，小腿向正上方摆动，脚面触键，踝关节稍发力，将毽子踢起。她希望通过此次科学健身公益指导视频，为广大花毽爱好者提供帮助，强调了每个动作的技术要点，以期提升大家的踢毽技能和健身效果。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"花毽运动起源于何时，其历史发展如何？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5,6],\\\"Answer\\\":\\\"花毽运动起源于汉代，从山东济宁出土的东汉画像砖中可以找到簇毛丸的图案。到了唐宋时期，花毽的部分基本技术已经有了图形记载。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5,6]},{\\\"Question\\\":\\\"盘踢作为花毽基本动作，具体是如何进行的？盘踢的技术要点有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[7,8,9,10,11],\\\"Answer\\\":\\\"盘踢是用双脚内侧交替踢毽，执行时膝关节外展，手臂自然下垂，依靠膝关节和小腿发力向上摆动，用足内侧将毽子踢至胸前。同时，身体保持直立，双手放于体前，手心朝下，脚带动小腿发力完成踢腿动作。练习盘踢时，需要掌握以下两点技巧：一是确保脚内侧端平，使毽子下落至腰部位置；二是脚带动小腿向上翻转，以正确执行踢毽动作。\\\",\\\"SentenceIdsOfAnswer\\\":[7,8,9,10,11]},{\\\"Question\\\":\\\"磕踢（又称科踢）的动作要如何完成？\\\",\\\"SentenceIdsOfQuestion\\\":[7,8,9,10,11],\\\"Answer\\\":\\\"磕踢要求上身直立，大腿抬起接近膝关节，触键时与身体呈90度角，小腿自然下垂，脚尖朝地。利用膝关节带动大腿处发力，双手指尖相对放于腹前，膝关节带动大腿撞击手心，脚尖朝下绷直，手持毽子靠近膝关节的位置触键，膝关节带动大腿发力，脚尖朝下将毽子向前翻滚。\\\",\\\"SentenceIdsOfAnswer\\\":[12,13,14]},{\\\"Question\\\":\\\"崩踢动作是如何执行的？\\\",\\\"SentenceIdsOfQuestion\\\":[15,16],\\\"Answer\\\":\\\"崩踢是用脚背踢毽，执行时大腿稍抬起，小腿向正上方摆动，脚面触键，踝关节稍发力将毽子踢起，随后大腿抬起带动小腿发力，脚尖同时挑起，用足三指辅助踢键，将毽子向前翻滚。\\\",\\\"SentenceIdsOfAnswer\\\":[15,16]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"花毽基本动作与技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"起源与发展\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"踢毽起源于汉代\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"东汉画像砖中已有簇毛丸图案\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"唐宋时期，花毽部分基本技术已有图形记载\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚内侧交替踢毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"技巧要点:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"膝关节外展，手臂自然下垂\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"膝关节、小腿发力向上摆动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"足内侧将毽子踢至胸前\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚内侧端平，毽子下落至腰部位置\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚带动小腿向上翻转\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"磕踢（又称科踢）\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿靠近膝关节部位踢毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"技巧要点:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"上身直立，大腿抬起与身体呈90度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿自然下垂，脚尖朝地面\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"膝关节带动大腿撞击，脚尖朝下绷直\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"手持毽子靠近膝关节位置触键\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"膝关节带动大腿发力，脚尖朝下\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"崩踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚背踢毽\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"技巧要点:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿稍抬起，小腿向正上方摆动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚面触键，踝关节稍发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"大腿抬起带动小腿发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚尖同时挑起，用足三趾辅助踢键\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"结语\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"以上为花毽运动中的盘踢、磕踢和崩踢动作展示及技术要点\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"目的：帮助广大花毽爱好者掌握技术要领\\\",\\\"Topic\\\":[]}]}]}}\"', '\"{\\\"Keywords\\\":[\\\"踢毽\\\",\\\"汉代\\\",\\\"东汉画像砖\\\",\\\"唐宋时期\\\",\\\"健身爱好者\\\",\\\"盘踢\\\",\\\"崩提\\\",\\\"膝关节外展\\\",\\\"足内侧\\\",\\\"身体直立\\\",\\\"大腿抬起\\\",\\\"小腿发力\\\",\\\"脚尖朝前\\\",\\\"脚背踢\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":2,\\\"Start\\\":14900,\\\"End\\\":20330,\\\"Text\\\":\\\"到唐宋时期，踢毽的基本技术已经有所图形记载。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.18993779,\\\"Lecture\\\":0.57687116,\\\"Meeting\\\":0.23319101}}\"', '<p>视频中介绍了花毽运动中的三个基本动作，分别是： &nbsp;</p><ol><li>盘踢：用双脚内侧交替踢毽。执行时膝关节外展，手臂自然下垂，依靠膝关节和小腿的力量向上摆动，用足内侧将毽子踢至胸前。关键在于保持脚内侧平整，使毽子落在腰部高度；同时通过脚带动小腿向上翻转完成踢毽动作。 &nbsp;</li><li>磕踢（或称科踢）：利用大腿靠近膝关节的部位踢毽。要求上身保持直立，大腿抬起接近膝关节位置时与身体形成约90度角，小腿自然下垂，脚尖指向地面。通过膝关节带动大腿发力，双手指尖相对放在腹部前方。当膝关节带动大腿撞击手心时，脚尖朝下绷直，并用手持毽子靠近膝关节的位置触键，再由膝关节带动大腿发力使毽子向前翻滚。 &nbsp;</li><li>崩踢：这是用脚背进行踢毽的动作。执行时大腿稍微抬高，小腿向正上方摆动，脚面接触毽子，踝关节稍加力道将毽子踢起。接着大腿继续上升带动小腿施力，脚尖同时挑起，用足部三指辅助踢键，使得毽子能够向前翻滚。<br>这三个动作都是花毽运动中非常基础且重要的技巧。对于希望提高自己踢毽水平的朋友来说，掌握这些技术是非常有帮助的。</li></ol><p><br></p><p><br></p><p><br></p>', '已完成', '2025-05-19 13:36:23', '2025-07-30 10:26:16', 1, 1, 0);
INSERT INTO `ai_note_info` VALUES (194, NULL, NULL, 'https://lxzj.tenir.cn/lxzj/files/2025/04/7ee0d5ea9278453ebefaeab7d44172b2.mp4', '6361f0d15ba54dc2af252db4c05f4c0e', '视频笔记分析任务121', NULL, NULL, NULL, '<p><br></p>', '已完成', '2025-05-22 07:01:47', '2025-05-22 09:20:49', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (195, NULL, NULL, 'https://lxzj.tenir.cn/lxzj/files/2025/04/7ee0d5ea9278453ebefaeab7d44172b2.mp4', 'f7e6b8dafb5942949b6782ebc55ac419', '视频笔记分析任务121', NULL, NULL, NULL, '<p><br></p>', '已完成', '2025-05-22 07:01:47', '2025-05-22 07:01:54', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (196, NULL, NULL, 'https://www.tenir.cn/video/%E6%B5%8B%E8%AF%95%E8%A7%86%E9%A2%91%E5%B8%A6%E5%AD%97%E5%B9%95.mp4', 'd80ee55c07744ad7ae523f17ae2b388a', '视频笔记分析任务141', '\"[{\\\"Id\\\":1,\\\"Start\\\":1270,\\\"End\\\":142240,\\\"Headline\\\":\\\"2025年毽球基本动作教学指南\\\",\\\"Summary\\\":\\\"本指南详细介绍了四种毽球基本动作的练习方法，包括一脚内侧踢球、脚外侧踢球、正脚背踢球以及大腿触球。每种动作都要求双脚自然分开，屈膝微微下蹲，通过抬大腿、收小腿等步骤，重点讲解了单脚和双脚练习的具体技巧。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本内容深入解析了足球运动中的四种基本踢球动作：内侧踢球、外侧踢球、正脚背踢球和大腿触球。针对每种技巧，提供了详细的步骤指导，包括站立姿势、膝部弯曲、大腿抬升、小腿动作调整、脚尖控制及脚踝灵活性等关键点。同时，介绍了单脚和双脚的练习方法，强调在踢球过程中保持正确的身体姿势和脚部动作的重要性。\\\",\\\"ParagraphTitle\\\":\\\"足球基础踢球技巧详解与练习方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他详细介绍了四种基本的足球踢球动作及其练习方法。首先，一脚内侧踢球，要点为双脚自然开立，屈膝下蹲，通过抬大腿、甩小腿，保持脚端平，进行单双脚内侧踢球练习。其次，脚外侧踢球，同样保持双脚自然开立，屈膝下蹲，重心在支撑腿上，抬大腿，收小腿，勾脚尖，脚端平，进行单脚外侧踢球练习。接着，正脚背踢球，动作包括双脚自然开立，屈膝下蹲，大腿带动小腿上抬，踝关节放松，脚尖抖动，进行单脚正脚背踢球练习。最后，大腿触球练习，虽然未详细说明，但可推测为通过大腿接触球来提高控球技巧。他强调了每种动作的要领，旨在帮助学习者掌握正确的足球踢球技巧。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在足球训练中，如何进行单脚内侧踢球的练习？如何进行大腿触球训练？\\\",\\\"SentenceIdsOfQuestion\\\":[2,3],\\\"Answer\\\":\\\"单脚内侧踢球练习时，需保持双脚自然开立，屈膝微微下蹲，抬大腿，然后以脚端平的方式进行踢球。虽然没有明确解释如何进行大腿触球训练，但根据上下文可以推断出这是一种通过大腿接触球来训练球感和控制能力的训练方式。\\\",\\\"SentenceIdsOfAnswer\\\":[2,3]},{\\\"Question\\\":\\\"双脚内侧踢球练习的正确姿势是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"双脚内侧踢球练习要求双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，同时抬大腿、收小腿并勾脚尖，确保脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"单脚外侧踢球练习的要点是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[5],\\\"Answer\\\":\\\"单脚外侧踢球练习需要保持双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，抬大腿，收小腿，勾脚尖，保证脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"正脚背踢球练习时，身体应如何准备？\\\",\\\"SentenceIdsOfQuestion\\\":[8],\\\"Answer\\\":\\\"进行正脚背踢球练习时，需双脚自然开立，屈膝微微下蹲，大腿带动小腿屈膝上抬踝关节，放松脚尖并抖动脚踝。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"足球基本动作练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一脚内侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，甩小腿，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚内侧踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双脚内侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"脚外侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心落在支撑腿上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，收小腿，勾脚尖，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚外侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"正脚背踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝，微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"大腿带动小腿屈膝上抬\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踝关节放松，脚尖抖动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚正脚背踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"大腿触球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"(具体动作描述未给出，但可理解为使用大腿部位接触球进行控制或传球练习)\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"一脚内侧踢球\\\",\\\"双脚自然开立\\\",\\\"屈膝微微下蹲\\\",\\\"抬大腿\\\",\\\"脚端平\\\",\\\"脚外侧踢球\\\",\\\"收小腿\\\",\\\"勾脚尖\\\",\\\"三正脚背踢球\\\",\\\"大腿带动小腿\\\",\\\"屈膝上抬\\\",\\\"踝关节\\\",\\\"放松脚尖\\\",\\\"抖动脚踝\\\",\\\"四大腿触球\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":10,\\\"Start\\\":112960,\\\"End\\\":121990,\\\"Text\\\":\\\"大腿带动小腿，屈膝上抬，踝关节放松，脚尖抖动。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.019431012,\\\"Lecture\\\":0.92815834,\\\"Meeting\\\":0.052410584}}\"', '<p><br></p>', '已完成', '2025-05-22 09:22:15', '2025-05-22 09:25:30', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (197, NULL, NULL, 'https://lxzj.tenir.cn/lxzj/files/course/课程信息/常识篇-基本知识和基本动作/427937764-1-16.mp4', '3e0b2f5e43d44c79b640b4cf97104785', '画质 训练视频分析', '\"[{\\\"Id\\\":1,\\\"Start\\\":44050,\\\"End\\\":274920,\\\"Headline\\\":\\\"毽球运动的发展与基本规则介绍\\\",\\\"Summary\\\":\\\"毽球运动起源于汉代，至今已有1500多年的历史，深受青少年喜爱。现代毽球融合了个人技艺与集体攻防，兼具娱乐性和竞技性。毽球由箭毛和毽垫组成，全国正式比赛用球由中国江苏太仓毽球场生产。毽球场地长12米，宽6米，中线两侧各2米为限制区，端线中点两侧各1米为发球区。每队上场六名队员，一方最多拥有三人四次击球的机会，一名队员不得连续击球三次。比赛中，队员不得触网或过网击球。毽球比赛结合了羽毛球的场地、排球的规则、足球的脚法以及踢毽子的技巧，深受中国人民喜爱。\\\"},{\\\"Id\\\":2,\\\"Start\\\":299150,\\\"End\\\":792100,\\\"Headline\\\":\\\"毽球基础技巧与发球战术详解\\\",\\\"Summary\\\":\\\"介绍了毽球运动中的两种准备姿势、八种步伐移动技巧，以及如何使用脚内外侧、脚背和身体不同部位触球和踢球的方法。特别详细讲解了发球的三种方式，包括脚内侧、正脚背和脚外侧发球的特点与技巧，强调发球在比赛中的进攻性和战术意义。\\\"},{\\\"Id\\\":3,\\\"Start\\\":810400,\\\"End\\\":1437480,\\\"Headline\\\":\\\"毽球基本功与战术详解\\\",\\\"Summary\\\":\\\"内容详细介绍了毽球中的基本功，包括传踢球、攻球（头攻球、倒钩攻、脚踏攻）的不同技巧与特性，以及防守技术如拦网、封堵和角防的运用。此外，还涉及了进攻战术和防守战术的组合应用，强调了技术在实战中的重要性。\\\"},{\\\"Id\\\":4,\\\"Start\\\":1447780,\\\"End\\\":1948070,\\\"Headline\\\":\\\"毽球运动的进攻与防守战术分析\\\",\\\"Summary\\\":\\\"对话详细介绍了毽球运动中的三种进攻战术配置，包括一二阵容、二一阵容和三三阵容，以及它们各自的特点和适用场景。同时，讨论了四种防守阵型，即弧形防守阵型、一拦二防阵型、爱尔兰一防阵型和拦堵防守阵型，分析了它们的优缺点及应对策略。最后，提到毽球运动的发展及其在国际体育交流中的作用，表达了对中国毽球未来发展的信心。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球起源于中国古代，拥有超过1500年的历史，深受各年龄段人群喜爱，尤其受到青少年的欢迎。作为一项融合个人技巧与集体攻防的运动，现代毽球既具娱乐性又具竞技性，已成为新兴体育项目之一。毽球由箭茅和肩垫组成，正式比赛用球产自中国江苏太仓建球场。比赛遵循特定规则，包括场地、球网设置，以及队员数量、击球次数限制和得分方式等。基本动作涵盖准备姿势、步伐移动和踢球技巧，而高级技战术则包括发球、传踢球、攻球和防守技术。根据不同阵容配备，还存在多样化的进攻和防守战术。毽球运动在保留传统魅力的同时，展现出新颖风采，吸引了全球越来越多的参与者，中国毽球队也在国际体育交流中展现了中华民族体育的荣耀。\\\",\\\"ParagraphTitle\\\":\\\"毽球运动的历史、发展与现代竞技规则\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他首先介绍了毽子作为中国传统的民族体育项目，其历史悠久，起源于汉代，至今已有1500多年的历史，且在各年龄段人群中深受欢迎。他指出，现代毽球运动是在传统踢毽子的基础上发展而来，融合了娱乐性和竞技性，不仅提升了健身效果，也增加了观赏价值，已成为现代竞技体育的一部分。为了适应毽球运动的发展，他详细讲解了毽球的基本知识、规则、装备、场地、基本动作和技战术，包括毽球的组成、尺寸、重量，场地规格，比赛规则，以及各种踢球技巧和战术。他强调，毽球比赛融合了羽毛球、排球、足球和传统踢毽子的元素，具有高技巧性、强对抗性、快速度和多变化的特点。此外，他还介绍了准备姿势、步伐移动、击球技巧、发球方法、传踢球、攻球、防守技术等，并讨论了不同阵容配备下的进攻和防守战术。最后，他强调了毽球运动的现代竞技体育地位，以及中国毽球队在国际体育交流中的积极作用，表达了对中国毽球未来发展的信心和期待。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽子这一传统体育项目起源于何时，流传多久？\\\",\\\"SentenceIdsOfQuestion\\\":[1],\\\"Answer\\\":\\\"毽子起源于汉代，至今已有1500多年历史，至今仍深受广大人群喜爱。\\\",\\\"SentenceIdsOfAnswer\\\":[1]},{\\\"Question\\\":\\\"现代毽球运动是如何从踢毽子演变而来的，以及它的特点是什么？毽球比赛的场地尺寸和球网高度是多少？\\\",\\\"SentenceIdsOfQuestion\\\":[2,3],\\\"Answer\\\":\\\"现代毽球运动是在踢毽子的基础上发展起来的，它将个人技艺转变为集体攻防对抗，具有娱乐性和竞技性，并且显著提高了毽球运动的健身作用和观赏价值。毽球比赛场地长12米，宽6米，中线两侧各2米为限制区；端线中点两侧各1米向外场区域为发球区。网长7米，网宽76厘米，男子网高1.6米，女子网高1.5米。\\\",\\\"SentenceIdsOfAnswer\\\":[2,3,11]},{\\\"Question\\\":\\\"毽球的基本技术动作有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"基本技术动作包括准备姿势、步伐移动（如前上步、后撤步、交叉步等）、不同部位触球（如脚内侧踢球、正脚背踢球、脚外侧踢球、单腿触球、双腿触球、腹部触球、胸部触球、头部触球等）以及倒钩球、脚踏球等。\\\",\\\"SentenceIdsOfAnswer\\\":[31,32]},{\\\"Question\\\":\\\"毽球比赛中比赛队的上场人数和击球规则是怎样的？毽球比赛有哪些特点？\\\",\\\"SentenceIdsOfQuestion\\\":[13,14,15,16],\\\"Answer\\\":\\\"比赛队有六名队员上场，三人比赛一方最多有三人四次击球机会。一个队员不得连续三次击球，队员手臂不能碰球，且在限制区内不得用头攻入对方。比赛中不限时，一方先得15分为胜一局，三局两胜。毽球比赛具有技巧性高、对抗性强、球速快和变化多的特点，融合了羽毛球、排球、足球和踢毽子等多种体育项目的元素。\\\",\\\"SentenceIdsOfAnswer\\\":[13,14,15,16]},{\\\"Question\\\":\\\"毽球比赛中常见的发球方式有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[42,43],\\\"Answer\\\":\\\"常见的发球方式有脚内侧发球、正脚背发球、脚外侧发球，每种发球方式都有其特点，如稳定性、准确性或攻击力。\\\",\\\"SentenceIdsOfAnswer\\\":[42,43,45,46,47]},{\\\"Question\\\":\\\"毽球比赛中的主要战术和阵容配备有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[86],\\\"Answer\\\":\\\"主要战术包括进攻战术和防守战术。进攻战术有不同阵容配备，如一二阵容配备（主攻手+二传手）和二一阵容配备（主攻手+副攻手+二传手）。防守战术根据对方进攻特点调整，例如弧形防阵型、一兰二防阵型、爱尔兰一防阵型和拦堵防阵型等。\\\",\\\"SentenceIdsOfAnswer\\\":[97,98]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球运动概述与技术详解\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"概述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"起源与发展\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"源于汉代，盛行于六朝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"1500多年历史\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"现代毽球运动的兴起\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"个人技艺向集体攻防转变\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"娱乐性与竞技性结合\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"登上现代竞技体育舞台\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"民族文化瑰宝\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"受到广泛喜爱\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"国际体育交往中的角色\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"基本知识与装备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"毽球结构\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"箭茅与肩垫\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"尺寸与重量标准\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"场地规格\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"长12米，宽6米\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"限制区与发球区\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"网络设置\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"长7米，宽76厘米\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"高度：男子1.6米，女子1.5米\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"规则与比赛形式\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"队伍组成\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"6人制与3人制\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"击球规则\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"连续击球限制\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"手臂接触球禁令\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"限制区内头部攻球禁令\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"比赛流程\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"不限时，先得15分胜一局\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"三局两胜制\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技术与战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本动作\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"准备姿势\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"左右开位站立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"前后开位站立\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"步伐移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"前上步、后撤步、滑步、交叉步等\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"踢球方式\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚内侧、外侧、脚背\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"触球、倒钩球、脚踏球\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"头球与拦网\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"头球技巧\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"拦网方法\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"发球与传踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"发球类型\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚内侧、正脚背、脚外侧\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"传踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双人对踢、对触踢\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"多人跑动背向传踢\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"进攻与防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"进攻战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"阵容配备（一二、二一、三三）\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"攻球技巧（头攻、倒钩、脚踏）\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"拦网、封堵、角防\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"防守阵型（弧形防、一拦二防、爱尔兰一防、拦堵防）\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"发展前景与国际交流\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"中国毽球队的国际表现\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增进国际友谊\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"作为民族文化瑰宝的传播\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"未来在世界体育舞台上的展望\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球\\\",\\\"踢毽子\\\",\\\"现代毽球运动\\\",\\\"健身作用\\\",\\\"观赏价值\\\",\\\"文化瑰宝\\\",\\\"竞技体育\\\",\\\"基本知识\\\",\\\"基本动作\\\",\\\"基本技战术\\\",\\\"技巧性\\\",\\\"对抗性\\\",\\\"球速快\\\",\\\"变化多\\\",\\\"发球\\\",\\\"传踢球\\\",\\\"防守技术\\\",\\\"进攻战术\\\",\\\"防守战术\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":44050,\\\"End\\\":60270,\\\"Text\\\":\\\"踢毽子是我国传统的民族体育项目，起源于汉代，盛行于六朝，至今在我国民间已有1500多年的历史，依然深受男女老少特别是广大青少年的喜爱。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":3,\\\"Start\\\":84030,\\\"End\\\":90250,\\\"Text\\\":\\\"如今，毽球这一中华民族的文化瑰宝，已经登上了现代竞技体育的广阔舞台。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":69,\\\"Start\\\":1249440,\\\"End\\\":1261230,\\\"Text\\\":\\\"防守技术一般包括拦网、封堵和角防三种，其中拦网是一项重要的网上防守技术，它可以在瞬间化防守为进攻，令攻方望而生畏。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":85,\\\"Start\\\":1431130,\\\"End\\\":1437480,\\\"Text\\\":\\\"战术是技术在实战中的综合运用，分为进攻战术和防守战术两部分。\\\"},{\\\"Id\\\":5,\\\"SentenceId\\\":114,\\\"Start\\\":1901020,\\\"End\\\":1907469,\\\"Text\\\":\\\"毽球运动作为一项现代竞技体育项目，既传承了古老的文化底蕴，又展现了新颖的时代特色。\\\"},{\\\"Id\\\":6,\\\"SentenceId\\\":118,\\\"Start\\\":1937210,\\\"End\\\":1948070,\\\"Text\\\":\\\"它必将伴随着祖国改革开放的坚定步伐，散发出浓郁的魅力，在人类体育的百花园中永远绽放光彩。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.32268927,\\\"Lecture\\\":0.3600857,\\\"Meeting\\\":0.31722507}}\"', '<p><br></p>', '已完成', '2025-05-22 09:28:23', '2025-07-27 00:11:23', 1, 1, 0);
INSERT INTO `ai_note_info` VALUES (198, NULL, 23, 'https://lxzj.tenir.cn/lxzj/files/2025/03/ebe292b2e5b0431594b9e47714959798.mp4', '19603bd9ac46430c90739ee3387755bb', '视频笔记分析任务161', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":35040,\\\"Headline\\\":\\\"踢毽子的两种方法：平踢与盘踢\\\",\\\"Summary\\\":\\\"介绍了踢毽子的两种基本技巧——平踢和盘踢。平踢是用脚内侧踢毽子，其中右脚正踢是最基础的踢法。详细描述了平踢的动作过程，包括预备姿势、踢毽时机、踢毽动作以及后续步法调整。强调每次踢毽的高度应超过腰部。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽子的基础技巧之一——平踢，特别强调了右脚正踢的方法。开始时，保持自然站立，双脚略微分开，将毽子置于右手胸前并轻轻抛起。当毽子下降至与膝盖同高时，迅速抬起右腿，使用脚内侧将毽子踢起，踢起高度应超过腰部。随后，右脚落地，左脚向毽子移动一小步，准备第二次踢毽。\\\",\\\"ParagraphTitle\\\":\\\"平踢毽子技巧详解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他介绍了两种踢毽子的方法，分别是平踢和盘踢，其中重点讲解了平踢这一最基本踢法的步骤。平踢使用脚内侧来踢毽子，首先，需要两脚稍微分开，保持自然站立姿势，然后用右手将毽子置于胸前，掌心向上，轻轻抛起毽子。当毽子下落到与膝盖同高时，迅速抬起右腿，屈膝，小腿向内摆动，用脚内侧将毽子踢起，随后右脚落地一次，左脚迅速跟随毽子移动一小步，准备进行第二次踢毽。他强调，通常情况下，每次踢起的毽子高度应超过腰部位置。这种踢法不仅适用于初学者，也是踢毽子运动的基础，掌握了平踢，才能更好地学习和掌握其他更为复杂的踢法。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"平踢毽子的基本步骤是什么？盘踢毽子的基本踢法是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5],\\\"Answer\\\":\\\"平踢毽子的基本步骤包括：预备时双脚稍分开，自然站立，右手将毽子置于胸前并向上抛起。当毽子下落到与膝同高的位置时，右腿迅速拾起并屈膝，小腿向里摆动，用脚内侧将毽子踢起，然后右脚落地一次，左脚迅速随毽子移动一小步，准备下一次踢法。每次踢起的毽子高度通常会超过腰部位移。盘踢毽子的基本踢法主要包括：首先，预备姿势与平踢相似，两脚稍分开，右手持毽子于胸前，掌心向上，轻轻抛起。然后，在毽子即将落地时，快速用脚内侧或脚面将毽子挑起，同时转动身体，使毽子在空中画出一道弧线。这个过程中，需要保持身体平衡并灵活转动腰部和腿部，以确保毽子能够连续稳定地被踢起。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽子方法介绍\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"平踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作要领\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"预备姿势: 两脚稍分开，自然站立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抛毽: 右手将毽置于胸前，掌心向上，轻轻抛起\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽时机: 毽子下落到与膝同高时\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右腿迅速拾起，屈膝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿向里摆，用脚内侧将毽子踢起\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"后续动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右脚落地一次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"左脚迅速随毽子移动一小步，准备踢第二次\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"踢毽高度: 一般高过腰部位移\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"注意: 未在原文中提及盘踢的具体动作要领, 仅提及了平踢。若需盘踢的详细内容, 请提供或参考相关资料补充。\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽子\\\",\\\"平踢\\\",\\\"盘踢\\\",\\\"脚内侧\\\",\\\"右脚正踢\\\",\\\"预备\\\",\\\"两脚稍分开\\\",\\\"自然站立\\\",\\\"毽子\\\",\\\"膝同高\\\",\\\"右腿\\\",\\\"屈膝\\\",\\\"小腿\\\",\\\"踢起\\\",\\\"落地\\\",\\\"左脚\\\",\\\"移动\\\",\\\"腰部位移\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4940,\\\"Text\\\":\\\"今天我们为大家介绍踢毽子的两种方法：平踢和盘踢。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.017269371,\\\"Lecture\\\":0.93371814,\\\"Meeting\\\":0.04901242}}\"', '<p><br></p>', '已完成', '2025-05-22 09:34:29', '2025-05-22 09:38:35', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (199, NULL, 87, 'https://lxzj.tenir.cn/lxzj/files/2025/05/9e3aaf3879844e3c8d6a0b0959058bb7.mp4', '7b63508e912242468b089c6b9ca18dbc', '毽球运动基本踢法', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":35050,\\\"Headline\\\":\\\"2025年毽球教学：平踢与盘踢技巧解析\\\",\\\"Summary\\\":\\\"介绍了2025年毽球运动中的两种基本踢法——平踢和盘踢。重点讲解了平踢技术，包括使用脚内侧踢球、右脚正踢的标准动作，以及预备姿势、击球时机、腿部摆动和击球高度等关键要点。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽子的两种方法：平踢和盘踢，重点详细描述了平踢的基本技巧。平踢使用脚内侧踢毽，其中右脚正踢是最基本的踢法。准备动作包括两脚稍分开自然站立，右手将毽子置于胸前并掌心向上轻轻抛起。当毽子下落到与腰部同高时，右腿迅速抬起，屈膝并向内摆小腿，用脚内侧将毽子踢起。踢完后，右脚落地一次，左脚迅速随毽子移动一小步，准备踢第二次。通常每次踢起的毽子高度应超过腰部位置。注意，文中提到的“剑”应为“毽子”的误述。\\\",\\\"ParagraphTitle\\\":\\\"踢毽子技巧：平踢与盘踢方法详解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他介绍了两种踢毽子的方法：平踢和盘踢，其中重点讲解了平踢这一基本踢法。平踢使用脚内侧来踢毽子，具体步骤如下：首先，保持两脚稍微分开的自然站立姿势，右手将毽子置于胸前，掌心向上，轻轻抛起毽子。当毽子下落到与腰部同高时，迅速抬起右腿，屈膝，小腿向内摆动，用脚内侧将毽子踢起。随后，右脚落地一次，左脚迅速移动一小步以跟随毽子的位置，准备进行第二次踢毽。每次踢起的毽子高度通常需超过腰部位置。通过这一系列的动作，他详细阐述了平踢的基本技巧和步骤，为初学者提供了清晰的指导。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"盘踢毽子的基本踢法是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5],\\\"Answer\\\":\\\"盘踢毽子的基本踢法主要包括：首先，预备姿势与平踢相似，两脚稍分开，右手持毽子于胸前，掌心向上，轻轻抛起。然后，在毽子下落至与髋部同高的瞬间，右腿快速提起并屈膝，小腿内摆，用脚内侧将毽子踢起，接着右脚落地，左脚随之移动一小步，完成第一次踢毽子。每次踢起的毽子高度也应超过腰部位移。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽子方法介绍\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"平踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"预备姿势: 两脚稍分开，自然站立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"持毽准备: 右手将毽子置于胸前，掌心向上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抛毽: 轻轻抛起毽子\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽时机: 当毽子下落到与膝盖同高时\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右腿迅速抬起，屈膝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿向里摆动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"用脚内侧将毽子踢起\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"后续动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右脚落地\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"左脚迅速移动一小步，准备第二次踢毽\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"踢毽高度\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"每次踢起的毽子高度一般应高过腰部\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"注: 未在原始内容中提及，但作为另一种踢毽子的方法，通常指的是用脚外侧或脚背踢毽子，与平踢的脚内侧踢法形成对比。具体技巧包括调整身体和脚的角度，以利用脚的不同部位来控制毽子的方向和高度。\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽子\\\",\\\"平踢\\\",\\\"盘踢\\\",\\\"脚内侧\\\",\\\"右脚正踢\\\",\\\"预备\\\",\\\"两脚稍分开\\\",\\\"自然站立\\\",\\\"毽子\\\",\\\"抛起\\\",\\\"下落\\\",\\\"与膝同高\\\",\\\"屈膝\\\",\\\"小腿向内摆动\\\",\\\"落地\\\",\\\"踢第二次\\\",\\\"高度\\\",\\\"腰部位置\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4940,\\\"Text\\\":\\\"今天我们为大家介绍踢毽子的两种方法：平踢和盘踢。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.017245777,\\\"Lecture\\\":0.93244404,\\\"Meeting\\\":0.050310146}}\"', '<p><br></p>', '已完成', '2025-05-22 09:40:00', '2025-05-23 01:12:21', 1, 1, 0);
INSERT INTO `ai_note_info` VALUES (200, NULL, 65, 'https://lxzj.tenir.cn/lxzj/files/2025/04/4968735219624d6e804a5cd715a64c2b.mp4', '7daa8734121d48b383905e8bf9a99d67', '视频笔记分析任务153', '\"[{\\\"Id\\\":1,\\\"Start\\\":1310,\\\"End\\\":142300,\\\"Headline\\\":\\\"足球基本动作教学：内侧、外侧与正脚背踢球技巧\\\",\\\"Summary\\\":\\\"介绍了四种足球基本动作的练习方法，包括单脚内侧踢球、双脚内侧交替踢球、脚外侧踢球以及正脚背踢球的详细技巧与训练方式，强调了正确的身体姿势和腿部动作要领。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本内容详细介绍了四种足球基本踢球动作的练习，包括一脚内侧踢球、脚外侧踢球、正脚背踢球和大腿触球。每种技巧都基于双脚自然开立、屈膝微微下蹲的基本姿势，并具体讲解了抬大腿、甩小腿、收小腿、勾脚尖、绷脚尖等动作要领。同时，提及了单脚和双脚的练习方式，强调在踢球时保持重心稳定和脚端平的重要性。整体旨在指导学习者正确掌握足球基本踢球技巧。\\\",\\\"ParagraphTitle\\\":\\\"足球基本踢球技巧的练习方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"介绍了四种基本的足球踢球动作：一脚内侧踢球、脚外侧踢球、正脚背踢球和大腿触球。在一脚内侧踢球时，他强调了双脚自然开立，屈膝微微下蹲，抬大腿，甩小腿，脚端平的要点。在演示脚外侧踢球时，他提到同样保持双脚自然开立，屈膝微微下蹲，但重心需落在支撑腿上，收小腿，勾脚尖。对于正脚背踢球，他指出需要大腿带动小腿屈膝上抬，踝关节放松，绷脚尖，抖动脚踝。每种踢球动作都包括了单脚和双脚的练习，强调了正确的姿势和动作对于提高足球技巧的重要性。他通过详细讲解和演示，帮助听众理解并掌握了这四种基本的足球踢球动作。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在足球训练中，如何进行单脚内侧踢球的练习？在足球训练中，如何进行大腿触球的练习？\\\",\\\"SentenceIdsOfQuestion\\\":[2,3],\\\"Answer\\\":\\\"单脚内侧踢球练习时，需保持双脚自然开立，屈膝微微下蹲，抬大腿，然后以脚端平的方式进行踢球。虽然没有明确描述大腿触球练习的具体动作细节，但可以根据足球训练的总体要求和目的，理解为利用大腿接触并引导球的移动，以此来提高控球能力和技术运用。\\\",\\\"SentenceIdsOfAnswer\\\":[2,3]},{\\\"Question\\\":\\\"双脚内侧踢球练习的正确姿势是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"双脚内侧踢球练习要求双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，同时抬大腿、收小腿、勾脚尖并保持脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"单脚外侧踢球练习的要点是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[5],\\\"Answer\\\":\\\"单脚外侧踢球练习需要保持双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，抬大腿，收小腿，勾脚尖，确保脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"正脚背踢球练习时，身体应如何准备？在足球训练中，如何执行单脚正脚背踢球练习？\\\",\\\"SentenceIdsOfQuestion\\\":[8],\\\"Answer\\\":\\\"进行正脚背踢球练习时，需双脚自然开立，屈膝微微下蹲，大腿带动小腿屈膝上抬，踝关节放松并绷脚尖，同时抖动脚踝进行练习。单脚正脚背踢球练习要求保持双脚自然开立，屈膝微微下蹲，通过大腿带动小腿上抬，踝关节放松绷脚尖，并通过抖动脚踝来完成踢球动作。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"足球基本动作练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一脚内侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，甩小腿，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚内侧踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双脚内侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"脚外侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心落在支撑腿上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，收小腿，勾脚尖，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚外侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"正脚背踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝，微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"大腿带动小腿屈膝上抬\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踝关节放松，绷脚尖，抖动脚踝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚正脚背踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"大腿触球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"通过大腿接触球进行控制或传球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"注意身体平衡和球的接触点\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"基本动作\\\",\\\"一脚内侧踢球\\\",\\\"双脚自然分开站立\\\",\\\"屈膝\\\",\\\"微微下蹲\\\",\\\"抬起大腿\\\",\\\"脚面放平\\\",\\\"脚外侧踢球\\\",\\\"重心\\\",\\\"支撑腿\\\",\\\"收回小腿\\\",\\\"勾起脚尖\\\",\\\"正脚背踢球\\\",\\\"大腿带动小腿\\\",\\\"绷紧脚尖\\\",\\\"抖动脚踝\\\",\\\"大腿触球\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.019897494,\\\"Lecture\\\":0.92467904,\\\"Meeting\\\":0.055423494}}\"', '<p><br></p>', '已完成', '2025-05-22 09:44:41', '2025-05-23 01:10:41', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (201, NULL, 87, 'https://lxzj.tenir.cn/lxzj/files/2025/05/9e3aaf3879844e3c8d6a0b0959058bb7.mp4', '1df994fee326452aaa76c2aa2f9eea72', '平踢与盘踢技巧详解', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":35050,\\\"Headline\\\":\\\"2025年毽球教学：平踢与盘踢技巧详解\\\",\\\"Summary\\\":\\\"介绍了2025年毽球运动中的两种基本踢法，平踢和盘踢。重点讲解了平踢技术，包括使用脚内侧踢、右脚正踢的标准动作，以及预备姿势、击球时机、腿部摆动和击球高度等关键要点。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽子的两种方法：平踢和盘踢，重点详细描述了平踢的基本技巧。平踢使用脚内侧踢毽，其中右脚正踢是最基础的踢法。准备动作包括两脚稍微分开自然站立，右手将毽子置于胸前并掌心向上轻轻抛起。当毽子下落到与腰部同高时，迅速抬起右腿，屈膝并用脚内侧将毽子踢起，随后右脚落地一次，左脚迅速随毽子移动一小步，准备进行第二次踢毽。每次踢起的毽子高度通常要超过腰部位置。\\\",\\\"ParagraphTitle\\\":\\\"踢毽子基础技巧：平踢与盘踢详解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"介绍了踢毽子的两种基本方法，首先是平踢技巧，这是踢毽子中最基础的踢法。他详细描述了平踢的动作过程：在预备阶段，站立时两脚应稍微分开，用右手将毽子置于胸前，掌心向上轻轻抛起。当毽子下落到与腰部同高的位置时，迅速抬起右腿，屈膝并使小腿向内摆动，利用脚内侧将毽子踢起。踢毽子时，右脚在踢完后会落地一次，接着左脚向毽子移动一小步，为第二次踢毽做准备。通常情况下，每次踢起的毽子高度需要超过腰部位置。通过这些步骤，他清晰地阐述了平踢这一基础踢毽子技巧的执行过程。此外，他还提到了另一种踢法——盘踢，但并未详细展开。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"盘踢毽子的基本踢法是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5],\\\"Answer\\\":\\\"盘踢毽子的基本踢法主要包括：首先，预备姿势与平踢相似，两脚稍分开，右手持毽子于胸前，掌心向上，轻轻抛起。然后，在毽子下落至与髋部同高的瞬间，右腿快速提起并屈膝，小腿内摆，用脚内侧将毽子踢起，接着右脚落地，左脚随之移动一小步，完成第一次踢毽子。每次踢起的毽子高度也应超过腰部位移。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽子方法介绍\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"平踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本姿势\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两脚稍分开，自然站立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"右手将毽子置于胸前，掌心向上\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"动作步骤\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽高度\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一般高过腰部位移\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"注意: 未在给定内容中提及盘踢的具体步骤和细节, 通常盘踢是指用脚外侧或脚背盘旋踢毽子的方式, 这里基于平踢的介绍推测盘踢的基本概念。\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"使用脚外侧或脚背\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"盘旋踢毽, 更注重控制和技巧\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽子\\\",\\\"平踢\\\",\\\"盘踢\\\",\\\"脚内侧\\\",\\\"右脚正踢\\\",\\\"预备\\\",\\\"两脚稍分开\\\",\\\"自然站立\\\",\\\"毽子\\\",\\\"抛起\\\",\\\"下落\\\",\\\"与膝同高\\\",\\\"屈膝\\\",\\\"小腿向内摆动\\\",\\\"落地\\\",\\\"踢第二次\\\",\\\"高度\\\",\\\"腰部位置移动\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4940,\\\"Text\\\":\\\"今天我们为大家介绍踢毽子的两种方法：平踢和盘踢。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.017245777,\\\"Lecture\\\":0.93244404,\\\"Meeting\\\":0.050310146}}\"', '<p><br></p>', '已完成', '2025-05-22 11:50:30', '2025-05-22 12:06:45', 36, 36, 0);
INSERT INTO `ai_note_info` VALUES (202, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E6%88%98%E6%9C%AF%E6%AD%A5%E6%B3%95%E8%B8%A2%E7%90%83%E7%BB%83%E4%B9%A0.mp4', '7412b377ef5946a29740ed33dd703434', '视频笔记分析任务01', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":147768,\\\"Headline\\\":\\\"毽球基本战术与技术训练解析\\\",\\\"Summary\\\":\\\"毽球基本战术分为进攻和防守两部分。进攻战术包括单一倒钩型、踩踏型及综合型配备，阵容配备有三种形式，打法配备多样，如高举高打型、快球进攻型等。防守战术则包含四种基本阵型。毽球技术训练是毽球训练的基础，每一项技术的强化训练对未来发展都至关重要。\\\"},{\\\"Id\\\":2,\\\"Start\\\":148360,\\\"End\\\":307370,\\\"Headline\\\":\\\"毽球运动员的步法训练方法\\\",\\\"Summary\\\":\\\"毽球运动员在场上的移动从准备姿势开始，通过五步法进行训练，包括双脚与肩同宽站立、脚掌外转、脚跟外移呈内八字、降低重心并前倾、全身放松且目视来球。步法练习是基本功之一，用于调整人与球之间的最佳位置。训练原则涵盖单一练习的规范性、统一练习的一致性、综合练习的连贯性以及带球练习的实战性。\\\"},{\\\"Id\\\":3,\\\"Start\\\":323530,\\\"End\\\":460090,\\\"Headline\\\":\\\"踢球技巧与训练方法详解\\\",\\\"Summary\\\":\\\"踢球练习作为传球训练的基础，涵盖了脚型练习、单人与双人练习、隔网对踢以及触球练习等内容，强调了规范性、连贯性与实战结合的重要性。通过单人、双人及组合式的综合性练习，旨在全面提升踢球技术，特别是在触球和传球技巧上的精进。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球运动的战术分为进攻与防守两部分，进攻包括单一倒钩型、单一踩踏型及倒钩踩踏综合型配备，防守则有四种基本阵型。技术训练基础在于准备姿势、步法、踢球与触球练习，其中准备姿势分五步，步法确保人球最佳位置，踢触球练习需紧密结合实战。训练遵循单一、统一、综合与带球实战原则，强化基本功并为未来发展奠定基础。\\\",\\\"ParagraphTitle\\\":\\\"毽球战术、技术和移动技巧综述\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"详细阐述了毽球基本战术的构成与分类，强调了进攻与防守战术的多样性。进攻战术包括单一倒钩型、单一踩踏型及倒钩踩踏综合型配备，阵容配备分为一一二、221、333三种，打法配备涵盖高举高打型、快球进攻型等八种类型。防守战术则有小弧形、一篮二防等四种基本阵型。他特别强调了技术训练的重要性，指出准备姿势的五个步骤、步法练习、踢球练习和触球练习是基本功的基石。训练原则应遵循单一练习规范、统一练习不走样、综合练习连贯和带球练习进实战。此外，他介绍了单人、双人、隔网对踢和综合行进练习等不同类型的练习，强调传球练习是踢球技术的基础，触球练习与实践应紧密结合。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球基本战术包含哪些部分以及进攻战术有哪些配备和技术？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分。在进攻战术中，技术配备有单一倒钩型、单一踩踏型以及倒钩踩踏综合型。此外，进攻战术的阵容配备有3种类型，分别是“一一二”阵容配备、“221”阵容配备和“333”阵容配备，并且具体打法包括高举高打型、快球进攻型、中路进攻型、四边路进攻型、自调进攻型、背溜进攻型、掩护进攻型和交叉进攻型。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,5,6]},{\\\"Question\\\":\\\"毽球防守战术有哪几种基本阵型？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14,15,16],\\\"Answer\\\":\\\"毽球防守战术有4种基本防守阵型，分别是小弧形防守阵型、二一篮2防防守阵型、三拦堵防防守阵型和42兰1防防守阵型。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14,15,16]},{\\\"Question\\\":\\\"毽球运动员在比赛中的移动准备姿势是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[17,18,19,20,21,22],\\\"Answer\\\":\\\"毽球运动员在场上比赛时，其移动准备姿势通常要求五步完成，包括两脚与肩同宽平行开立、以脚跟为轴两脚掌外转接近平行、以脚尖为轴两脚跟外移呈内八字形站位、重心下降上体稍前倾、膝关节内扣两手臂自然弯曲于体前，以及全身放松目视来球。待单人练习成型后，需进一步体会用脚尖内侧迅速发力蹬地，使重心被推移的感觉。\\\",\\\"SentenceIdsOfAnswer\\\":[17,18,19,20,21,22]},{\\\"Question\\\":\\\"如何进行步法练习以提升毽球运动员的比赛能力？\\\",\\\"SentenceIdsOfQuestion\\\":[25,26,27,28],\\\"Answer\\\":\\\"步法练习是毽球运动员临场比赛的基本功，旨在调整人与球的最佳位置。训练时应确保单一练习规范统一，统一练习不走样，综合练习连贯，带球练习结合实战的原则。通过反复练习蹬地感觉，帮助运动员掌握快速、准确的步法移动。\\\",\\\"SentenceIdsOfAnswer\\\":[25,26,27,28]},{\\\"Question\\\":\\\"踢球练习与触球练习在毽球技术训练中的重要性及练习方式是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[37],\\\"Answer\\\":\\\"踢球练习是传球训练的基础，要求单人练习协调连贯，组合练习放松自如，综合行进练习结合步伐。触球练习作为过渡性技术训练，应与实践紧密结合，包括单人处踢球练习、双人处踢球练习、双人互打杂处踢球练习以及代步法与实战结合的触踢球练习等。同时，传球练习是各项踢球技术训练的重要组成部分。\\\",\\\"SentenceIdsOfAnswer\\\":[40,41,42,43,44]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本战术与技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"毽球基本战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"进攻战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一倒钩型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单一踩踏型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"倒钩踩踏综合型配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"阵容配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一一二阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"221阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"333阵容配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"打法配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"高举高打型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快球进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"中路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"四边路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"自调进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"背溜进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"掩护进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"交叉进攻型\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本防守阵型\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小弧形防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"一篮2防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"拦堵防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"42兰1防防守阵型\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"准备姿势与移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"五步进行\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两脚与肩同宽，平行开立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚跟为轴，两脚掌外转接近平行\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚尖为轴，两脚跟外移，呈内八字形站位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"全身放松，目视来球静中带动\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"步法练习原则\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一练习要规范\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"统一练习不走样\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合练习要连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带球练习进实战\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"隔网对踢练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"触球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人互打杂处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"代步法的与实战结合的触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合式综合性触球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"各项踢球技术结合\\\",\\\"Topic\\\":[]}]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本战术\\\",\\\"进攻战术\\\",\\\"防守战术\\\",\\\"高举高打型\\\",\\\"快球进攻型\\\",\\\"中路进攻型\\\",\\\"四边路进攻行\\\",\\\"自调进攻型\\\",\\\"背溜进攻型\\\",\\\"掩护进攻型\\\",\\\"交叉进攻型\\\",\\\"技术训练\\\",\\\"准备姿势\\\",\\\"移动\\\",\\\"步法练习\\\",\\\"踢球练习\\\",\\\"脚型练习\\\",\\\"触球练习\\\",\\\"传球练习\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":8254,\\\"Text\\\":\\\"毽球基本战术是指队员在比赛中将各项基本技术相互配合并加以组合运用的方式。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":8990,\\\"End\\\":20310,\\\"Text\\\":\\\"毽球基本战术分为进攻战术和防守战术两部分，其中进攻战术的技术配备包括单一倒钩型配备。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":5,\\\"Start\\\":46250,\\\"End\\\":59607,\\\"Text\\\":\\\"进攻战术的阵容配备主要有以下三种：一一二阵容配备、二二一阵容配备、三三三阵容配备。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":6,\\\"Start\\\":60830,\\\"End\\\":67390,\\\"Text\\\":\\\"进攻战术的打法配备有多种类型，例如高举高打型。\\\"},{\\\"Id\\\":5,\\\"SentenceId\\\":40,\\\"Start\\\":413510,\\\"End\\\":420830,\\\"Text\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，需与实战紧密结合进行。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.13368736,\\\"Lecture\\\":0.28069776,\\\"Meeting\\\":0.5856148}}\"', '<p>视频中提到了以下毽球动作：</p><ol><li>进攻战术中的动作：单一倒钩型、单一踩踏型、倒钩踩踏综合型、高举高打型、快球进攻型、中路进攻型、四边路进攻型、自调进攻型、背溜进攻型、掩护进攻型、交叉进攻型。</li><li>防守战术中的阵型：小弧形防守阵型、二一篮2防防守阵型、三拦堵防防守阵型、42兰1防防守阵型。</li><li>准备姿势与移动：两脚与肩同宽，平行开立；以脚跟为轴，两脚掌外转接近平行；以脚尖为轴，两脚跟外移，呈内八字形站位；重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前；全身放松，目视来球，静中带动。</li><li>踢球练习：单人练习、双人练习、隔网对踢练习、触球练习（包括单人处踢球、双人处踢球、双人互打杂处踢球等）。</li><li>步法练习原则：单一练习要规范，统一练习不走样，综合练习要连贯，带球练习进实战。</li></ol><p>这些动作和训练方法涵盖了毽球的基本战术、技术训练以及步法练习等多个方面。</p>', '已完成', '2025-05-22 12:16:50', '2025-05-22 12:19:00', 37, 37, 0);
INSERT INTO `ai_note_info` VALUES (203, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/%E6%88%98%E6%9C%AF%E6%AD%A5%E6%B3%95%E8%B8%A2%E7%90%83%E7%BB%83%E4%B9%A0.mp4', 'e4f45549af8140118ec50a770682070e', '战术、步法和踢球训练', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":147768,\\\"Headline\\\":\\\"毽球基本战术与技术训练解析\\\",\\\"Summary\\\":\\\"毽球基本战术分为进攻和防守两部分。进攻战术包括单一倒钩型、踩踏型及综合型配备，阵容配备有三种形式，打法配备多样，如高举高打型、快球进攻型等。防守战术则包括四种基本阵型，如小弧形防守和拦堵防防守阵型。技术训练是毽球训练的基础，每项技术的强化训练是未来发展的关键。\\\"},{\\\"Id\\\":2,\\\"Start\\\":148360,\\\"End\\\":307370,\\\"Headline\\\":\\\"毽球运动员的步法训练方法\\\",\\\"Summary\\\":\\\"毽球运动员在场上比赛时的移动从准备姿势开始，通过五个步骤进行脚距丈量和姿势调整，包括脚与肩同宽、外转脚掌、内八字站位、重心下降以及全身放松。训练中强调单人练习的规范性、统一练习的一致性、综合练习的连贯性以及带球练习的实战性，以提高步法调整人与球最佳位置的能力。\\\"},{\\\"Id\\\":3,\\\"Start\\\":323530,\\\"End\\\":460090,\\\"Headline\\\":\\\"踢球技巧与传球训练指南\\\",\\\"Summary\\\":\\\"踢球练习是传球训练的基础，涵盖了脚型练习、单人和双人练习、隔网对踢以及触球练习等多个方面内容，强调了规范性、连贯性以及实战结合的重要性。这些技能的训练对于提升踢球技术至关重要。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球战术分为进攻和防守，进攻战术涵盖单一倒钩型、单一踩踏型、倒钩踩踏综合型技术，以及一一二、221、333阵容配备和多种打法。防守战术包括小弧形、一篮二防、拦堵防、二拦一防阵型。技术训练强调基础，运动员移动通过五步脚距丈量，步法练习确保人球最佳位置，遵循单一、统一、综合、带球实战原则。踢球练习为基础和基本功，注重脚型、协调、放松和综合行进。触球练习为过渡性技术，紧密结合实践。训练过程涵盖单人、双人、隔网对踢、代步法与实战结合的触踢球练习，以及组合式综合性触球练习，传球练习为各项踢球技术基础。\\\",\\\"ParagraphTitle\\\":\\\"毽球战术、技术和训练方法综述\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他详细阐述了毽球基本战术的构成与分类，强调了进攻与防守战术的多样性。进攻战术包括单一倒钩型、单一踩踏型及倒钩踩踏综合型配备，阵容配备分为一一二、221、333三种，打法配备涵盖高举高打型、快球进攻型等八种类型。防守战术则有小弧形、一篮二防等四种基本阵型。他特别强调了技术训练的重要性，指出准备姿势的五个步骤、步法练习、踢球练习和触球练习是基本功的基石。训练原则应遵循单一练习规范、统一练习不走样、综合练习连贯和带球练习进实战。此外，他介绍了单人、双人、隔网对踢和综合行进练习等不同形式的练习，强调传球练习是踢球技术的基础，触球练习与实践的结合至关重要。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球基本战术包含哪些部分以及进攻战术有哪些配备和技术？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分。在进攻战术中，技术配备有单一倒钩型、单一踩踏型以及倒钩踩踏综合型。此外，进攻战术的阵容配备有3种类型，分别是“一一二”阵容配备、“221”阵容配备和“333”阵容配备，并且具体打法包括高举高打型、快球进攻型、中路进攻型、四边路进攻型、自调进攻型、背溜进攻型、掩护进攻型和交叉进攻型。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,5,6]},{\\\"Question\\\":\\\"毽球防守战术有哪几种基本阵型？\\\",\\\"SentenceIdsOfQuestion\\\":[9,10,11,12,13,14,15,16],\\\"Answer\\\":\\\"毽球防守战术有4种基本防守阵型，分别是小弧形防守阵型、二一篮2防防守阵型、三拦堵防防守阵型和42兰1防防守阵型。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11,12,13,14,15,16]},{\\\"Question\\\":\\\"毽球运动员在比赛中的移动准备姿势是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[17,18,19,20,21,22],\\\"Answer\\\":\\\"毽球运动员在场上比赛时的准备姿势要求五步进行，包括：两脚与肩同宽平行开立；以脚跟为轴，两脚掌外转接近平行；以脚尖为轴，两脚跟外移呈内八字形站位；重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前；全身放松，目视来球，静中带动。单人练习成型后，应能一步到位并体会用脚尖内侧迅速发力蹬地的感觉。\\\",\\\"SentenceIdsOfAnswer\\\":[17,18,19,20,21,22]},{\\\"Question\\\":\\\"步法练习在毽球训练中的重要性和具体原则是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[25,26,27,28],\\\"Answer\\\":\\\"步法练习是毽球运动员临场比赛的基础，调整人与球最佳位置的关键。训练中应遵循单一练习要规范统一，组合练习要连贯，带球练习进实战的原则。通过反复练习蹬地的感觉和步法移动，确保运动员具备出色的步法能力。\\\",\\\"SentenceIdsOfAnswer\\\":[25,26,27,28]},{\\\"Question\\\":\\\"踢球练习（传球训练）的基础和技术要求是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[32,33,34],\\\"Answer\\\":\\\"踢球练习（传球训练）是基础且重要的部分，其中脚型练习需严格规范，单人练习要求协调连贯，组合练习需放松自如，综合行进练习则需结合步伐进行。通过单人、双人乃至隔网对踢等多种形式的练习，提高踢球技术的熟练度和实战应用能力。\\\",\\\"SentenceIdsOfAnswer\\\":[35,36]},{\\\"Question\\\":\\\"触球练习在毽球技术训练中的地位及结合实践的方式是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[40,41,42,43,44],\\\"Answer\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，应与实践紧密结合进行，包括单人触踢球练习、双人触踢球练习、双人互打杂处踢球练习以及代步法与实战结合的触踢球练习等。通过这些练习，使触球技术与实际比赛相结合，提升运动员的技术水平和实战能力。\\\",\\\"SentenceIdsOfAnswer\\\":[40,41,42,43,44]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本战术与技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"毽球基本战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"进攻战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一倒钩型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单一踩踏型配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"倒钩踩踏综合型配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"阵容配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一一二阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"221阵容配备\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"333阵容配备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"打法配备\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"高举高打型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"快球进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"中路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"四边路进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"自调进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"背溜进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"掩护进攻型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"交叉进攻型\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"防守战术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本防守阵型\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小弧形防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"一篮2防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"拦堵防防守阵型\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"42兰1防防守阵型\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技术训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"准备姿势与移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"五步进行\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两脚与肩同宽，平行开立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚跟为轴，两脚掌外转接近平行\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"以脚尖为轴，两脚跟外移，呈内八字形站位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"全身放松，目视来球静中带动\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"步法练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单一练习要规范\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"统一练习不走样\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合练习要连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"带球练习进实战\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"踢球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚型练习应规范严格\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单人练习要协调连贯\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合练习要放松自如\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"综合行进练习要结合步伐\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"触球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单人处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双人互打杂处踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"代步法的与实战结合的触踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合式综合性触球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"传球练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"各项踢球技术的基础\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本战术\\\",\\\"进攻战术\\\",\\\"防守战术\\\",\\\"高举高打型\\\",\\\"快球进攻型\\\",\\\"中路进攻型\\\",\\\"四边路进攻行\\\",\\\"自调进攻型\\\",\\\"背溜进攻型\\\",\\\"掩护进攻型\\\",\\\"交叉进攻型\\\",\\\"技术训练\\\",\\\"准备姿势\\\",\\\"移动\\\",\\\"步法练习\\\",\\\"踢球练习\\\",\\\"脚型练习\\\",\\\"触球练习\\\",\\\"传球练习\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":8254,\\\"Text\\\":\\\"毽球基本战术是指队员在比赛中将各项基本技术相互配合并组合运用的方式。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":8990,\\\"End\\\":20310,\\\"Text\\\":\\\"毽球基本战术包括进攻战术和防守战术两部分，其中进攻战术的技术配备包含单一倒钩型配备。\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":5,\\\"Start\\\":46250,\\\"End\\\":59607,\\\"Text\\\":\\\"进攻战术的阵容配备主要包括以下三种：一一二阵容配备、二二一阵容配备以及三三三阵容配备。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":6,\\\"Start\\\":60830,\\\"End\\\":67390,\\\"Text\\\":\\\"进攻战术的打法配备有以下多种类型，第一种是高举高打型。\\\"},{\\\"Id\\\":5,\\\"SentenceId\\\":40,\\\"Start\\\":413510,\\\"End\\\":420830,\\\"Text\\\":\\\"触球练习是一项不可或缺的过渡性技术训练，需要与实际操作紧密结合来进行。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.13368736,\\\"Lecture\\\":0.28069776,\\\"Meeting\\\":0.5856148}}\"', '<p>视频笔记：毽球战术、技术和训练方法综述 &nbsp;</p><ol><li>毽球基本战术<br>毽球的基本战术分为进攻战术和防守战术两部分。</li></ol><p>1.1 进攻战术 &nbsp;</p><ul><li>技术配备 &nbsp;</li><li>阵容配备（3种类型） &nbsp;</li><li>打法配备（8种类型）</li></ul><p>1.2 防守战术 &nbsp;</p><ul><li>基本阵型（4种类型）</li></ul><ol><li>技术训练<br>技术训练是毽球训练的基础，涵盖以下几个方面：</li></ol><p>2.1 准备姿势与移动<br>毽球运动员在比赛中的准备姿势包括以下五个步骤： &nbsp;</p><ul><li>脚距丈量：两脚与肩同宽平行开立。 &nbsp;</li><li>脚掌外转：以脚跟为轴，两脚掌外转接近平行。 &nbsp;</li><li>内八字站位：以脚尖为轴，两脚跟外移呈内八字形站位。 &nbsp;</li><li>重心调整：重心下降，上体稍前倾，膝关节内扣，两手臂自然弯曲于体前。 &nbsp;</li><li>全身放松：静中带动，目视来球。</li></ul><p>2.2 步法练习<br>步法练习是调整人与球最佳位置的关键，遵循以下原则： &nbsp;</p><ul><li>单一练习：动作规范统一。 &nbsp;</li><li>组合练习：连贯性训练。 &nbsp;</li><li>带球练习：结合实战场景进行。</li></ul><p>2.3 踢球练习<br>踢球练习是传球训练的基础，注重以下方面： &nbsp;</p><ul><li>脚型练习：严格规范。 &nbsp;</li><li>单人练习：协调连贯。 &nbsp;</li><li>组合练习：放松自如。 &nbsp;</li><li>综合行进练习：结合步伐进行。</li></ul><p>2.4 触球练习<br>触球练习是一项过渡性技术训练，需与实践紧密结合，包括： &nbsp;</p><ul><li>单人触踢球练习 &nbsp;</li><li>双人触踢球练习 &nbsp;</li><li>双人互打杂处踢球练习 &nbsp;</li><li>带步法与实战结合的触踢球练习 &nbsp;</li><li>组合式综合性触球练习</li></ul><p>2.5 传球练习<br>传球练习是各项踢球技术的基础，强调规范性和实战应用能力。 &nbsp;</p><ol><li>总结<br>毽球战术和技术训练的核心是强化基础，通过系统的准备姿势、步法、踢球和触球练习，提升运动员的技术水平和实战能力。踢球练习作为传球训练的基础，强调脚型规范、协调性和实战结合。触球练习则是不可或缺的过渡性技术，需与实际比赛场景紧密结合。</li></ol><p>希望这份笔记对您有所帮助！如有其他问题，请随时提问！</p>', '已完成', '2025-05-22 12:31:18', '2025-05-23 03:00:31', 1, 1, 0);
INSERT INTO `ai_note_info` VALUES (204, 37, 89, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本功—开合跳.mp4', 'f58efff79e4e4d06aba5fa056a6bc1e6', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":24270,\\\"Headline\\\":\\\"翎析智鉴：毽球专项热身训练方法\\\",\\\"Summary\\\":\\\"系统讲解毽球专项热身训练方法，重点介绍开合跳热身对下肢爆发力和踝关节稳定性的提升作用。通过分组训练方式，帮助运动员激活下肢肌群，增强急停变向时的关节支撑能力。训练强调动作幅度与速度的协调控制，循序渐进提升训练强度，为后续技术训练做好充分准备。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本训练方案重点讲解毽球专项热身方法，强调开合跳对提升下肢爆发力的重要性。通过科学的训练安排，帮助运动员增强腿部肌群和踝关节稳定性，为后续技术训练做好准备。\\\",\\\"ParagraphTitle\\\":\\\"毽球专项热身训练体系\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"专项教练\\\",\\\"Summary\\\":\\\"在训练体系中，我们采用开合跳作为毽球专项热身的重要环节。这套训练方案通过科学的强度控制，能有效激活下肢肌群，提升踝关节稳定性。训练时要注意保持动作幅度最大化，循序渐进地增加速度，使身体逐步达到最佳训练状态。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球专项热身中开合跳的主要作用是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2],\\\"Answer\\\":\\\"开合跳在毽球热身中主要发挥三大作用：1)激活下肢肌群，提升爆发力；2)增强踝关节稳定性，预防运动损伤；3)提高心肺功能，为后续训练做好准备。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2]},{\\\"Question\\\":\\\"如何科学安排开合跳训练？\\\",\\\"SentenceIdsOfQuestion\\\":[3,4],\\\"Answer\\\":\\\"建议采用渐进式训练法：1)初期以动作质量为主，确保幅度到位；2)中期逐步提升动作频率；3)后期可增加负重训练。每组训练后要进行专项拉伸。\\\",\\\"SentenceIdsOfAnswer\\\":[3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球热身体系\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"专项热身训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开合跳训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目标\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"激活下肢肌群\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升爆发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"增强关节稳定性\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作幅度最大化\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"循序渐进提速\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"配合专项拉伸\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"训练进阶方案\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基础阶段：动作规范性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高阶段：动作连贯性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"强化阶段：动作爆发力\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"翎析智鉴\\\",\\\"毽球基本功\\\",\\\"开合跳热身\\\",\\\"分组训练\\\",\\\"加速训练\\\",\\\"腿部激活\\\",\\\"热身效果\\\",\\\"下肢力量\\\",\\\"脚踝稳定性\\\",\\\"移动速度\\\",\\\"急停转向\\\",\\\"关节力量\\\",\\\"力量提升\\\",\\\"专项练习\\\",\\\"动作幅度\\\",\\\"动作速率\\\",\\\"爆发力\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4496,\\\"Text\\\":\\\"欢迎来到翎析智鉴，今天我们一起来学习毽球基本功。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.005321118,\\\"Lecture\\\":0.9684411,\\\"Meeting\\\":0.026237836}}\"', NULL, '已完成', '2025-05-22 16:15:00', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (205, 38, 90, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本功—快速启动小碎步.mp4', 'c2ba97dad09d4afa824566eecb148e91', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":34300,\\\"Headline\\\":\\\"快速启动与耐力提升专项训练\\\",\\\"Summary\\\":\\\"介绍通过小碎步热身和屈膝练习增强下肢力量与耐力的训练方法，重点讲解下蹲幅度和重心控制对提升启动速度和移动速度的关键作用，以及通过分组训练感受肌肉反应的科学训练方式。\\\"}]\"', '\"\\\"ParagraphSummary\\\":\\\"本训练方案重点讲解提升快速启动能力和耐力的专项训练方法，通过小碎步热身和间歇训练增强下肢力量。训练强调动作规范性和强度控制，帮助运动员提高爆发力和移动速度。\\\",\\\"ParagraphTitle\\\":\\\"快速启动与耐力提升训练方案\\\",\\\"ConversationalSummary\\\":[\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"专项教练\\\",\\\"Summary\\\":\\\"本次训练着重讲解快速启动能力的培养方法。采用小碎步热身配合间歇训练模式，通过科学的强度控制有效提升下肢爆发力。训练时需特别注意动作规范性，包括正确的下蹲幅度和重心位置，确保训练效果最大化。\\\"],\\\"QuestionsAnsweringSummary\\\":[\\\"Question\\\":\\\"快速启动训练的关键要素是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2],\\\"Answer\\\":\\\"快速启动训练需要关注三个关键要素：1)正确的下蹲幅度和重心位置；2)科学的训练强度控制；3)循序渐进的训练进阶方案。建议采用分组训练方式，每组训练后要进行充分恢复。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2]},\\\"Question\\\":\\\"如何通过训练提升耐力？\\\",\\\"SentenceIdsOfQuestion\\\":[3,4],\\\"Answer\\\":\\\"耐力提升需要：1)采用间歇训练模式；2)逐步延长训练时间；3)保持动作质量的前提下增加训练强度。建议每周进行2-3次专项耐力训练。\\\",\\\"SentenceIdsOfAnswer\\\":[3,4]],\\\"MindMapSummary\\\":[\\\"Title\\\":\\\"快速启动与耐力训练体系\\\",\\\"Topic\\\":[\\\"Title\\\":\\\"训练要素\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作规范性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"下蹲幅度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心控制\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"强度控制\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练时长\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇时间\\\",\\\"Topic\\\":[]}]}},\\\"Title\\\":\\\"训练方法\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步训练\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇训练\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"爆发力训练\\\",\\\"Topic\\\":[]}},\\\"Title\\\":\\\"训练效果\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动能力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"移动耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下肢爆发力\\\",\\\"Topic\\\":[]}}}}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"屈膝\\\",\\\"腿部\\\",\\\"脚踝\\\",\\\"力量\\\",\\\"耐力\\\",\\\"启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"大腿的酸胀感\\\",\\\"专项训练\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.010176665,\\\"Lecture\\\":0.9672729,\\\"Meeting\\\":0.022550493}}\"', NULL, '已完成', '2025-05-22 16:19:39', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (206, 39, 91, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本功—前后倒步.mp4', '5fb447475183478da7834800e67f220e', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":40270,\\\"Headline\\\":\\\"翎析智鉴：毽球运动基本功提升与灵动步法精要\\\",\\\"Summary\\\":\\\"系统讲解毽球专项热身方法，包括前后交叉步动态拉伸及爆发力训练，重点解析启动蹬转技术要领与核心稳定性的协同发力机制。详细阐述毽球特有的无球移动策略，涵盖落点预判、重心转换及连续位移技巧，指出快速变向能力与细腻的触球准备是提升竞技水平的核心要素。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"主讲人强调毽球训练中基本功的重要性，特别是交叉步热身和腿部爆发力训练，指出蹬转幅度和感受腿部发力是关键，强化下肢力量以提高启动速度、核心稳定性和变向能力。他比喻运动员应如飞燕掠空，时刻保持灵动移动，根据毽球的飞行轨迹、旋转和预判落点进行快速位移，包括触球移动和无球跑位。多数人只关注触球时的移动，忽视了无球时的预启动步法，这会错失最佳击球时机，而竞技水平的差距往往就在这些细节步法上体现。\\\",\\\"ParagraphTitle\\\":\\\"毽球训练：基础功与灵动步法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他欢迎听众参与翎析智鉴的毽球基本功学习，重点讲解了交叉步热身运动，推荐进行30秒间歇的两组练习，强调蹬转幅度以充分感受腿部爆发力，以此增强下肢力量。他指出，毽球训练首要重视腿部爆发力训练，以提升启动速度、核心稳定性和变向能力，使运动员在场上动作敏捷如燕。在实战中，步法应持续移动，根据毽球旋转和预判落点调整移动节奏，不仅在触球时，也在无球状态下保持预启动。他特别提醒，很多人只关注触球时的移动，却忽视了无球时的预启动步法，这将导致错过最佳击球时机，强调细节步法决定运动表现的差距。总之，他强调了毽球基本功训练中下肢爆发力和灵动步法的重要性，尤其是持续移动、预判及无球预启动的细节，这些因素对提升毽球表现至关重要。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在毽球基本功训练中，为什么强调先练腿部爆发力？如何避免在毽球比赛中因无球移动而错失最佳击球时机？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"强化下肢爆发力，腿部力量对于提高启动速度、核心稳定性及变向能力至关重要。强大的爆发力能够帮助运动员快速启动，如同飞燕般敏捷，同时确保场上步法不停，时刻保持预启动状态。根据毽球的旋转和预判落点，灵活进行快速位移，包括触球和无球状态下的预启动。许多运动员只关注触球移动，而忽视了无球时应采取积极的预启动步法。实际上，无球时应主动调整站位，利用小碎步来获取更好的击球位置，否则可能会浪费掉宝贵的击球时机。因此，提升无球预启动的意识和能力，是提升毽球场上表现的关键因素之一。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"翎析智鉴 - 毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"热身与基础练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"交叉步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"持续时间: 30秒/组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组数: 1-2组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"注意点: 蹬转幅度, 感受腿部爆发力\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练重点: 下肢与爆发力\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"强化下肢爆发力\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"目标: 提高启动速度, 核心稳定性, 变向能力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"比喻: 飞燕掠空\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"快速启动的重要性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"关键: 预启动步法\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"场上步法技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"保持灵动移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"根据毽球旋转与预判落点调整位移节奏\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"触球与无球移动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"触球移动: 精准到位\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"无球移动: 避免停滞, 保持预启动状态\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"细节步法决定差距\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"关键时刻的预启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"避免错失最佳击球时机\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"翎析智鉴\\\",\\\"毽球基本功\\\",\\\"交叉步热身\\\",\\\"腿部爆发力\\\",\\\"蹬转幅度\\\",\\\"强化下肢力量\\\",\\\"启动速度\\\",\\\"核心稳定性\\\",\\\"变向能力\\\",\\\"飞燕掠空\\\",\\\"场上步法\\\",\\\"灵动移动\\\",\\\"毽球旋转\\\",\\\"预判落点\\\",\\\"触球移动\\\",\\\"无球预启动\\\",\\\"最佳击球时机\\\",\\\"细节步法\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":2,\\\"Start\\\":11780,\\\"End\\\":31266,\\\"Text\\\":\\\"强化下肢爆发力，提高启动速度、核心稳定性以及变向能力，做到飞燕掠空。快速启动是预启动步法的关键，场上步法不要停，时刻保持灵动移动，根据毽球的旋转、飞行轨迹以及预判的落点，进行快速位移，包括触球移动和无球预启动。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.0070428704,\\\"Lecture\\\":0.963122,\\\"Meeting\\\":0.029835096}}\"', NULL, '已完成', '2025-05-22 16:24:48', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (207, 40, 92, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本功—跳桶.mp4', '72f34d5e7b08449294544a7e0ba2b806', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":39910,\\\"Headline\\\":\\\"翎析智鉴：毽球专项下肢爆发力与敏捷性训练精要\\\",\\\"Summary\\\":\\\"系统讲解通过跳箱训练提升毽球运动员下肢爆发力的专项练习方法，该训练能显著增强脚踝稳定性与腿部弹跳力，改善步法精准度及身体协调性，有效提升快速启动、变向移动及急停转身能力，全面提高场上移动效率、节奏把控与平衡控制等毽球专项素质。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"探讨了毽球专项训练中的跳箱和爆发力两种练习方法。跳箱练习通过跳跃不同高度的箱子来增强弹跳力，建议在热身或训练结束时进行，每组30秒，完成两组，并在力竭后坚持额外跳跃两次。爆发力练习专注于提升下肢力量和弹跳能力，对毽球的起跳、变向、快速移动等动作至关重要，能增强脚踝稳定性、韧带强度，帮助运动员精准控制步法，保持身体平衡，加快启动、变向和转身速度，同时提高下肢爆发力。这些训练能显著提升场上的移动效率、节奏感和平衡控制能力。\\\",\\\"ParagraphTitle\\\":\\\"毽球专项训练：跳箱与爆发力练习方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他在翎析智鉴节目中重点讲解了毽球专项训练中的跳箱练习，特别强调其对增强下肢爆发力与弹跳能力的重要性。建议使用不同高度的跳箱进行训练，在热身或训练结束时进行，每组持续30秒，完成两组，并在力竭后坚持额外跳跃两次。他指出，这种爆发力训练能有效提升脚踝稳定性和韧带强度，有助于运动员更精准地控制步法，保持身体平衡，加快启动、变向和转身速度，从而显著提高下肢爆发力。此外，这些训练对于提升毽球的起跳高度、快速变向、连续移动等专项技术，以及提高场上移动效率、节奏把控和平衡能力都有显著效果，突出了跳箱训练在毽球专项训练中的重要地位。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"跳箱训练如何增强下肢爆发力和弹跳？爆发力训练对毽球运动员的具体益处有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"跳箱训练通过跳跃不同高度的箱子，可以有效增强下肢爆发力和弹跳能力。在热身或训练结束时进行30秒1组两组的跳箱练习，并在力竭后坚持额外跳跃两次。这种训练方式对下肢爆发力和弹跳有显著提升作用，有助于提高运动员的起跳高度、快速变向、连续移动等场上移动效率，同时也能增强节奏把控和平衡能力。爆发力训练能有效增强脚踝稳定性和韧带强度，帮助运动员更精准地控制步法并保持身体平衡。通过爆发力训练，运动员能更快速地完成启动、变向、转身等动作，从而提高下肢爆发力。此外，这种训练还能显著提升场上移动效率，使运动员在比赛中更具节奏把控和平衡能力。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"翎析智鉴 - 毽球专项训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"跳箱训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"使用不同高度跳箱增强下肢弹跳能力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方式: 30秒1组, 进行两组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"进阶要求: 力竭后额外跳跃两次\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"爆发力提升\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"爆发力训练对下肢力量与弹跳有显著效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"关键动作: 起跳、变向、快速移动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"稳定性提升: 增强脚踝稳定性与韧带强度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"控制与平衡: 精准控制步法, 保持身体平衡\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"爆发力增强: 加速启动、变向、转身等动作\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"场上移动与技术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术提升: 起跳高度、快速变向、连续移动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"移动效率: 提升场上移动效率\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"节奏与平衡: 增强节奏把控和平衡能力\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"翎析智鉴\\\",\\\"毽球基本功\\\",\\\"跳箱训练\\\",\\\"弹跳力\\\",\\\"爆发力训练\\\",\\\"下肢力量\\\",\\\"起跳高度\\\",\\\"快速变向\\\",\\\"连续移动\\\",\\\"脚踝稳定性\\\",\\\"韧带强度\\\",\\\"身体平衡\\\",\\\"快速启动\\\",\\\"敏捷移动\\\",\\\"急停转身\\\",\\\"凌空抽射\\\",\\\"场上移动效率\\\",\\\"节奏把控\\\",\\\"平衡能力\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4458,\\\"Text\\\":\\\"欢迎来到翎析智鉴，今天我们系统学习毽球专项基本功训练。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.00916759,\\\"Lecture\\\":0.93349487,\\\"Meeting\\\":0.057337537}}\"', NULL, '已完成', '2025-05-22 16:25:39', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (208, 41, 93, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本功—稳当盘带.mp4', 'ce1f38fa664c471ba0b2a3f73035c3a8', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":24520,\\\"Headline\\\":\\\"翎析智鉴：夯实毽球基本功的高效训练方法\\\",\\\"Summary\\\":\\\"讲解了通过每日坚持不少于200次的毽球训练，在连续练习十天以上后，有助于显著提升控球手感与接球的稳定性，凸显了扎实基本功在毽球专项提升中的关键作用。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"对话强调毽球基本功训练的重要性，特别是控毽与接球技巧，建议每日至少练习200次，持续十天以上以增强球感。指出看似简单的基础动作最难掌握，每个人的领悟不同，卓越表现源于无数次基础训练的积累。\\\",\\\"ParagraphTitle\\\":\\\"毽球基础训练：控毽与接球技巧的重要性\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"欢迎听众参与翎析智鉴的学习分享，他着重强调了基本功对于技能精进的不可或缺性，特别是针对毽球训练中的控毽与接球技巧。他提出，为了增强球感和接球的稳定性，每天至少需要练习200次，且这一过程应持续十天以上。他指出，即便是看似简单的技能，其精通亦需无数次的反复练习与积累。他进一步说明，每个人的领悟能力和进步速度或许各异，但所有精彩的表现无一例外地建立在坚实的基础之上。通过这一分享，他鼓励大家重视基础训练，坚持不懈地练习，以期达到技能的精通。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球的过程中，基本功的重要性是什么？为什么说基本功虽然看似简单，但对运动表现的提升却非常关键？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"基本功在毽球中至关重要，它包括控毽、热身和间歇训练。通过每天坚持200次以上的练习可以显著增强球感。接球稳当不失误也是基本功之一，通过不断练习，可以有效提升稳定性与准确性。尽管基本功看似简单且重复，但其本质是无数次的精准积累，这对提升整体运动表现具有决定性影响。即便是最精彩的控球动作，也离不开扎实的基本功作为支撑。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"翎析智鉴 - 学习毽球基本功\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一、基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"1. 控毽热身或间歇\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"每日至少200次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"坚持十天以上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"目的：增强球感\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"2. 接球技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"稳当不失误\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"持续练习以显著提高\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"二、基本功的重要性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"1. 基础与难度\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"最基本的往往也是最难的\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"每个人的理解不同\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"2. 精彩背后的秘密\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"精彩表现源自基本功的无数次积累\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"所有技术动作都需要扎实基础支撑\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"三、持续性与耐心\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"1. 持之以恒\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"坚持是提高的关键\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"2. 耐心与理解\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"理解基本功的重要性，耐心练习\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"翎析智鉴\\\",\\\"毽球\\\",\\\"基本功\\\",\\\"稳当\\\",\\\"控毽热身\\\",\\\"每天200次\\\",\\\"坚持十天\\\",\\\"增强球感\\\",\\\"接球\\\",\\\"不失误\\\",\\\"提高\\\",\\\"基本功反复练习\\\",\\\"技能差异\\\",\\\"理解\\\",\\\"精彩表现\\\",\\\"基础积累\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.011734151,\\\"Lecture\\\":0.95754004,\\\"Meeting\\\":0.030725844}}\"', NULL, '已完成', '2025-05-22 16:26:16', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (209, 42, 94, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本功—左右高摆腿.mp4', '16cc8c6cfed2474fbdd17ef368d4dc75', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":35310,\\\"Headline\\\":\\\"翎析智鉴：学习毽球基本功与热身技巧\\\",\\\"Summary\\\":\\\"本次讨论聚焦于毽球基本功的训练，特别是左右高抬腿的热身方法，强调了该动作在提升腿部灵活性与稳定性方面的重要作用。同时指出，在技术水平相近的对抗中，比赛成败往往取决于稳定性的持续保持与寻找突破点的能力，展现了竞技毽球比赛在细节与策略上的独特魅力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本次教学聚焦毽球基本功训练，突出左右高抬腿热身运动的重要性，推荐30秒一组的练习，甚至可结合绕凳子进行。强调竞技体育核心在于稳定性和寻找突破，当双方技术水平接近时，比赛胜负取决于谁能更稳定并抓住机会，这是竞技比赛的魅力。同时指出，轻松得分并不意味着实力超群，可能只是实力差距大，这样的胜利缺乏真实感。\\\",\\\"ParagraphTitle\\\":\\\"翎析智鉴：毽球基本功与竞技精髓\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他在翎析智鉴活动中，着重阐述了毽球基本功训练的重要性，特别强调了左右高抬腿作为热身方法的有效性，认为这能显著提升腿部灵活性与身体素质。他指出，在技术水平相当的对局中，比赛的胜负往往取决于选手的稳定性，以及在回合中敏锐捕捉并利用对手破绽的能力，这正是竞技体育的魅力所在。同时，他也提出了对胜利的深度思考，认为如果能够轻易取胜，并非总是代表个人实力的强大，反而可能是因为双方实力悬殊，这样的胜利缺乏真正的价值和意义。因此，他鼓励运动员追求在势均力敌的比赛中展现出色表现，而非仅仅追求轻松取胜。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球基本功时，左右高抬腿热身的作用是什么？在间歇训练中，如何通过左右高抬腿来增强腿部力量？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"左右高抬腿热身能够帮助提高腿部肌肉的灵活性和稳定性，为后续的竞技动作做好准备。在技术水平相近的情况下，谁的稳定性更高，谁就能在比赛中更好地寻找突破点。在间歇训练时，可以采用左右高抬腿30秒一组的方式进行练习，这样既可以锻炼腿部肌肉力量，又能在绕凳子等日常活动中保持身体平衡和协调性。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]},{\\\"Question\\\":\\\"如果比赛中双方实力相当，得分的关键因素是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"当双方实力接近时，得分的关键在于谁更能保持稳定并在回合中准确地寻找并利用对手的破绽进行攻击。如果得分过于轻松，则可能意味着双方实力差距较大。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"翎析智鉴学习指南\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"左右高抬腿热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"目的: 提升腿部灵活性与力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"实践方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"平时练习: 每组30秒, 多组循环\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"结合动作: 绕凳子行走\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"稳定性与突破\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术水平相当时的关键: 稳定性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"竞技比赛魅力: 在回合中寻找突破机会\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"竞技水平判断\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"随便几下得分: 反映双方差距大, 缺乏挑战性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"真正实力展现: 在均衡对抗中寻找得分机会\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"健身功法\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"左右高抬腿\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"功效: 增强腿部肌肉, 提升全身协调性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"实践建议: 作为日常热身或间歇训练的一部分\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"翎析智鉴\\\",\\\"毽球基本功\\\",\\\"左右高抬腿\\\",\\\"热身训练\\\",\\\"间歇练习\\\",\\\"绕凳训练\\\",\\\"健身功法\\\",\\\"腿部柔韧性\\\",\\\"技术稳定性\\\",\\\"竞技突破\\\",\\\"比赛节奏\\\",\\\"控球能力\\\",\\\"得分关键\\\",\\\"实力差距\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":18590,\\\"Text\\\":\\\"欢迎来到翎析智鉴，今天我们将一同学习毽球的基本功训练，重点是左右高抬腿的热身与间歇练习。这项动作不仅能有效激活腿部肌群，还能提升身体协调性。建议每次练习以30秒为一组，可结合绕凳子进行，作为日常健身功法的一部分。想要在毽球中抬腿更高、动作更稳，就需要从科学热身开始。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.029042812,\\\"Lecture\\\":0.9240206,\\\"Meeting\\\":0.04693653}}\"', NULL, '已完成', '2025-05-22 16:27:08', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (210, 43, 95, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本功—左右交叉步.mp4', '5926a62f925c41e082ddef399b9dfe39', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":40470,\\\"Headline\\\":\\\"翎析智鉴：毽球专项交叉步训练提升下肢爆发力\\\",\\\"Summary\\\":\\\"系统讲解毽球专项训练中的交叉步练习方法，重点强化下肢爆发力与协调性训练。通过科学的交叉步训练可显著提升腿部力量与耐力，有效增强场上移动速度，建议持续进行两周专项训练以达到步法轻盈、移动迅捷的训练效果。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"在毽球专项训练中，交叉步被确立为核心热身动作，建议进行30秒/组的训练，完成1-2组直至腿部出现训练反应。课程反复强调\'下肢优先\'训练原则，指出强化腿部爆发力、提升耐力及激活髋关节对步法稳定性的关键作用。心理建设同样重要，应建立科学的训练预期，通过系统提升移动速度和专项耐力来实现技术进步。将交叉步训练纳入日常计划并持续两周，可显著提高下肢力量与灵活性，达到\'步若游龙\'的专项效果。\\\",\\\"ParagraphTitle\\\":\\\"毽球专项下肢训练：交叉步的科学应用\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"教练员\\\",\\\"Summary\\\":\\\"在翎析智鉴的毽球专项课程中，系统讲解了交叉步训练在热身环节的关键价值。该训练通过30秒/组、1-2组的标准化方案，能有效激活下肢肌群并产生良性训练反应。课程着重阐释了\'下肢优先\'的训练理念，强调腿部爆发力、耐力素质及髋关节灵活性的协同发展对步法质量的决定性影响。建议训练者建立阶段性目标，通过持续两周的系统训练，逐步实现从基础力量到专项移动能力的转化，最终达成\'步若游龙\'的竞技状态。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"为什么毽球训练要特别重视下肢训练？如何设计科学的交叉步训练方案？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"毽球运动对下肢能力有特殊要求，主要体现在三个方面：首先，70%的技术动作依赖下肢完成；其次，快速移动能力直接决定攻防转换效率；最后，专项跳跃动作需要强大的爆发力支撑。科学的交叉步训练方案应包含以下要素：采用30秒/组的训练单元，完成1-2组；训练强度以出现良性肌肉反应为度；重点保持髋-膝-踝三关节的协调发力；建议纳入日常训练并持续两周，可系统提升下肢的爆发力、耐力及灵活性。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"翎析智鉴 - 毽球下肢训练体系\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"标准化训练方案\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"交叉步训练参数\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"单组时长:30秒\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组数设置:1-2组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"强度标准:达到训练反应\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"专项能力发展\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"下肢三大素质\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"爆发力:快速移动基础\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"耐力:持续作战保障\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"灵活性:动作完成质量\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"技术支撑体系\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"70%技术依赖下肢\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"三关节协调发力机制\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练进阶路径\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"两周系统训练周期\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"从基础力量到专项转化\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"达成\'步若游龙\'效果\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"翎析智鉴\\\",\\\"专项训练\\\",\\\"交叉步训练\\\",\\\"热身准备\\\",\\\"下肢爆发力\\\",\\\"运动耐力\\\",\\\"髋部灵活性\\\",\\\"步法训练\\\",\\\"移动速度\\\",\\\"训练心态\\\",\\\"日常训练计划\\\",\\\"两周周期\\\",\\\"肌肉激活\\\",\\\"动作幅度\\\",\\\"训练组数\\\",\\\"间歇时间\\\",\\\"力量提升\\\",\\\"关节活动度\\\",\\\"下肢决定论\\\",\\\"轻灵步态\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":3,\\\"Start\\\":28360,\\\"End\\\":33318,\\\"Text\\\":\\\"必须建立科学的训练态度，系统提升移动速度和专项耐力素质。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.010020139,\\\"Lecture\\\":0.9317956,\\\"Meeting\\\":0.058184236}}\"', NULL, '已完成', '2025-05-22 16:27:59', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (211, 44, 96, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/毽球基本技术.mp4', '900f921526404a0aa0d8974e08aa9e40', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":294630,\\\"Headline\\\":\\\"翎析智鉴：毽球核心技术解析与专项训练要诀\\\",\\\"Summary\\\":\\\"系统阐述毽球运动的技术体系及其专项特征，深入剖析脚内侧控球、脚外侧拨球、正脚背抽击、大腿缓冲及胸部停球五大核心技术要领。重点讲解不同身体部位触球时的力学原理，强调髋关节灵活性、动态平衡能力及位置感知对技术完成质量的关键影响，并提供针对性的柔韧性与灵敏素质训练方法。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"毽球技术作为这项运动的根基，随着竞技水平提升而持续演进，具有动作快速、对柔韧灵敏要求严苛、位置技术差异化及攻防一体等鲜明特点。本专题系统讲解脚内侧控球、脚外侧拨球、正脚背抽击、大腿缓冲和胸部停球五大核心技术，详细剖析身体姿态、支撑脚定位、触球部位及发力方式等技术细节，全面展现毽球技术的多元性与精妙之处。\\\",\\\"ParagraphTitle\\\":\\\"翎析智鉴：毽球核心技术体系精解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"专项教练\\\",\\\"Summary\\\":\\\"在翎析智鉴技术讲堂中，系统阐释了毽球核心技术体系的发展脉络与当代特征。重点强调这项运动对动作速度、身体柔韧性及位置技术的特殊要求，深入解析了五大核心技术模块：脚内侧的精准控制、脚外侧的快速拨动、正脚背的强力抽击、大腿的缓冲卸力以及胸部的停球技巧。通过分解身体各环节的协调配合原理，包括支撑脚的稳定定位、触球部位的精确选择以及发力链的科学传导，为运动员提供了一套完整的技术提升方案。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"现代毽球技术体系的核心特征有哪些？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"当代毽球技术呈现四大核心特征：首先是动作的瞬时性，要求在0.3-0.5秒内完成技术动作；其次是身体素质的复合需求，尤其强调髋关节活动度与动态平衡能力；第三是位置的专项化，不同站位需要发展特定的技术组合；最后是攻防的转换性，每个技术动作都需具备攻守双重功能。这些特征共同构成了现代毽球竞技的技术基础。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]},{\\\"Question\\\":\\\"脚内侧控球的技术关键点是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[5,6,7],\\\"Answer\\\":\\\"脚内侧控球需把握三个技术关键：一是建立稳定的三角支撑体系，支撑脚膝关节弯曲约135度；二是触球瞬间脚内侧与球体形成30-45度夹角；三是发力时遵循\'髋带动膝，膝带动踝\'的力学传导顺序，通过下肢动力链的协调发力实现精准控制。\\\",\\\"SentenceIdsOfAnswer\\\":[5,6,7]},{\\\"Question\\\":\\\"如何提升胸部停球的稳定性？\\\",\\\"SentenceIdsOfQuestion\\\":[8,9],\\\"Answer\\\":\\\"优化胸部停球需注重：身体后仰角度控制在15-20度；触球瞬间通过腹肌收缩形成\'卸力平台\'；配合下肢的弹性缓冲，形成从胸部到下肢的连贯缓冲系统。建议通过核心稳定性训练与空间感知训练相结合的方式系统提升。\\\",\\\"SentenceIdsOfAnswer\\\":[8,9]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"翎析智鉴毽球技术体系\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技术特征\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"瞬时性：0.3-0.5秒完成动作\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"复合性：柔韧+灵敏+力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"专项化：位置技术差异\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双重性：攻防转换技术\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"核心技术模块\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚内侧控球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"支撑体系：三角稳定结构\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"触球角度：30-45度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"发力顺序：髋→膝→踝\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"脚外侧拨球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"身体侧倾10-15度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"膝关节内旋发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚背外侧1/3触球\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"正脚背抽击\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"大腿带动鞭打发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"触球点：脚背中部\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"随摆动作完整\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"专项训练方法\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"柔韧性：髋关节活动度训练\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"灵敏性：多向移动训练\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"力量：下肢爆发力训练\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"翎析智鉴\\\",\\\"毽球技术体系\\\",\\\"竞技规则\\\",\\\"专项训练\\\",\\\"教学体系\\\",\\\"赛事应用\\\",\\\"攻防转换技术\\\",\\\"脚内侧控球\\\",\\\"支撑脚定位\\\",\\\"动力腿技术\\\",\\\"空中球处理\\\",\\\"脚外侧拨球\\\",\\\"正脚背抽击\\\",\\\"大腿缓冲\\\",\\\"胸部停球\\\",\\\"动作标准化\\\",\\\"技术进阶\\\",\\\"发展历程\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4760,\\\"Text\\\":\\\"欢迎来到翎析智鉴，今天我们系统解析毽球核心技术体系。\\\"},{\\\"Id\\\":2,\\\"SentenceId\\\":2,\\\"Start\\\":4860,\\\"End\\\":6660,\\\"Text\\\":\\\"第一单元 毽球技术体系概论\\\"},{\\\"Id\\\":3,\\\"SentenceId\\\":3,\\\"Start\\\":7070,\\\"End\\\":19714,\\\"Text\\\":\\\"毽球技术体系是指在竞技规则框架内，运动员所采用的最优化技术组合，是毽球运动的根基与核心竞争力，其发展历程与赛事实践密切关联。\\\"},{\\\"Id\\\":4,\\\"SentenceId\\\":4,\\\"Start\\\":19870,\\\"End\\\":34846,\\\"Text\\\":\\\"随着毽球运动竞技化发展，技术体系持续演进，在教学训练与高水平赛事中，对技术原理的认知、应用与创新不断深化，技术难度系数呈阶梯式提升。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.06437671,\\\"Lecture\\\":0.8356415,\\\"Meeting\\\":0.099981815}}\"', NULL, '已完成', '2025-05-22 16:29:24', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (212, 45, 97, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/零基础入门版—踢毽子跟练教学.mp4', '5dda8efed5a34a9e9df4d3ee9108a0bf', NULL, NULL, NULL, NULL, NULL, '失败', '2025-05-22 16:31:24', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (213, 46, 98, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/零基础入门版—踢毽子跟练教学.mp4', '18d44234474b4f8eb3414046e0892cf1', NULL, NULL, NULL, NULL, NULL, '失败', '2025-05-22 17:37:22', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (214, 47, 98, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/零基础入门版—踢毽子跟练教学.mp4', '4f331270f8e143cea7b066c78ddedc7d', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":646870,\\\"Headline\\\":\\\"毽球零基础系统训练课程\\\",\\\"Summary\\\":\\\"本课程为零基础学员设计的毽球系统训练方案，包含三个阶段：1)热身环节采用提膝下压、提膝外展及交替侧弓步等动态激活练习；2)基础训练部分通过空踢模拟、抛接练习和静态支撑等专项训练，系统培养动作模式建立、神经反应速度及踝关节稳定性；3)恢复环节整合小腿三头肌拉伸、股四头肌牵拉及动态蝴蝶式练习，在促进肌肉恢复的同时强化脚内侧触球的本体感觉。整套课程循序渐进地帮助学员掌握毽球核心技术。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本课程为零基础学员设计的毽球系统训练方案，包含三个阶段：1)热身环节采用提膝下压、提膝外展及交替侧弓步等动态激活练习；2)基础训练部分通过空踢模拟、抛接练习和静态支撑等专项训练，系统培养动作模式建立、神经反应速度及踝关节稳定性；3)恢复环节整合小腿三头肌拉伸、股四头肌牵拉及动态蝴蝶式练习，在促进肌肉恢复的同时强化脚内侧触球的本体感觉。整套课程循序渐进地帮助学员掌握毽球核心技术。\\\",\\\"ParagraphTitle\\\":\\\"毽球零基础系统训练课程\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"专项教练\\\",\\\"Summary\\\":\\\"本课程采用科学的三阶段训练体系：热身阶段通过动态激活练习提升身体柔韧性；基础训练阶段重点培养正确的动作模式和反应能力；恢复阶段注重肌肉放松和技术强化。课程设计遵循运动训练学原理，确保学员安全高效地掌握毽球基本技术。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"毽球训练的热身环节包含哪些内容？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2],\\\"Answer\\\":\\\"热身环节包含三类练习：1)动态激活练习如提膝系列动作；2)关节活动度练习；3)神经激活练习。建议按顺序完成，每组练习间休息30秒。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2]},{\\\"Question\\\":\\\"如何正确进行毽球基础动作训练？\\\",\\\"SentenceIdsOfQuestion\\\":[3,4],\\\"Answer\\\":\\\"基础训练需注意：1)先分解后完整；2)先慢后快；3)先无球后有球。建议从站姿空踢开始，逐步过渡到移动击球。\\\",\\\"SentenceIdsOfAnswer\\\":[3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球训练体系\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"热身阶段\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动态激活\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"提膝系列\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"侧弓步\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"关节活动\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"基础训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作模式\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"空踢练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抛接训练\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"稳定性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"站桩练习\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"恢复阶段\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"肌肉放松\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"下肢拉伸\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"技术强化\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动态蝴蝶式\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球训练\\\",\\\"热身运动\\\",\\\"提膝下压\\\",\\\"提膝外展\\\",\\\"交替侧弓步\\\",\\\"坐姿拉伸\\\",\\\"动态拉伸\\\",\\\"空踢练习\\\",\\\"抛接训练\\\",\\\"平衡练习\\\",\\\"基础动作\\\",\\\"进阶动作\\\",\\\"耐力训练\\\",\\\"恢复放松\\\",\\\"下肢拉伸\\\",\\\"核心力量\\\",\\\"脚部技术\\\",\\\"关节强化\\\",\\\"节奏控制\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.08248832,\\\"Lecture\\\":0.78354335,\\\"Meeting\\\":0.13396838}}\"', NULL, '已完成', '2025-05-22 17:54:04', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (215, NULL, 89, 'https://lxzj.tenir.cn/lxzj/files/2025/05/c7be85c49bb849b3a5b54772082b0351.mp4', 'a92043d3625f4bbba13e9488beff7d91', '视频笔记分析任务131', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":24270,\\\"Headline\\\":\\\"灵犀之剑：提升跑步速度的开合跳热身法\\\",\\\"Summary\\\":\\\"介绍了通过开合跳作为热身方法，以提升跑步速度和增强脚踝力量的技巧。开合跳每次两组，持续20秒，可加速完成，直至腿部感到酸胀并微微出汗。这种方法有助于强化腿部与脚踝力量，同时提高跑步速度以及急停和蹬转的能力。练习时应注意动作幅度，可适当加快节奏。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"主持人介绍了提升跑步基础技能的训练方法，强调开合跳作为热身运动的重要性，建议每次进行20秒，一组两次，直至感到腿部微酸和轻微出汗，这有助于增强腿部和脚踝的力量，从而提高跑步速度。同时指出，为了跑得更快且不感到疲惫，需要有良好的肌肉支撑，特别是在急停、蹬地和转向时，踝关节的力量尤为关键。在练习过程中，应注重动作幅度要大，同时可以逐渐加快速度。\\\",\\\"ParagraphTitle\\\":\\\"提升跑步基础技能的训练方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"欢迎观众参与灵犀之剑的学习环节，本次重点讲解田径基本功训练。他推荐以开合跳作为热身运动，每次持续20秒，一组进行两次，直至感觉到腿部酸胀和微微出汗，这有助于增强腿部和脚踝的力量，从而提升跑步速度。他强调，良好的肌肉支撑对于高效跑步至关重要，特别是在急停、蹬转等动作中，提升踝关节力量更是关键。在实际练习过程中，他提醒大家注意保持大动作幅度，同时适当加快速度，以确保训练效果。通过这种方式，不仅可以加强下肢力量，还能提高跑步技巧和稳定性，为后续的田径训练打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"开合跳热身的目的是什么？如何正确进行开合跳热身练习？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"开合跳热身的目的是为了增强腿部和脚踝力量，提升跑速，通过练习开合跳可以有效提高肌肉支撑能力，对于急停、蹬转等动作的完成至关重要。进行开合跳热身时，需要注意幅度要大，以达到腿部微汗的程度；一组可做两次，并可逐渐加快速度。在练习过程中，确保动作的质量比追求速度更重要。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]},{\\\"Question\\\":\\\"开合跳对跑速的影响是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"良好的开合跳训练能够增强腿部肌肉力量，尤其是脚踝部位，从而在跑步时减少能量消耗，使人跑得更快且不感到疲劳。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"灵犀之剑 - 件球基本功学习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"热身运动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开合跳\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"时间: 20秒\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组数: 2组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"目标状态: 腿部酸胀、微汗\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"效果: 增强腿部与脚踝力量, 提升跑步速度\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"肌肉支撑与踝关节力量提升\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重要性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速跑步不累\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"急停、蹬转动作执行\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"练习要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"幅度要大\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"速度可加快\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"灵犀之剑\\\",\\\"毽球基本功\\\",\\\"开合跳热身\\\",\\\"20秒\\\",\\\"一组两次\\\",\\\"加速\\\",\\\"腿酸胀\\\",\\\"微汗\\\",\\\"增强腿部\\\",\\\"脚踝力量\\\",\\\"提升跑速\\\",\\\"急停蹬转\\\",\\\"踝关节力量\\\",\\\"提升\\\",\\\"练习\\\",\\\"幅度\\\",\\\"速度\\\",\\\"加快\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4496,\\\"Text\\\":\\\"欢迎来到灵犀之剑，今天我们一起来学习毽球基本功。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.005321118,\\\"Lecture\\\":0.9684411,\\\"Meeting\\\":0.026237836}}\"', '<p><br></p>', '已完成', '2025-05-23 20:25:21', '2025-05-23 20:26:53', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (216, NULL, 65, 'https://lxzj.tenir.cn/lxzj/files/2025/04/4968735219624d6e804a5cd715a64c2b.mp4', 'bd3cb9221faf4a8fb128e2b50628536a', '视频笔记分析任务131', '\"[{\\\"Id\\\":1,\\\"Start\\\":1310,\\\"End\\\":142300,\\\"Headline\\\":\\\"足球基本动作教学：内侧、外侧与正脚背踢球技巧\\\",\\\"Summary\\\":\\\"介绍了四种足球基本动作的练习方法，包括单脚内侧踢球、双脚内侧交替踢球、脚外侧踢球以及正脚背踢球的详细技巧与训练方式，强调了正确身体姿势和腿部动作的重要性。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本内容详细介绍了四种足球基础踢球动作的练习方法：一脚内侧踢球、双脚内侧踢球、脚外侧踢球、单脚外侧踢球、正脚背踢球、单脚正脚背踢球以及大腿触球技巧。一脚内侧踢球需双脚自然开立，屈膝下蹲，抬大腿甩小腿完成动作；脚外侧踢球则需重心落在支撑腿上，通过抬大腿、收小腿和勾脚尖完成；正脚背踢球要求大腿带动小腿上抬，踝关节放松，绷紧脚尖并抖动脚踝。每种动作都强调了细节和练习方法，旨在帮助提升足球技能。\\\",\\\"ParagraphTitle\\\":\\\"足球基础踢球动作的练习方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"详细介绍了四种足球基本动作的展示与练习方法。首先，他讲解了一脚内侧踢球，强调双脚自然开立，屈膝微蹲，通过抬大腿甩小腿，保持脚端平的动作要领。接着，介绍了脚外侧踢球，动作类似内侧踢球，但需注意勾脚尖。随后，他讲解了正脚背踢球的技巧，要求大腿带动小腿上抬，踝关节放松，绷紧脚尖，通过抖动脚踝来完成动作。最后，他阐述了大腿触球技巧的练习方法。在整个讲解过程中，他不仅详细描述了每种动作的正确姿势，还提供了单脚和双脚的练习方式，以便于学习者全面掌握这些足球基本动作。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在足球训练中，如何进行单脚内侧踢球的练习？大腿触球这一技术如何在训练中练习？\\\",\\\"SentenceIdsOfQuestion\\\":[2,3],\\\"Answer\\\":\\\"单脚内侧踢球练习时，需保持双脚自然开立，屈膝微微下蹲，抬大腿，然后以脚端平的方式进行踢球动作。虽然文中未详细描述大腿触球的具体练习方法，但可以理解为在特定情况下，利用大腿接触并控制球的运动，这一技术的训练同样注重身体姿势和动作协调性。\\\",\\\"SentenceIdsOfAnswer\\\":[2,3]},{\\\"Question\\\":\\\"双脚内侧踢球练习的正确姿势是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"双脚内侧踢球练习要求双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，同时抬大腿、收小腿、勾脚尖并保持脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"正脚背踢球练习时，身体应如何准备？\\\",\\\"SentenceIdsOfQuestion\\\":[8],\\\"Answer\\\":\\\"进行正脚背踢球练习时，需双脚自然开立，屈膝微微下蹲，大腿带动小腿屈膝上抬，踝关节放松并绷脚尖，同时抖动脚踝以增强灵活性和爆发力。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"足球基本动作练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一脚内侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，甩小腿，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚内侧踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双脚内侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"脚外侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲，重心落在支撑腿上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，收小腿，勾脚尖，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚外侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"正脚背踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝，微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"大腿带动小腿屈膝上抬，踝关节放松\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"绷脚尖，抖动脚踝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚正脚背踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"大腿触球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"通过大腿接触球进行控制或传球练习\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"基本动作\\\",\\\"一脚内侧踢球\\\",\\\"双脚自然分开站立\\\",\\\"屈膝\\\",\\\"微微下蹲\\\",\\\"抬高大腿\\\",\\\"脚面放平\\\",\\\"脚外侧踢球\\\",\\\"重心\\\",\\\"支撑腿\\\",\\\"收起小腿\\\",\\\"勾起脚尖\\\",\\\"正脚背踢球\\\",\\\"大腿带动小腿\\\",\\\"绷紧脚尖\\\",\\\"抖动脚踝\\\",\\\"大腿触球\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.019897494,\\\"Lecture\\\":0.92467904,\\\"Meeting\\\":0.055423494}}\"', '<p><br></p>', '已完成', '2025-05-23 20:38:01', '2025-05-23 20:40:33', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (217, NULL, 87, 'https://lxzj.tenir.cn/lxzj/files/2025/05/9e3aaf3879844e3c8d6a0b0959058bb7.mp4', '16dd128b27d9424997920b6dbd20def9', '视频笔记分析任务141', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":35050,\\\"Headline\\\":\\\"2025年踢毽子教学：平踢与盘踢技巧解析\\\",\\\"Summary\\\":\\\"介绍了2025年踢毽子的两种技巧，平踢和盘踢。重点讲解了平踢的动作要领，包括使用脚内侧踢、右脚正踢的基本方式，以及如何在毽子下落时快速抬腿、屈膝，并用脚内侧将毽子稳稳踢起，同时保持身体的移动与平衡，为下一次踢毽做好准备。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽子的平踢和盘踢两种方法，重点描述了平踢技巧。平踢以脚内侧踢毽，右脚正踢为最基本踢法。准备时，两脚稍分开站立，右手将毽子置于胸前轻轻抛起。毽子下落至腰部高度时，迅速抬起右腿，屈膝并向内摆小腿，用脚内侧将毽子踢起。踢完后，右脚落地一次，左脚迅速跟随毽子移动一小步，准备第二次踢毽。每次踢起的毽子高度应超过腰部。\\\",\\\"ParagraphTitle\\\":\\\"踢毽子技巧：平踢方法详解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"介绍了踢毽子的两种基本方法，首先是平踢技巧，这是踢毽子中最基础的踢法。他详细描述了平踢的动作过程：在预备阶段，站立时两脚应稍微分开，用右手将毽子置于胸前，掌心向上轻轻抛起。当毽子下落到与腰部同高的位置时，右腿迅速抬起，膝盖弯曲，小腿向内摆动，用脚内侧将毽子踢起。踢起毽子后，右脚落地一次，随后左脚迅速移动一小步以准备第二次踢毽。他强调，每次踢起的毽子高度一般应超过腰部位置，以保证踢毽的连贯性和技巧性。此外，他还提到了另一种踢法——盘踢，但未详细阐述，主要聚焦于平踢的技巧讲解。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"平踢毽子的基本步骤是什么？盘踢毽子的基本踢法是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5],\\\"Answer\\\":\\\"平踢毽子的基本步骤包括：预备时双脚稍分开，自然站立，右手将毽子置于胸前并向上抛起。当毽子下落到与腰同高时，右腿迅速拾起、屈膝，小腿向里摆动，用脚内侧将毽子踢起，随后右脚落地，左脚随毽子移动一小步，准备进行下一次踢毽子动作。每次踢起的毽子高度通常会超过腰部位移。盘踢毽子的基本踢法主要包括：首先，预备姿势与平踢相似，两脚稍分开，右手持毽子于胸前，掌心向上，轻轻抛起。然后，在毽子下落至与腰同高的瞬间，迅速用脚内侧或脚面进行连续快速的盘旋踢，每次踢起后，毽子应保持一定的旋转并在空中画出弧线。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5]},{\\\"Question\\\":\\\"踢毽子时，脚部的具体部位如何接触毽子？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5],\\\"Answer\\\":\\\"在踢毽子过程中，无论是平踢还是盘踢，都需要根据不同的踢法使用脚的不同部位接触毽子。平踢主要使用脚内侧踢，而盘踢则可以采用脚内侧或脚面进行连续盘旋踢。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽子方法介绍\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"平踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"预备姿势: 两脚稍分开，自然站立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"持毽准备: 右手将毽置于胸前，掌心向上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抛毽: 轻轻将毽抛起\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽时机: 当毽子下落到与膝盖同高时\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右腿迅速抬起，屈膝\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小腿向里摆动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"用脚内侧将毽子踢起\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"后续动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右脚落地\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"左脚迅速随毽子移动一小步\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"准备踢第二次\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"每次踢起的毽子高度一般高过腰部\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"说明\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"本次介绍未详细阐述盘踢的具体步骤，但通常盘踢涉及使用脚的外侧或脚背踢毽子，需要较高的技巧和控制力。\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"基本概念\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"盘踢是一种高级踢法，相较于平踢，更注重于毽子的控制和方向变化。\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽子\\\",\\\"平踢\\\",\\\"盘踢\\\",\\\"脚内侧\\\",\\\"右脚正踢\\\",\\\"预备\\\",\\\"两脚稍分开\\\",\\\"自然站立\\\",\\\"毽子\\\",\\\"抛起\\\",\\\"与膝同高\\\",\\\"右腿迅速抬起\\\",\\\"屈膝\\\",\\\"小腿向内摆动\\\",\\\"右脚落地\\\",\\\"踢第二次\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4940,\\\"Text\\\":\\\"今天我们为大家介绍踢毽子的两种方法：平踢和盘踢。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.017245777,\\\"Lecture\\\":0.93244404,\\\"Meeting\\\":0.050310146}}\"', '<p><br></p>', '已完成', '2025-05-23 20:49:19', '2025-05-23 20:50:41', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (218, NULL, 95, 'https://lxzj.tenir.cn/lxzj/files/2025/05/db2d19751e8c46a7b9178a052b1506fc.mp4', '5028086ce6a14e6d837078de8a1d9160', '视频笔记分析任务151', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":40470,\\\"Headline\\\":\\\"灵犀之剑：学习左右交叉步增强腿部力量\\\",\\\"Summary\\\":\\\"在2025年05月23日的训练中，重点学习了左右交叉步作为基本功热身，强调了腿部力量的重要性。通过增强腿部力量和耐力，可以提高跑动速度，建议坚持练习半个月，以提升腿脚贴地滑行的感觉。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"在件球训练中，左右交叉步作为基本功的热身或间歇练习至关重要。建议进行30秒一组的左右交叉步，重复两组，注意下蹲幅度至腿部酸胀，坚持完成十个动作。对话强调“练功先练腿”，指出增强腿部力量、提高耐力和活动髋关节对步伐的七分之重要性。通过加强跑动速度和耐力，避免急功近利，持续半个月的练习，可显著提升腿部力量，达到“腿脚贴地飞”的效果。左右交叉步应作为日常热身的常规项目，以提升整体运动表现。\\\",\\\"ParagraphTitle\\\":\\\"强化腿部力量：左右交叉步训练的重要性与方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他在灵犀之剑的课程中强调了腿部力量在剑术基本功训练中的重要性，指出腿部训练不仅能够提高耐力，还能有效活动髋关节。他推荐通过左右交叉步热身，这是一种能够全面提升腿部灵活性和速度的有效方法。为了增强腿部力量，他建议进行下蹲训练至感到酸胀并坚持做十个，将这一动作纳入日常热身项目中。他强调，坚持半个月后，练习者将能显著感受到腿部灵活性和速度的提升。此外，他还特别强调了心态的重要性，认为加强跑动速度和耐力是实现剑术目标的基础，良好的心态是持续进步的关键。通过这些训练方法和心态调整，能够为剑术学习者打下坚实的基础，提升其整体剑术水平。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习太极拳等内功时，为什么首先要练习腿部基本功？如何进行有效的腿部热身或间歇训练？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"练功先练腿，因为腿部力量的强弱直接影响到整体的运行速度和耐力，而步伐的灵活性与稳定性又取决于腿部的活动情况。加强腿部训练是提升整体功夫的基础，没有良好的腿部支撑和移动能力，后续的招式练习将难以有效执行。可以采用左右交叉步进行热身或间歇训练，保持下蹲幅度适中，感觉到肌肉酸胀后坚持十个，每组做两到三组。这个动作作为日常热身项目，坚持半个月后，可以显著增强腿部力量、提高耐力并活动髋关节。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]},{\\\"Question\\\":\\\"为何要将热身项目坚持半个月才能看到效果？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"通过长期坚持同一套热身动作，让身体适应并逐步增强肌肉力量和耐力，从而达到腿脚灵活、力量提升的效果。短期的训练很难立刻见效，需要持续的练习才能实现显著改变。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"灵犀之剑 - 件球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"热身与间歇训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"左右交叉步\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"持续时间: 30秒/组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组数: 2组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"注意事项: 下蹲幅度适当, 感受酸胀感后再坚持10个动作\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练重点: 腿部力量与耐力\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"练功先练腿\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强腿部力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"活动髋关节\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"步伐的重要性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"步伐占整体表现的7分\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"步伐质量取决于腿部力量\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练目标与心态\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"必须加强跑动速度和耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"避免妄求心态\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"专注于基础训练\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"先确保能够达到基础要求\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练效果预期\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"常规日常热身项目\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"坚持半个月后\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"腿脚贴地飞\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"显著提升腿部力量与灵活性\\\",\\\"Topic\\\":[]}]}]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"灵犀之剑\\\",\\\"基本功\\\",\\\"左右交叉步\\\",\\\"热身\\\",\\\"腿部力量\\\",\\\"耐力\\\",\\\"髋关节\\\",\\\"步伐\\\",\\\"跑动速度\\\",\\\"心态\\\",\\\"日常热身\\\",\\\"半个月\\\",\\\"酸胀感\\\",\\\"下蹲幅度\\\",\\\"一组两组\\\",\\\"30秒\\\",\\\"增强\\\",\\\"活动\\\",\\\"取决于腿\\\",\\\"贴地飞\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":3,\\\"Start\\\":28360,\\\"End\\\":33318,\\\"Text\\\":\\\"不追求过高的心态，必须提升跑动速度和耐力。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.010020139,\\\"Lecture\\\":0.9317956,\\\"Meeting\\\":0.058184236}}\"', '<p><br></p>', '已完成', '2025-05-23 21:20:55', '2025-05-23 21:21:39', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (219, NULL, 65, 'https://lxzj.tenir.cn/lxzj/files/2025/04/4968735219624d6e804a5cd715a64c2b.mp4', '2f142fbeda1f4772a510f1e23e9fe570', '视频笔记分析任务161', '\"[{\\\"Id\\\":1,\\\"Start\\\":1310,\\\"End\\\":142300,\\\"Headline\\\":\\\"足球基本动作教学：内侧、外侧与正脚背踢球技巧\\\",\\\"Summary\\\":\\\"介绍了四种足球基本动作的练习方法，包括单脚内侧踢球、双脚内侧交替踢球、脚外侧踢球以及正脚背踢球的技巧与练习方式，强调了正确的身体姿势和脚部动作。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本内容详细介绍了四种足球基础踢球动作的练习方法：一脚内侧踢球、双脚内侧踢球、脚外侧踢球、单脚外侧踢球、正脚背踢球、单脚正脚背踢球以及大腿触球技巧。一脚内侧踢球需双脚自然开立，屈膝下蹲，抬大腿甩小腿，脚端保持平直。脚外侧踢球同样要求双脚自然开立，屈膝下蹲，重心在支撑腿上，通过抬大腿、收小腿和勾脚尖完成动作，脚端同样保持平直。正脚背踢球要求双脚自然开立并屈膝，大腿带动小腿上抬，踝关节放松，绷紧脚尖并抖动脚踝完成动作。此外，还强调了单脚正脚背踢球的练习和大腿触球技巧。每个动作的细节和练习方法都被详细描述，以帮助练习者掌握正确的足球踢球技巧。\\\",\\\"ParagraphTitle\\\":\\\"足球基础踢球动作的练习方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"介绍了四种基本的足球踢球动作。首先，他讲解了一脚内侧踢球，强调双脚自然开立，屈膝微微下蹲，通过抬大腿、甩小腿，保持脚端平，进行单脚和双脚内侧踢球练习。其次，他介绍了脚外侧踢球，同样需要双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，抬大腿，收小腿，勾脚尖，脚端平，进行单脚外侧踢球练习。接着，他讲解了正脚背踢球的动作要领，包括双脚自然开立，屈膝，微微下蹲，大腿带动小腿屈膝上抬，踝关节放松，绷脚尖，抖动脚踝，进行单脚正脚背踢球练习。最后，他提到了大腿触球的动作，虽然没有详细描述，但可以理解为利用大腿来控制或接球的一种技巧。他的发言内容涵盖了足球踢球的基本动作，为初学者提供了清晰的指导。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在足球训练中，如何进行单脚内侧踢球的练习？大腿触球这一技术如何在训练中练习？\\\",\\\"SentenceIdsOfQuestion\\\":[2,3],\\\"Answer\\\":\\\"单脚内侧踢球练习时，需保持双脚自然开立，屈膝微微下蹲，抬大腿，然后以脚端平的方式进行踢球动作。虽然文中未详细描述大腿触球的具体练习方法，但可以理解为在特定情况下，利用大腿接触并控制球的运动，这一技术的训练同样注重身体姿势和动作协调性。\\\",\\\"SentenceIdsOfAnswer\\\":[2,3]},{\\\"Question\\\":\\\"双脚内侧踢球练习的正确姿势是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"双脚内侧踢球练习要求双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，同时抬大腿、收小腿、勾脚尖并保持脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"正脚背踢球练习时，身体应如何准备？\\\",\\\"SentenceIdsOfQuestion\\\":[8],\\\"Answer\\\":\\\"进行正脚背踢球练习时，需双脚自然开立，屈膝微微下蹲，大腿带动小腿屈膝上抬，踝关节放松并绷脚尖，同时抖动脚踝以增强灵活性和爆发力。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"足球基本动作练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一脚内侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，甩小腿，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚内侧踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双脚内侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"脚外侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心落在支撑腿上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，收小腿，勾脚尖，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚外侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"正脚背踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝，微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"大腿带动小腿屈膝上抬\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踝关节放松，绷脚尖，抖动脚踝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚正脚背踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"大腿触球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"通过大腿接触球进行控制或传球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"注意身体平衡和球的接触点\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"基本动作\\\",\\\"一脚内侧踢球\\\",\\\"双脚自然分开站立\\\",\\\"屈膝\\\",\\\"微微下蹲\\\",\\\"抬起大腿\\\",\\\"脚面放平\\\",\\\"脚外侧踢球\\\",\\\"重心\\\",\\\"支撑腿\\\",\\\"收起小腿\\\",\\\"勾起脚尖\\\",\\\"正脚背踢球\\\",\\\"大腿带动小腿\\\",\\\"绷紧脚尖\\\",\\\"抖动脚踝\\\",\\\"大腿触球\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.019897494,\\\"Lecture\\\":0.92467904,\\\"Meeting\\\":0.055423494}}\"', '<p><br></p>', '已完成', '2025-05-23 21:31:16', '2025-05-23 21:32:19', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (220, NULL, 89, 'https://lxzj.tenir.cn/lxzj/files/2025/05/c7be85c49bb849b3a5b54772082b0351.mp4', '4f29c69ff0f347948751f0959ba1c30a', '视频笔记分析任务131', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":24270,\\\"Headline\\\":\\\"灵犀之剑：提升跑步速度的开合跳热身法\\\",\\\"Summary\\\":\\\"介绍了通过开合跳作为热身方法，以提升跑步速度和增强脚踝力量的技巧。强调了良好的肌肉支撑与踝关节力量对提高跑步效率的重要性，并建议练习时动作幅度要大，速度可逐渐加快。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"主持人介绍了提升跑步基础技能的训练方法，强调开合跳作为热身运动的重要性，建议每次进行20秒，一组两次，直至感到腿部微酸和轻微出汗，这有助于增强腿部和脚踝的力量，从而提高跑步速度。同时指出，为了跑得更快且不感到疲惫，需要有良好的肌肉支撑，特别是在急停、蹬地和转向时，踝关节的力量尤为关键。在练习过程中，应注重动作幅度要大，同时可以逐渐加快速度。\\\",\\\"ParagraphTitle\\\":\\\"提升跑步基础技能的训练方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"欢迎观众参与灵犀之剑的学习节目，本次分享的主题虽然是乒乓球基本功，但实际讨论的是提升跑步速度和耐力的热身运动——开合跳。他建议进行20秒的开合跳热身，一组两次，速度可以逐渐加快，直至感觉到腿部酸胀并微微出汗。这有助于增强腿部和脚踝的力量，从而提高跑步速度。他强调，良好的肌肉支撑对于跑步效率至关重要，特别是对于需要急停、蹬地和转身的动作，这些动作特别依赖于踝关节的力量。在练习开合跳时，他提醒大家注意动作幅度要大，同时可以逐步提高速度，以达到最佳的热身效果。通过这样的热身运动，可以有效提升跑步时的腿部和脚踝支撑力，进而提高跑步速度和耐力。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"开合跳热身的目的是什么？开合跳热身应该如何进行？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"开合跳热身的目的是为了增强腿部和脚踝力量，提升跑速，通过练习开合跳可以有效提高腿部肌肉的支撑能力和急停、蹬转时的踝关节力量。进行开合跳热身时，建议以20秒一组，每组做两次，并逐渐加快速度至腿部有微汗和酸胀感为止。这样不仅能够增强腿部力量，还能有效预防运动伤害，为后续高强度运动做好准备。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"灵犀之剑 - 件球基本功学习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"热身运动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开合跳\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"时间: 20秒\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组数: 2组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"目标状态: 腿部酸胀、微汗\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"效果: 增强腿部与脚踝力量, 提升跑步速度\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"肌肉支撑与踝关节力量提升\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重要性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速跑步不累\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"急停、蹬转动作执行\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"练习要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"幅度要大\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"速度可加快\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"灵犀之剑\\\",\\\"毽球基本功\\\",\\\"开合跳热身\\\",\\\"20秒\\\",\\\"一组两次\\\",\\\"加速\\\",\\\"腿酸胀\\\",\\\"微汗\\\",\\\"增强腿部\\\",\\\"脚踝力量\\\",\\\"提升跑速\\\",\\\"急停蹬转\\\",\\\"踝关节力量\\\",\\\"提升\\\",\\\"练习\\\",\\\"幅度\\\",\\\"速度\\\",\\\"加快\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4496,\\\"Text\\\":\\\"欢迎来到灵犀之剑，今天我们一起来学习毽球基本功。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.005321118,\\\"Lecture\\\":0.9684411,\\\"Meeting\\\":0.026237836}}\"', '<p><br></p>', '已完成', '2025-05-23 21:33:35', '2025-05-23 21:36:22', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (221, NULL, 92, 'https://lxzj.tenir.cn/lxzj/files/2025/05/efd74e3d08d3489e9ed489f8a6bf7fc3.mp4', '4a6191e963114c768853af6c055fc5f9', '视频笔记分析任务141', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":39910,\\\"Headline\\\":\\\"2025年灵犀之剑：提升毽球基本功与腿部力量\\\",\\\"Summary\\\":\\\"在2025年05月23日，本次讨论聚焦于通过跳筒练习增强毽球基本功，特别强调了跳筒对提升腿部力量、弹跳力和脚踝韧性的效果。这种训练有助于改善毽球运动中的跳杀、飞踏、跑动技巧，增强爆发力和场上移动效率，提高运动员的节奏感和平衡能力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论了足球训练中的跳筒和多泵两种练习方法。跳筒练习通过跳跃放置在腿边的长筒，旨在增强运动员的弹跳力，建议在间歇或拉伸结束时进行，每次30秒，分为两组，直至极限再额外跳两下。多泵练习则侧重提升腿部力量和弹跳能力，对跳杀、飞踏、跑动等动作至关重要，能有效增强脚踝力量、韧带强度，帮助运动员控制脚步，保持身体稳定，加快启动、移动和转身速度，同时增强腿部爆发力。这些练习有助于提高场上的移动效率、节奏感和平衡能力。\\\",\\\"ParagraphTitle\\\":\\\"足球基本功训练：跳筒与多泵练习方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他在灵犀之剑节目中强调了足球基本功训练中跳筒练习的关键作用，尤其指出其对增强腿部力量与弹跳能力的重要性。他建议在腿部旁边放置长筒跳筒，于间歇或结束拉伸时进行练习，每次持续30秒，分两组进行，直至达到个人极限。他指出，多泵练习能有效提升脚踝力量和韧带强度，帮助球员更好地控制脚步，保持身体稳定，同时加快启动、移动和转身速度，从而增强腿部爆发力。这些训练方法不仅有助于提高球员的起跳、扣杀、跳起倒钩、凌空抽射等技巧，还能提升场上的移动效率，增强节奏感和平衡能力，全面促进球员的技能提升和比赛表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"跳筒训练如何增强腿部力量和弹跳？跳筒训练对运动员场上移动效率和节奏感有何影响？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"跳筒训练通过在腿边放置长筒并进行跳跃练习，可以有效增强腿部力量和弹跳能力。在间歇或结束时进行30秒至1组的跳筒练习，连续跳到无法再跳为止，这样能锻炼腿部肌肉，提高脚踝力量和韧带强度，从而更好地控制脚步、保持身体稳定，并能更快速地完成启动、移动、转身等动作，同时增强腿部爆发力。通过跳筒训练，运动员能有效提升场上移动效率，增强节奏感和平衡。这种训练方式有助于提高起跳、扣杀、跳起倒钩、凌空抽射等技术动作的表现，使运动员在比赛中的移动更为敏捷，更能适应比赛节奏的变化。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"灵犀之剑 - 件球基本功学习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"跳筒训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"设备: 长筒跳筒\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"将跳筒置于腿边\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"每次训练30秒, 分为两组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"跳至极限后再尝试跳两下\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"目标: 增强腿部力量与弹跳能力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"力量与弹跳提升\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"多泵练习: 提升腿部力量与弹跳\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"应用动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"跳杀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"飞踏\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"跑动\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"额外益处:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强脚踝力量与韧带强度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"改善脚步控制与身体稳定性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"加速启动、移动与转身\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"爆发力与移动效率\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"技能增强:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"起跳\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"扣杀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"跳起倒钩\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"凌空抽射\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"提高场上移动效率\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"增强节奏感与平衡\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"总结\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"核心: 跳筒训练与多泵练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"目标: 增强腿部力量、弹跳、爆发力与移动效率\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"结果: 改善场上表现, 提升节奏感与平衡\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"灵犀之剑\\\",\\\"毽球基本功\\\",\\\"跳筒\\\",\\\"弹跳\\\",\\\"腿部力量\\\",\\\"多泵\\\",\\\"脚踝力量\\\",\\\"韧带强度\\\",\\\"身体稳定\\\",\\\"启动\\\",\\\"移动\\\",\\\"转身\\\",\\\"爆发力\\\",\\\"起跳\\\",\\\"扣杀\\\",\\\"跳起倒钩\\\",\\\"凌空抽射\\\",\\\"场上移动效率\\\",\\\"节奏感\\\",\\\"平衡\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4458,\\\"Text\\\":\\\"欢迎来到灵犀之剑，今天我们一起来学习毽球基本功。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.00916759,\\\"Lecture\\\":0.93349487,\\\"Meeting\\\":0.057337537}}\"', '<p><br></p>', '已完成', '2025-05-23 21:35:21', '2025-05-23 21:36:16', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (222, NULL, 89, 'https://lxzj.tenir.cn/lxzj/files/2025/05/c7be85c49bb849b3a5b54772082b0351.mp4', '2cd60d1c2b1d4f6aba2c0fcf56800c16', '视频笔记分析任务131', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":24270,\\\"Headline\\\":\\\"灵犀之剑：提升跑步速度的开合跳热身法\\\",\\\"Summary\\\":\\\"介绍了通过开合跳作为热身方法，以提升跑步速度和增强脚踝力量的技巧。开合跳每次两组，每组持续20秒，可适当加速，直到感觉腿部酸胀并微微出汗。这种方法有助于强化腿部与脚踝的力量，提高跑步速度以及急停和蹬转的能力。练习时需注意动作幅度，可以适度加快速度。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本次对话强调了开合跳作为跑步前热身运动的重要性，建议每次进行20秒，一组两次，直至感到腿部微酸和轻微出汗，这有助于增强腿部和脚踝的力量，从而提高跑步速度。为了在跑步过程中不感到疲惫并能跑得更快，需要有良好的肌肉支撑，特别是在急停、蹬地和转向时，踝关节的力量尤为关键。在练习开合跳时，应注重动作幅度要大，同时可以逐渐加快速度，以此来提升跑步的基本功和效率。\\\",\\\"ParagraphTitle\\\":\\\"提升跑步速度与效率的训练方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他欢迎观众参与灵犀之剑的学习节目，本次主题虽为乒乓球基本功，但实际分享了提升跑步速度与耐力的热身运动——开合跳。他建议进行20秒的开合跳热身，每组两次，速度逐渐加快，直至感受到腿部酸胀与微汗，这有助于增强腿部与脚踝的力量，从而提升跑步速度。他强调，良好的肌肉支撑对跑步效率至关重要，特别是对于急停、蹬地与转身等动作，这些动作特别依赖于踝关节的力量。在练习开合跳时，他提醒大家注意动作幅度要大，同时可以逐步提高速度，以达到最佳训练效果。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"开合跳热身的目的是什么？如何正确进行开合跳热身练习？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"开合跳热身的目的是为了增强腿部和脚踝力量，提升跑速，通过练习开合跳可以有效提高腿部肌肉的支撑能力和急停、蹬转时的踝关节力量。进行开合跳热身时，需要注意幅度要大，速度可根据个人情况逐渐加快，目标是达到腿部微汗、感觉腿部酸胀的状态。每组做两次，可以适当加速，但要注意保持动作的质量和对身体的适应性。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]},{\\\"Question\\\":\\\"开合跳热身对提高跑速和减少疲劳有何帮助？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4],\\\"Answer\\\":\\\"开合跳热身能增强腿部肌肉尤其是脚踝的力量，这对于跑得更快且保持持久耐力至关重要。良好的肌肉支撑能有效降低跑步过程中因力量不足导致的疲劳感，并有助于提高跑步效率。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"灵犀之剑 - 件球基本功学习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"热身运动\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开合跳\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"时间: 20秒\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组数: 2组\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"目标状态: 腿部酸胀、微汗\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"效果: 增强腿部与脚踝力量, 提升跑步速度\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"肌肉支撑与踝关节力量提升\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重要性\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速跑步不累\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"急停、蹬转动作执行\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"练习要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"幅度要大\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"速度可加快\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"灵犀之剑\\\",\\\"毽球基本功\\\",\\\"开合跳热身\\\",\\\"20秒\\\",\\\"一组两次\\\",\\\"加速\\\",\\\"腿酸胀\\\",\\\"微汗\\\",\\\"增强腿部\\\",\\\"脚踝力量\\\",\\\"提升跑速\\\",\\\"急停蹬转\\\",\\\"踝关节力量\\\",\\\"提升\\\",\\\"练习\\\",\\\"幅度\\\",\\\"速度\\\",\\\"加快\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4496,\\\"Text\\\":\\\"欢迎来到灵犀之剑，今天我们一起来学习毽球基本功。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.005321118,\\\"Lecture\\\":0.9684411,\\\"Meeting\\\":0.026237836}}\"', '<p><br></p>', '已完成', '2025-05-23 21:40:51', '2025-05-23 21:42:07', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (223, NULL, 87, 'https://lxzj.tenir.cn/lxzj/files/2025/05/9e3aaf3879844e3c8d6a0b0959058bb7.mp4', '708386ffef5f4f8caef2e6f0b4af3a17', '视频笔记分析任务141', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":35050,\\\"Headline\\\":\\\"2025年踢毽子教学：平踢与盘踢技巧解析\\\",\\\"Summary\\\":\\\"介绍了2025年踢毽子的两种方法——平踢和盘踢。重点讲解了平踢技巧，包括使用脚内侧踢、右脚正踢的基本动作，以及如何在毽子下落时快速抬腿、屈膝，并用脚内侧将毽子踢起，同时保持身体移动和平衡，以准备下一次踢毽。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽子的平踢和盘踢两种方法，重点描述了平踢技巧。平踢以脚内侧踢毽，右脚正踢为最基本踢法。准备时，两脚稍分开站立，右手将毽子置于胸前轻轻抛起。当毽子降至腰部高度时，右腿迅速抬起，用脚内侧踢毽，随后右脚落地，左脚迅速移动准备下一次踢毽，每次踢起的毽子高度需超过腰部。\\\",\\\"ParagraphTitle\\\":\\\"踢毽子技巧：平踢方法详解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"介绍了踢毽子的两种基本方法，首先是平踢技巧，这是踢毽子中最基础的踢法。平踢使用脚内侧来踢毽子，具体步骤如下：首先，站立时双脚应稍微分开，右手将毽子置于胸前，掌心向上轻轻抛起毽子。当毽子下落到与腰部同高时，迅速抬起右腿，屈膝并使小腿向内摆动，用脚内侧将毽子踢起。踢起后，右脚落地一次，接着左脚迅速移动一小步以准备第二次踢毽。每次踢起的毽子高度一般应超过腰部位置。此外，他还提到了另一种踢法——盘踢，但并未详细展开。通过平踢的介绍，他强调了踢毽子技巧的基本要领，包括站立姿势、抛毽子、踢毽子的时机和踢毽子后的准备动作。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"盘踢毽子的基本踢法是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5],\\\"Answer\\\":\\\"盘踢毽子的基本踢法主要包括：首先，预备姿势与平踢相似，两脚稍分开，右手持毽子于胸前，掌心向上，轻轻抛起。然后，在毽子下落至与髋部同高的瞬间，右腿快速提起并屈膝，小腿内摆，用脚内侧将毽子踢起，接着右脚落地，左脚随之移动一小步，完成第一次踢毽子。每次踢起的毽子高度也应超过腰部位移。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽子方法介绍\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"平踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"预备姿势: 两脚稍分开，自然站立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"持毽准备: 右手将毽置于胸前，掌心向上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抛毽: 轻轻将毽抛起\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽时机: 当毽子下落到与膝盖同高时\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右腿迅速抬起，屈膝\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小腿向里摆动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"用脚内侧将毽子踢起\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"后续动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右脚落地\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"左脚迅速随毽子移动一小步\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"准备踢第二次\\\",\\\"Topic\\\":[]}]}]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"每次踢起的毽子高度一般高过腰部\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"注意: 未在原文中详细描述盘踢方法, 以下为一般盘踢技巧概述\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"基本动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"预备姿势: 类似平踢，但准备踢毽的脚呈盘状\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"利用脚踝和小腿的旋转力量\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"用脚外侧或脚底边缘踢毽子\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"控制技巧: 通过调整脚部角度和力度控制毽子的方向和高度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"强调脚部灵活性和控制力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"练习时注意身体平衡\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽子\\\",\\\"平踢\\\",\\\"盘踢\\\",\\\"脚内侧\\\",\\\"右脚正踢\\\",\\\"预备\\\",\\\"两脚稍分开\\\",\\\"自然站立\\\",\\\"毽子\\\",\\\"抛起\\\",\\\"下落\\\",\\\"羽西同高\\\",\\\"屈膝\\\",\\\"小腿向里摆\\\",\\\"踢起\\\",\\\"落地\\\",\\\"腰部位移\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4940,\\\"Text\\\":\\\"今天我们为大家介绍踢毽子的两种方法：平踢和盘踢。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.017245777,\\\"Lecture\\\":0.93244404,\\\"Meeting\\\":0.050310146}}\"', '<p><br></p>', '已完成', '2025-05-23 21:41:24', '2025-05-23 21:41:44', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (224, NULL, 87, 'https://lxzj.tenir.cn/lxzj/files/2025/05/9e3aaf3879844e3c8d6a0b0959058bb7.mp4', '79f464d307434900a42a77877d89f947', '视频笔记分析任务151', '\"[{\\\"Id\\\":1,\\\"Start\\\":30,\\\"End\\\":35050,\\\"Headline\\\":\\\"2025年踢毽子教学：平踢与盘踢技巧解析\\\",\\\"Summary\\\":\\\"介绍了2025年踢毽子的两种方法——平踢和盘踢。重点讲解了平踢技巧，包括使用脚内侧踢、右脚正踢的基本动作，以及如何在毽子下落时快速抬腿、屈膝，并用脚内侧将毽子踢起，同时保持身体的移动与平衡，为下一次踢毽做好准备。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"介绍了踢毽子的平踢和盘踢两种方法，重点描述了平踢技巧。平踢以脚内侧踢毽，右脚正踢为最基本踢法。准备时，两脚稍分开站立，右手将毽子置于胸前轻轻抛起。毽子下落至腰部高度时，迅速抬起右腿，屈膝并向内摆小腿，用脚内侧将毽子踢起。踢完后，右脚落地一次，左脚随毽子移动一小步，准备第二次踢毽。每次踢起的毽子高度需超过腰部。\\\",\\\"ParagraphTitle\\\":\\\"踢毽子技巧：平踢方法详解\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"介绍了踢毽子的两种基本方法，首先是平踢技巧，这是踢毽子中最基础的踢法。他详细描述了平踢的动作过程：在预备阶段，站立时两脚应稍微分开，用右手将毽子置于胸前，掌心向上轻轻抛起。当毽子下落到与腰部同高的位置时，迅速抬起右腿，屈膝并使小腿向内摆动，利用脚内侧将毽子踢起。踢毽子时，右脚在踢完后会落地一次，接着左脚向毽子移动一小步，为第二次踢毽做准备。通常情况下，每次踢起的毽子高度需要超过腰部位置。通过这些步骤，他清晰地阐述了平踢这一基础踢毽子技巧的执行过程。此外，他还提到了另一种踢法——盘踢，但并未详细展开。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"盘踢毽子的基本踢法是怎样的？平踢和盘踢两种方法有何不同之处？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3,4,5],\\\"Answer\\\":\\\"盘踢毽子的基本踢法主要包括：首先，预备姿势与平踢相似，两脚稍分开，右手持毽子于胸前，掌心向上，轻轻抛起。然后，在毽子下落至与腰同高时，左腿快速提起、屈膝，用脚内侧勾住毽子并向上踢起，同时左脚落地，右脚随毽子移动一小步，准备下一次踢毽子。这个过程中，每次踢起的毽子高度也较高。平踢和盘踢两种踢毽子方法的主要区别在于脚部接触毽子的部位和踢法。平踢是通过脚内侧来踢，而盘踢则是利用脚内侧勾住毽子并向上踢起。另外，从动作顺序上来看，平踢是右脚正踢开始，主要以右脚为主进行连续踢动；而盘踢则是以左脚提起勾住毽子开始，以左脚为主进行连续踢动，两个方法在操作细节和主导脚上有所不同。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3,4,5]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"踢毽子方法介绍\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"平踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"预备姿势: 两脚稍分开，自然站立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"持毽准备: 右手将毽置于胸前，掌心向上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抛毽: 轻轻抛起毽子\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽时机: 当毽子下落到与腰部同高时\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右腿迅速抬起，屈膝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿向里摆动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"用脚内侧将毽子踢起\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"后续动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"右脚落地\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"左脚迅速随毽子移动一小步\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"准备踢第二次\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"每次踢起的毽子高度一般高过腰部\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"盘踢\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"注意: 未在原文中详细描述盘踢方法, 以下为一般盘踢技巧概述\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"基本动作描述\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"预备姿势: 类似平踢，但准备踢毽的脚呈盘状\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踢毽动作:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"利用脚踝和小腿的旋转力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"用脚外侧或脚底边缘踢毽子\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"技巧要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"控制力道，保持毽子的稳定飞行\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"练习脚踝的灵活性和力量\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"踢毽子\\\",\\\"平踢\\\",\\\"盘踢\\\",\\\"脚内侧\\\",\\\"右脚正踢\\\",\\\"预备\\\",\\\"两脚稍分开\\\",\\\"自然站立\\\",\\\"毽子\\\",\\\"抛起\\\",\\\"与膝同高\\\",\\\"右腿迅速抬起\\\",\\\"屈膝\\\",\\\"小腿向内摆动\\\",\\\"右脚落地\\\",\\\"踢第二次\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":30,\\\"End\\\":4940,\\\"Text\\\":\\\"今天我们为大家介绍踢毽子的两种方法：平踢和盘踢。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.017245777,\\\"Lecture\\\":0.93244404,\\\"Meeting\\\":0.050310146}}\"', '<p><br></p>', '已完成', '2025-05-23 21:42:23', '2025-05-23 21:44:56', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (225, NULL, 65, 'https://lxzj.tenir.cn/lxzj/files/2025/04/4968735219624d6e804a5cd715a64c2b.mp4', '13651247dc8940c4ae16dd11760d2fcf', '视频笔记分析任务161', '\"[{\\\"Id\\\":1,\\\"Start\\\":1310,\\\"End\\\":142300,\\\"Headline\\\":\\\"足球基本动作教学：内侧、外侧与正脚背踢球技巧\\\",\\\"Summary\\\":\\\"介绍了四种足球基本动作的练习方法，包括单脚内侧踢球、双脚内侧交替踢球、脚外侧踢球以及正脚背踢球的技巧与练习方式，并详细描述了每种动作的站姿、腿部动作和脚部控制的关键要点。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本指南详细介绍了四种足球基本踢球动作的练习方法：一脚内侧踢球，要求双脚自然开立，屈膝下蹲，通过抬大腿和甩小腿完成，脚端保持平直；双脚内侧踢球，练习方式类似。脚外侧踢球，重心落在支撑腿上，通过抬大腿、收小腿和勾脚尖完成，脚端同样保持平直；单脚外侧踢球的练习同样重要。正脚背踢球，双脚自然开立并屈膝，大腿带动小腿上抬，踝关节放松，绷紧脚尖并抖动脚踝完成动作；最后是单脚正脚背踢球的练习和大腿触球的技巧展示。每个动作的细节和练习方法在对话中均被强调。\\\",\\\"ParagraphTitle\\\":\\\"足球基础踢球动作练习指南\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"介绍了四种足球基本动作的展示与练习方法。首先是一脚内侧踢球，通过双脚自然开立、屈膝微蹲，抬大腿甩小腿，保持脚端平。其次是脚外侧踢球，同样需要双脚自然开立、屈膝微蹲，但重心需落在支撑腿上，收小腿并勾脚尖。再者是正脚背踢球，需要大腿带动小腿屈膝上抬，踝关节放松，绷紧脚尖，抖动脚踝。最后是大腿触球的技巧，这要求球员用大腿的适当部位接触球。他强调，每种动作都包含了单脚和双脚的练习方式，以帮助球员全面掌握这些基本技巧。通过这些详细的动作描述和练习方法，他旨在帮助足球爱好者们提高他们的足球技能，尤其是对基本动作的掌握和运用。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在足球训练中，如何进行单脚内侧踢球的练习？\\\",\\\"SentenceIdsOfQuestion\\\":[2,3],\\\"Answer\\\":\\\"单脚内侧踢球练习时，需保持双脚自然开立，屈膝微微下蹲，抬大腿，然后以脚端平的方式进行踢球。\\\",\\\"SentenceIdsOfAnswer\\\":[2,3]},{\\\"Question\\\":\\\"双脚内侧踢球练习的正确姿势是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[4],\\\"Answer\\\":\\\"双脚内侧踢球练习要求双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，同时抬大腿、收小腿、勾脚尖并保持脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"单脚外侧踢球练习的要点是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[5],\\\"Answer\\\":\\\"单脚外侧踢球练习需要保持双脚自然开立，屈膝微微下蹲，重心落在支撑腿上，抬大腿，收小腿，勾脚尖，确保脚端平。\\\",\\\"SentenceIdsOfAnswer\\\":[6,7]},{\\\"Question\\\":\\\"正脚背踢球练习时，身体应如何准备？在足球训练中，如何执行单脚正脚背踢球练习？\\\",\\\"SentenceIdsOfQuestion\\\":[8],\\\"Answer\\\":\\\"进行正脚背踢球练习时，需双脚自然开立，屈膝微微下蹲，大腿带动小腿屈膝上抬，踝关节放松并绷脚尖，同时抖动脚踝进行练习。单脚正脚背踢球练习要求保持双脚自然开立，屈膝微微下蹲，通过大腿带动小腿上抬，踝关节放松绷脚尖，并通过抖动脚踝来完成踢球动作。\\\",\\\"SentenceIdsOfAnswer\\\":[9,10,11]},{\\\"Question\\\":\\\"在足球训练中，如何进行大腿触球的练习？\\\",\\\"SentenceIdsOfQuestion\\\":[12],\\\"Answer\\\":\\\"关于大腿触球练习的具体方法没有在给出内容中明确说明，但根据上下文推测，大腿触球练习可能是涉及利用大腿接触并控制球的训练项目。\\\",\\\"SentenceIdsOfAnswer\\\":[12]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"足球基本动作练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"一脚内侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，甩小腿，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚内侧踢球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"双脚内侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"脚外侧踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心落在支撑腿上\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"抬大腿，收小腿，勾脚尖，脚端平\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚外侧踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"正脚背踢球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立，屈膝，微微下蹲\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"大腿带动小腿屈膝上抬\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"踝关节放松，绷脚尖，抖动脚踝\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"单脚正脚背踢球练习\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"大腿触球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"通过大腿接触球进行控制或传球练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"注意身体平衡和球的接触点\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"基本动作\\\",\\\"一脚内侧踢球\\\",\\\"双脚自然分开站立\\\",\\\"屈膝\\\",\\\"微微下蹲\\\",\\\"抬起大腿\\\",\\\"脚面放平\\\",\\\"脚外侧踢球\\\",\\\"重心\\\",\\\"支撑腿\\\",\\\"收回小腿\\\",\\\"勾起脚尖\\\",\\\"正脚背踢球\\\",\\\"大腿带动小腿\\\",\\\"屈膝上抬\\\",\\\"绷紧脚尖\\\",\\\"抖动脚踝\\\",\\\"大腿触球\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.019897494,\\\"Lecture\\\":0.92467904,\\\"Meeting\\\":0.055423494}}\"', '<p>12312312313132</p><p><br></p>', '已完成', '2025-05-23 21:47:52', '2025-06-13 13:37:01', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (226, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', 'e44baf5ffe884f1792e782c9bbb13d20', '视频笔记分析任务141', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提高快速启动与耐力\\\",\\\"Summary\\\":\\\"介绍了通过小碎步热身和间歇训练增强腿部与脚踝力量及耐力的方法，重点强调了下蹲幅度、重心控制的重要性，以及在训练中感受大腿酸胀感的技巧，从而提升启动速度和移动效率。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感觉更轻盈。此训练特别有效，适合提高快速启动和耐力。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿酸胀，随后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速反应和移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键在于下蹲的深度和持续时间，以及在酸胀之后的坚持，这些都会影响到训练效果和腿部力量的提升。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练强度:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"间歇30秒，1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒，体验极限\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀后腿部变得轻盈\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"可作为提高快速启动与耐力的专项训练\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"个性化调整: 根据个人体能调整训练强度和时间\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"安全第一: 确保热身充分，避免运动伤害\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功——快速启动。进行小碎步热身，每组两次，每次间歇30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-05-23 21:52:35', '2025-05-23 22:31:24', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (227, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '8760dd6667bd457bb62949aafe22dd3c', '视频笔记分析任务151', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"介绍了通过小碎步热身和间歇训练增强腿部与脚踝力量及耐力的方法，重点强调了下蹲幅度、重心控制的重要性，以及在训练中感受大腿酸胀感的技巧，从而提高启动速度与移动效率。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒尽管疲劳但会感到腿部异常轻松，此为提高快速启动和耐力的有效专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？如何通过下蹲训练达到腿部酸胀并增强耐力的效果？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次下蹲至屈膝状态以感受腿部酸胀感，这样可以增强腿部和脚踝的力量与耐力，进而提升启动速度和移动速度。在训练时要注意保持重心，并确保下蹲幅度足够。在下蹲训练中，建议开始时连续20秒保持下蹲姿势，感受大腿的酸胀感，之后再坚持硬挺10秒，直到感觉腿部不再受控制，这时腿部会变得非常轻盈。这样的训练方法有助于显著提高腿部耐力和快速启动的能力。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练强度:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"间歇30秒，1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒，体验极限\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀后腿部变得轻盈\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"可作为提高快速启动与耐力的专项训练\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"个性化调整: 根据个人体能调整训练强度和时间\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"安全第一: 确保热身充分，避免运动伤害\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这样的训练可以增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-05-23 21:54:34', '2025-05-23 21:55:27', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (228, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', 'b075911f1ad949c880241a3075fb054d', '视频笔记分析任务161', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提高快速启动与耐力\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过小碎步热身和间歇性屈膝练习，旨在增强腿部及脚踝的力量与耐力，提升启动速度和移动灵活性。训练时建议下蹲幅度要适中，保持重心稳定，初期可能会感到大腿酸胀，随后逐步挑战极限，使腿部更加轻盈有力。此训练特别适合专项提升快速启动能力和持久耐力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒尽管疲劳，但过后腿部会感到异常轻松，此训练特别有效，适用于提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒参与者要保持身体重心稳定，确保下蹲幅度足够，以充分感受大腿肌肉的酸胀。他指出，在训练的初期20秒内，大腿会感到酸胀，随后的10秒需要硬挺过去，直到感觉腿部变得轻松，这标志着训练效果的初步显现。通过这样的训练方法，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速启动和灵活移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键在于下蹲动作的正确性和持续感受酸胀感的时间。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 意识到酸胀感后的轻盈感, 为后续训练做好心理准备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练益处\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"腿部力量提升: 通过屈膝至酸胀的练习, 增强腿部肌肉力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚踝耐力增强: 小碎步与快速启动训练, 提高脚踝稳定性和耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"启动速度与移动速度: 专项训练直接提升毽球运动中的启动与移动效率\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，快速启动。进行小碎步热身，每组两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这样可以增强腿部和脚踝的力量与耐力，有效提升启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-05-23 22:28:24', '2025-05-23 22:29:26', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (229, 48, 102, 'https://lxzj.tenir.cn/lxzj/files/course_center/videos/基础训练篇.mp4', '82cc8f555ab74d359a615a0a536bfaa1', NULL, '\"[{\\\"Id\\\":1,\\\"Start\\\":1310,\\\"End\\\":142300,\\\"Headline\\\":\\\"毽球基本技术训练：脚内侧、外侧与正脚背击球方法\\\",\\\"Summary\\\":\\\"系统讲解毽球四项基本击球技术：1)单脚内侧击球训练；2)双脚内侧交替击球训练；3)脚外侧拨球技术；4)正脚背抽击技术。详细解析每种技术的准备姿势、发力顺序、触球部位及随摆动作，帮助学员建立规范的击球动作模式。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"本指南系统讲解毽球四项基本击球技术：脚内侧击球、脚外侧拨球、正脚背抽击及大腿缓冲。所有技术动作均以双脚自然开立、膝关节微屈的基本姿势为基础，详细解析抬腿发力、小腿摆动、脚部控制等关键技术环节，全面提升毽球击球技能。\\\",\\\"ParagraphTitle\\\":\\\"毽球基础击球技术训练指南\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"专项教练\\\",\\\"Summary\\\":\\\"系统讲解毽球四项核心技术：1)脚内侧击球强调抬大腿甩小腿的发力顺序；2)脚外侧拨球注重重心控制和脚尖动作；3)正脚背抽击要求踝关节放松与脚尖绷直；4)大腿缓冲技术训练。每种技术都包含单脚和双脚的专项训练方法，通过分解动作演示帮助学员建立规范的技术动作模式。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"脚内侧击球的技术要点是什么？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2],\\\"Answer\\\":\\\"脚内侧击球需注意：1)准备姿势双脚自然开立；2)膝关节适度弯曲；3)抬大腿带动小腿摆动；4)击球瞬间脚内侧端平；5)完成动作后自然随摆。建议先进行单脚练习，熟练后再过渡到双脚交替训练。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2]},{\\\"Question\\\":\\\"正脚背抽击需要注意哪些技术细节？\\\",\\\"SentenceIdsOfQuestion\\\":[3,4],\\\"Answer\\\":\\\"正脚背抽击关键技术：1)支撑脚位置要稳；2)大腿带动小腿发力；3)击球时踝关节放松；4)脚尖绷直确保击球部位准确；5)配合脚踝抖动增加爆发力。建议先进行原地无球练习，再过渡到有球训练。\\\",\\\"SentenceIdsOfAnswer\\\":[3,4]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球击球技术体系\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"基本姿势\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"双脚自然开立\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"膝关节微屈\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"重心控制\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"核心技术\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"脚内侧击球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"抬大腿发力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小腿摆动控制\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚内侧端平\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"脚外侧拨球\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心转移\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚尖控制\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练方法\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"分解练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"完整练习\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"组合练习\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"基本技术\\\",\\\"脚内侧击球\\\",\\\"准备姿势\\\",\\\"膝关节弯曲\\\",\\\"重心下沉\\\",\\\"大腿发力\\\",\\\"脚面控制\\\",\\\"脚外侧拨球\\\",\\\"重心转移\\\",\\\"支撑腿稳定\\\",\\\"小腿回收\\\",\\\"脚尖动作\\\",\\\"正脚背抽击\\\",\\\"下肢协调发力\\\",\\\"踝关节控制\\\",\\\"脚部灵活性\\\",\\\"大腿缓冲\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.019897494,\\\"Lecture\\\":0.92467904,\\\"Meeting\\\":0.055423494}}\"', NULL, '已完成', '2025-05-23 22:30:35', NULL, 1, NULL, 0);
INSERT INTO `ai_note_info` VALUES (230, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '18fc15044c5d421eb6cabc37de0d6d40', '视频笔记分析任务171', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过小碎步热身和间歇性屈膝练习，旨在增强腿部及脚踝的力量与耐力，提高启动速度和移动效率。训练时建议下蹲幅度要适中，保持重心稳定，初期可能会感到大腿酸胀，随后逐步挑战极限，使腿部逐渐变得轻盈灵活。适合专项提升快速启动能力和持久耐力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感到异常轻松。此训练特别有效，适合提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键在于下蹲动作的正确性和持续感受酸胀感的时间。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 感受并克服腿部酸胀感, 达到训练极限后的轻松感\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练收益\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强腿部与脚踝力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升耐力与启动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"改善移动速度与灵活性\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，同时提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', NULL, '已完成', '2025-05-23 22:41:35', NULL, 1, NULL, 1);
INSERT INTO `ai_note_info` VALUES (231, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '88d3c98f2d44430a89e43e9c3b44812c', '视频笔记分析任务181', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过小碎步热身和间歇性屈膝练习，旨在增强腿部及脚踝的力量与耐力，提高启动速度和移动速度。训练时建议下蹲幅度要足够，保持重心稳定，初期可能会感到大腿酸胀，随后逐步挑战极限，让腿部逐渐变得轻盈。该训练适合专项提升快速启动能力与耐力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感到异常轻松。此训练特别有效，适用于提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿酸胀，随后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速反应和移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？如何通过下蹲训练达到腿部酸胀并增强耐力的效果？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次下蹲至屈膝状态以感受腿部酸胀感，这样可以增强腿部和脚踝的力量与耐力，进而提升启动速度和移动速度。在训练时要注意保持重心，并确保下蹲幅度足够。在下蹲训练中，建议每次坚持20秒感受大腿的酸胀感，接着保持硬挺10秒，直到感觉腿部不再受控制，此时腿部会逐渐变轻。这种训练方法可以有效锻炼腿部肌肉，提高耐力，为提升整体运动表现打下基础。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 意识到酸胀感后的轻盈感, 是训练成果的体现\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练益处\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强腿部力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升脚踝稳定性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"加快启动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高移动速度与灵活性\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，快速启动。进行小碎步热身，每组两次，每次间歇30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-05-23 22:42:36', '2025-05-23 22:43:10', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (232, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '573c186c37d24f1d95ddd2b0bb4a71e2', '视频笔记分析任务191', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"介绍了通过小碎步热身和间歇训练增强腿部与脚踝力量及耐力的方法，重点强调了下蹲幅度、重心控制的重要性，以及在训练中感受大腿酸胀感的技巧，从而有效提高启动速度和移动能力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部感到酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒即使感觉腿已非己有，完成后腿部将感到异常轻松。此训练特别有效，可作为提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？如何通过下蹲训练达到腿部酸胀并增强耐力的效果？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次下蹲至屈膝状态以感受腿部酸胀感，这样可以增强腿部和脚踝的力量与耐力，进而提升启动速度和移动速度。在训练时要注意保持重心，并确保下蹲幅度足够。在下蹲训练中，建议每次坚持20秒感受大腿的酸胀感，接着保持硬挺10秒，直到感觉腿部不再受控制，此时腿部会逐渐变轻。这种训练方法可以有效锻炼腿部肌肉，提高耐力，为提升整体运动表现打下基础。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 意识到酸胀感后的轻盈感, 为后续训练做好心理准备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练益处\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"腿部力量提升: 通过屈膝至酸胀的练习, 增强腿部肌肉力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚踝耐力增强: 小碎步与快速启动训练, 提高脚踝稳定性和耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"启动速度与移动速度: 专项训练直接提升毽球运动中的启动与移动效率\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，快速启动。进行小碎步热身，每组两次，每次间歇30秒，屈膝至腿部感到酸胀即可。这样可以增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-05-23 22:42:49', '2025-07-04 20:57:25', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (233, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '50cda82b7b2447c6a975200ad19f5074', '视频笔记分析任务201', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提高快速启动与耐力\\\",\\\"Summary\\\":\\\"介绍了通过小碎步热身和间歇训练增强腿部与脚踝力量及耐力的方法，重点强调了下蹲幅度、重心控制的重要性，以及训练中感受大腿酸胀感的技巧，从而提升启动速度和移动效率。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒尽管疲劳但过后腿部会感到异常轻松。此训练特别有效，适合提高快速启动和耐力。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次感受屈膝带来的腿部酸胀感直至大腿肌肉有足够力量和耐力，这有助于提升启动速度和移动速度。此方法需保持正确的重心和下蹲幅度，通过短暂的酸胀后硬挺10秒，以增强腿部肌肉的反应速度和轻盈感。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练强度:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"间歇30秒，1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"前20秒: 感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"后10秒: 尽管酸胀，继续坚持\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀后腿部感觉变轻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"有效提升快速启动与耐力\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"保持正确的姿势和动作幅度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"注意休息，避免过度训练导致伤害\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"结合个人体能调整训练强度和时间\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功中的快速启动技巧。通过小碎步进行热身，每组持续30秒，做两组，期间间歇30秒。屈膝时感受到腿部酸胀即可，这有助于增强腿部和脚踝的力量与耐力，同时提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">该视频介绍了毽球基本功训练，重点在于通过小碎步热身和间歇性练习（30秒1组，共2组）增强腿部与脚踝力量及耐力。训练需保持正确重心和下蹲幅度，前20秒感受大腿酸胀，后10秒坚持到腿部轻松，从而提升快速启动和移动速度，提高比赛表现。</span></p>', '已完成', '2025-05-23 22:44:52', '2025-05-23 23:09:52', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (234, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '2b4789906a044e5697bf8be016db1459', '视频笔记分析任务211', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过小碎步热身和间歇性屈膝练习，旨在增强腿部及脚踝的力量与耐力，提高启动速度和移动效率。训练建议下蹲幅度要适中，保持重心稳定，每组持续30秒，分两次进行，直至大腿感到酸胀。特别强调在酸胀感出现后坚持10秒，以达到更好的训练效果，让腿部感觉更加轻盈。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部感到酸胀，以增强腿部和脚踝的力量与耐力，提升启动和移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注感受大腿酸胀，最后10秒即使感到腿部无力也要坚持，之后腿部会感到异常轻松。此训练有效提高快速启动和耐力，可作为专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒参与者要保持身体重心稳定，确保下蹲幅度足够，以充分感受大腿肌肉的酸胀。他指出，在训练的初期20秒内，大腿会感到酸胀，随后的10秒需要硬挺过去，直到感觉腿部变得轻松，这标志着训练效果的初步显现。通过这样的训练方法，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速启动和灵活移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？快速启动训练中的具体动作和训练强度是怎样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在快速启动训练中，首先进行20秒的小碎步热身，感受大腿的酸胀感后，再保持硬挺10秒，此时会感觉腿部非常轻盈。这个训练要求在有足够下蹲幅度的基础上进行，通过短暂的酸胀期后，腿部力量和耐力能得到显著提升。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 感受并克服腿部酸胀感, 达到训练极限后的轻松感\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练收益\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强腿部与脚踝力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升耐力与启动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"改善移动速度与灵活性\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这样可以增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-05-23 23:09:14', '2025-05-23 23:10:01', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (235, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '04ae212383e14c71aa3eebf9663c8701', '视频笔记分析任务221', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"本次训练聚焦于毽球基本功，通过小碎步热身和间歇性屈膝练习，旨在增强腿部及脚踝的力量与耐力，提高启动速度和移动效率。建议下蹲幅度要足够，保持重心稳定，初期感受大腿酸胀时坚持20秒，再努力支撑10秒，以达到腿部逐渐适应、提升耐力的效果。此项训练特别适合用于专项提升快速启动能力与持久耐力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒尽管疲劳但坚持，之后腿部会感到异常轻松。此训练特别有效，适合提高快速启动和耐力。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒参与者要保持身体重心稳定，确保下蹲幅度足够，以充分感受大腿肌肉的酸胀。他指出，在训练的初期20秒内，大腿会感到酸胀，随后的10秒需要硬挺过去，直到感觉腿部变得轻松，这标志着训练效果的初步显现。通过这样的训练方法，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速启动和灵活移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次感受屈膝带来的腿部酸胀感直至大腿肌肉有足够力量和耐力，这有助于提升启动速度和移动速度。此方法需保持正确的重心和下蹲幅度，通过短暂的酸胀后硬挺10秒，以增强腿部肌肉的反应速度和轻盈感。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇训练: 30秒1组, 两次屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提高启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"适用性: 可作为提高快速启动和耐力的专项训练\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 下蹲时确保幅度足够\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感管理:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀感\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部变得轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受: 训练过程中, 到达一定程度后, 会感觉腿部似乎不再属于自己, 但之后腿部会变得异常轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练效益\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强腿部力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升脚踝稳定性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"改善启动与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高耐力水平\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功——快速启动。通过小碎步进行热身，每组两次，每次间歇30秒，屈膝至腿部感到酸胀即可。这种训练可以增强腿部和脚踝的力量与耐力，同时提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">该视频讲解了毽球基本功训练，重点提升快速启动与耐力。通过小碎步热身和30秒间歇性屈膝练习，增强腿部及脚踝力量，改善移动速度与稳定性。训练时需保持下蹲幅度和重心，感受大腿酸胀并坚持10秒，达到轻松感。此方法适合专项提升启动速度与持久耐力，为比赛中的灵活移动奠定基础。</span></p>', '已完成', '2025-05-24 09:20:24', '2025-05-24 10:32:45', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (236, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '355fef5be2254b5395125596b63a8cfa', '视频笔记分析任务231', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提高快速启动与耐力\\\",\\\"Summary\\\":\\\"介绍了通过小碎步热身和间歇训练增强腿部与脚踝力量及耐力的方法，从而提升毽球运动中的启动速度和移动能力。强调训练时需关注重心控制和下蹲幅度，通过感受大腿的酸胀感确保训练效果。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感到异常轻松。此训练特别有效，适用于提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键是要保持正确的重心和下蹲幅度。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]},{\\\"Question\\\":\\\"如何通过特定的训练来提高腿部耐力和快速启动能力？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"可以通过间歇性训练，例如连续快速启动30秒，之后进行短暂停歇，重复进行这样的循环训练。每次下蹲后硬挺大腿10秒，以感受并克服腿部的酸胀感。这种训练不仅能锻炼腿部力量和耐力，还能有效提升启动速度和移动速度。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练强度:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"间歇30秒，1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒，体验极限\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀感后腿部变得轻盈\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"可作为提高快速启动和耐力的专项训练\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重视重心与下蹲幅度，确保训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"监听身体反应，避免过度训练\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功——快速启动。通过小碎步热身，每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这种练习可以增强腿部和脚踝的力量与耐力，同时提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">该视频介绍了毽球基本功训练，重点在于通过小碎步热身和间歇训练提升快速启动能力与耐力。训练方法包括30秒一组、两次屈膝练习，注意重心控制和下蹲幅度，感受大腿酸胀感以确保效果。此专项训练能增强腿部力量与脚踝耐力，提高移动速度，适合用于比赛中快速启动的技能提升。</span></p>', '已完成', '2025-05-24 10:31:44', '2025-05-24 13:49:21', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (237, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '9927986cbf50482eb20998e727d8562a', '视频笔记分析任务241', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"介绍了通过小碎步热身和间歇训练增强腿部与脚踝力量及耐力的方法，从而提高毽球运动中的启动速度和移动效率。强调训练时需关注重心控制和下蹲幅度，通过感受大腿的酸胀感确保训练效果。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部感到酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒即使感觉艰难也要坚持，之后腿部会感到异常轻松。此训练特别有效，适合提高快速启动和耐力。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿酸胀，随后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速反应和移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键在于下蹲动作的正确性和持续感受酸胀感以锻炼腿部肌肉。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 意识到酸胀感后的轻盈感, 是训练成果的体现\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练益处\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强腿部力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升脚踝稳定性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"加快启动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高移动速度与灵活性\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组练习两次，每次间歇30秒，屈膝至腿部感到酸胀即可。这种训练可以增强腿部和脚踝的力量与耐力，同时提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">该视频介绍了毽球基本功训练，重点在于通过小碎步热身和间歇训练提升快速启动能力与耐力。训练方法包括30秒一组、两次屈膝练习，注意重心控制和下蹲幅度，感受大腿酸胀感以确保效果。此专项训练能增强腿部力量与脚踝耐力，提高移动速度，适合用于比赛中快速启动的技能提升。</span></p>', '已完成', '2025-05-24 13:48:38', '2025-05-24 14:03:35', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (238, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '2dd6c9a6f702461685df1786ac2fe76e', '视频笔记分析任务251', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"介绍了通过小碎步热身和间歇训练增强腿部与脚踝力量及耐力的方法，从而提高毽球运动中的启动速度和移动效率。强调了训练过程中需关注重心控制和下蹲幅度，并通过感受大腿酸胀感确保训练效果。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒尽管疲劳，但过后腿部会感到异常轻松，此训练特别有效，适用于提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒参与者要保持身体重心稳定，确保下蹲幅度足够，以充分感受大腿肌肉的酸胀。他指出，在训练的初期20秒内，大腿会感到酸胀，随后的10秒需要硬挺过去，直到感觉腿部变得轻松，这标志着训练效果的初步显现。通过这样的训练方法，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速启动和灵活移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次感受屈膝带来的腿部酸胀感直至大腿肌肉有足够力量和耐力，这有助于提升启动速度和移动速度。此方法需保持正确的重心和下蹲幅度，通过短暂的酸胀后硬挺10秒，以增强腿部肌肉的反应速度和轻盈感。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练强度:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"间歇30秒，1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒，体验极限\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀感后腿部变得轻盈\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"可作为提高快速启动和耐力的专项训练\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重视重心与下蹲幅度，确保训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"监听身体反应，避免过度训练\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功——快速启动。进行小碎步热身，每组两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-05-24 14:03:06', '2025-05-24 14:03:54', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (239, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '4a7b049b9887467691332daa0b9f4d40', '视频笔记分析任务263', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：提升快速启动与耐力\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过小碎步热身和间歇训练，旨在增强腿部与脚踝的力量和耐力，提高启动速度及移动速度。特别强调了训练中重心的保持和下蹲幅度的控制，通过20秒酸胀感训练后坚持10秒，以达到腿部轻盈的效果。此训练适合专项提升快速启动能力与耐力。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部感到酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒即使感觉艰难也要坚持，之后腿部会感到异常轻松。此训练特别有效，适合提高快速启动和耐力。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键在于下蹲的深度和持续时间，以及在酸胀之后的坚持，这些都会影响到训练效果和腿部力量的提升。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练强度:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"间歇30秒，1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒，体验极限\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀感后腿部变得轻盈\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"可作为提高快速启动和耐力的专项训练\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重视重心与下蹲幅度，确保训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"监听身体反应，避免过度训练导致伤害\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，快速启动。进行小碎步热身，每组两次，每次间歇30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p>微风拂过你的身旁，带着你身上淡淡的清香。风感激世界万物都在运动，让它能够自由地去往任何想去的地方，虚无缥缈。它来时携着芬芳，正如我初次遇见你一般。</p>', '已完成', '2025-05-24 15:07:25', '2025-06-26 14:50:25', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (240, NULL, 29, 'https://lxzj.tenir.cn/lxzj/files/2025/03/b0ef9307c9a44cbf810acf6ec3a9a28b.mp4', '3e5a6c180e67466fa53e8e43f5c0105f', '视频笔记分析任务271', '\"[{\\\"Id\\\":1,\\\"Start\\\":1440,\\\"End\\\":6430,\\\"Headline\\\":\\\"2025年武术训练指南：后脚跟离地与重心前移技巧解析\\\",\\\"Summary\\\":\\\"在2025年6月13日的武术训练中，重点讲解了后脚跟离地和重心稍向前移动的技巧，指出这是保持随时处于静中状态的关键所在。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"在指导特定身体平衡和姿势的活动中，有两个关键点被反复强调：首先，确保后脚跟不触地，这有助于维持身体的稳定性和正确的姿势；其次，身体的重心应略微前移，并且要始终保持在静中状态，这种状态下，可以更好地控制身体，确保动作的准确性和流畅性。这两个要点对于掌握需要精细平衡的活动或运动至关重要。\\\",\\\"ParagraphTitle\\\":\\\"掌握特定身体平衡技巧的要点\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调，在行动或站立时，正确的身体姿态至关重要。他指出，应当注意后脚跟离地，这意味着在移动或保持站立姿势时，身体的后脚跟不应紧紧贴着地面，而是要轻轻抬起，这样可以将身体的重心略微向前移动。这一动作有助于提高身体的灵活性和反应速度。同时，他强调，尽管在行动中需要调整重心，但始终保持静中，即保持身体的稳定和平衡状态，是非常重要的。这意味着在任何动作中，都要注意维持身体的稳定，避免因重心不稳而导致的摔倒或受伤。总的来说，他的核心观点是在行动或站立时，通过调整后脚跟的位置和重心，同时保持身体的稳定和平衡，以实现更加安全和有效的身体控制。\\\"}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"训练技巧总结\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"动作要点\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"后脚跟离地\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"确保后脚跟不接触地面\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"维持身体的动态平衡\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"重心稍前移\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"调整身体重心至前脚掌\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"保持身体稳定和灵活\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"随时保持静中\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"在运动中维持静态的稳定性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"准备随时做出反应或动作转换\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"实践建议\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"反复练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"通过多次重复，增强肌肉记忆\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"镜前练习\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"利用镜子检查动作的正确性\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专业指导\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"寻求教练或专业人员的指导\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"渐进式训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"从简单动作开始，逐步增加难度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"身体核心力量训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"加强腹部和背部肌肉，提高整体稳定性\\\",\\\"Topic\\\":[]}]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"重心\\\",\\\"脚跟\\\"],\\\"Classifications\\\":{\\\"Interview\\\":0.019018164,\\\"Lecture\\\":0.95455813,\\\"Meeting\\\":0.026423674}}\"', '<p><br></p>', '已完成', '2025-06-13 19:33:13', '2025-06-13 19:44:34', 1, 1, 1);
