INSERT INTO `ai_note_info` VALUES (242, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4 ', 'f8aba481bdba4b4c891b48b53d170330', '视频笔记分析任务291', NULL, NULL, NULL, '<p><br></p>', '失败', '2025-07-04 19:51:32', '2025-07-04 19:51:42', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (243, NULL, 106, 'https://lxzj.tenir.cn/lxzj/files/2025/07/273bec68d8f24ce795a0ddcaa458bc87.mp4', '7087c103384d4c17b60bf4200cfd7f5d', '视频笔记分析任务301', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：增强腿部与脚踝力量\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过快速启动和小碎步热身，结合30秒一组、两次屈膝的练习，旨在增强腿部和脚踝的力量与耐力，提升启动速度和移动速度。特别强调下蹲幅度要足够，先用20秒感受大腿酸胀，再坚持10秒，最终使腿部感觉更加轻盈。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感到异常轻松。此训练特别有效，适用于提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键是要保持正确的重心和下蹲幅度。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]},{\\\"Question\\\":\\\"如何通过特定的训练来提高腿部耐力和快速启动能力？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"可以通过间歇性训练，例如连续快速启动30秒，之后进行短暂停歇，重复进行这样的循环训练。每次下蹲后硬挺大腿10秒，以感受并克服腿部的酸胀感。这种训练不仅能锻炼腿部力量和耐力，还能有效提升启动速度和移动速度。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感受到腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 下蹲时幅度要足够, 以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内, 集中感受大腿的酸胀感\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后, 再坚持硬挺10秒, 直至感觉腿部似乎不再属于自己\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"完成后, 腿部会有轻松感, 表明训练有效\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练益处\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"增强腿部力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提升脚踝稳定性\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"加快启动与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"提高耐力与灵活性\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，快速启动。进行小碎步热身，每组两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-07-04 19:52:28', '2025-07-04 19:52:56', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (244, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4 ', '2e93ae99fb6c4ee6ab0edc38e50205ad', '视频笔记分析任务311', NULL, NULL, NULL, '<p><br></p>', '失败', '2025-07-04 19:53:29', '2025-07-04 19:53:49', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (245, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', 'a40c33d6cc064b849076b55a9881d2c7', '视频笔记分析任务321', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：增强腿部与脚踝力量\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过快速启动和小碎步热身，结合30秒一组、两次屈膝的练习，旨在增强腿部和脚踝的力量与耐力，提升启动速度和移动速度。特别强调下蹲幅度要足够，先用20秒感受大腿酸胀，再坚持10秒，以此提高快速启动能力和耐力水平。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感到异常轻松。此训练为提高快速启动和耐力的专项训练，效果显著。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键在于下蹲动作的正确性和持续感受酸胀感的时间。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练强度:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"间歇30秒，1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以充分锻炼腿部肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒，体验极限\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练感受:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀感后腿部变得轻盈\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"可作为提高快速启动和耐力的专项训练\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重视重心与下蹲幅度，确保训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"监听身体反应，避免过度训练\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', NULL, '已完成', '2025-07-04 20:22:47', NULL, 1, NULL, 1);
INSERT INTO `ai_note_info` VALUES (246, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '9de550ad189d4709899f96d563eb8c7e', '视频笔记分析任务331', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：增强腿部与脚踝力量\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球的基本功训练，通过快速启动和小碎步热身，结合30秒一组、重复两次的屈膝练习，旨在增强腿部和脚踝的力量与耐力，提升启动速度和移动速度。特别强调了训练时的重心控制和下蹲幅度，以及通过感受大腿酸胀感来提升耐力，训练后腿部会感到更加轻松。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感到异常轻松。此训练特别有效，适用于提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？如何通过下蹲训练达到腿部酸胀并增强耐力的效果？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次下蹲至屈膝状态以感受腿部酸胀感，这样可以增强腿部和脚踝的力量与耐力，进而提升启动速度和移动速度。在训练时要注意保持重心，并确保下蹲幅度足够。在下蹲训练中，建议每次坚持20秒感受大腿的酸胀感，接着保持硬挺10秒，直到感觉腿部不再受控制，此时腿部会变得轻盈。这种训练方法可以有效锻炼腿部肌肉，提高耐力，为提升整体运动表现打下基础。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 意识到酸胀感后的轻盈感, 为后续训练做好心理准备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练益处\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"腿部力量提升: 通过屈膝至酸胀的练习, 增强腿部肌肉力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚踝耐力增强: 小碎步与快速启动训练, 提升脚踝稳定性和耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"启动速度与移动速度提高: 专项训练直接提升运动员的启动与移动速度\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功——快速启动。进行小碎步热身，每组两次，每次间歇30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-07-04 20:23:46', '2025-07-04 20:24:37', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (247, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '325a4d2c0e29416db863693d6569f68d', '视频笔记分析任务151', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：增强腿部力量与耐力\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过快速启动和小碎步热身，结合30秒一组、两次屈膝的练习，旨在增强腿部和脚踝的力量与耐力，提升启动速度和移动速度。特别强调下蹲幅度要足够，先用20秒感受大腿酸胀，再坚持10秒，最终让腿部感觉更加轻盈。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部感到酸胀，以增强腿部和脚踝的力量与耐力，提升启动和移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注大腿酸胀感，最后10秒克服极度疲劳，完成后腿部会感觉更轻盈。此训练特别有效，可作为提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"他强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键是要保持正确的重心和下蹲幅度。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]},{\\\"Question\\\":\\\"如何通过特定的训练来提高腿部耐力和快速启动能力？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"可以通过间歇性训练，例如连续快速启动30秒后休息10秒，反复进行两组，每组之间间隔30秒，直到腿部有明显酸胀感。这种训练有助于增强腿部肌肉力量和耐力，从而提高快速启动的速度。同样地，下蹲时也要注意保持正确的姿势和深度，确保训练的有效性。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝力量与耐力, 提升启动速度与移动速度\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇30秒, 1组两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感觉腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 专项提高快速启动与耐力\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 足够的下蹲幅度以达到训练效果\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感训练:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"开始20秒内感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒, 直至感觉腿部轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"心理准备: 意识到酸胀感后的轻盈感, 为后续训练做好心理准备\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练益处\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"腿部力量提升: 通过屈膝至酸胀的练习, 增强腿部肌肉力量\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚踝耐力增强: 小碎步与快速启动训练, 提高脚踝稳定性和耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"启动速度与移动速度: 专项训练直接提升毽球比赛中的启动与移动速度\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p>本次课程重点围绕毽球基本功训练，旨在提升快速启动和移动速度。通过小碎步热身以及30秒一组的两次屈膝练习，增强腿部和脚踝的力量与耐力。训练过程中要保持重心稳定，下蹲幅度足够，先感受大腿酸胀20秒，再坚持10秒直至腿部感到轻盈。这一专项训练能有效提高启动速度和耐力，为比赛表现奠定基础。</p>', '已完成', '2025-07-04 20:35:36', '2025-07-04 21:09:22', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (248, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', '28f58a925c504148a5fec6e80b49db2c', '视频笔记分析任务161', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：增强腿部力量与耐力\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过快速启动和小碎步热身，结合30秒为一组、重复两次的屈膝练习，旨在增强腿部和脚踝的力量与耐力，提升启动速度和移动速度。特别强调下蹲幅度要足够，先用20秒感受大腿酸胀，再坚持10秒，最终让腿部感觉更加轻盈。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"对话聚焦于毽球基本功训练，强调了快速启动技巧和小碎步热身的重要性。推荐进行两次30秒的屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升启动速度。训练关键在于保持重心稳定，确保下蹲幅度，前20秒感受大腿酸胀，最后10秒直至腿部感觉轻盈。此专项训练有效提高快速启动与耐力。\\\",\\\"ParagraphTitle\\\":\\\"毽球快速启动技巧与小碎步热身训练方法\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？如何通过下蹲训练达到腿部酸胀并增强耐力的效果？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次下蹲至屈膝状态以感受腿部酸胀感，这样可以增强腿部和脚踝的力量与耐力，进而提升启动速度和移动速度。在训练时要注意保持重心，并确保下蹲幅度足够。在下蹲训练中，建议每次坚持20秒感受大腿的酸胀感，接着保持硬挺10秒，直到感觉腿部不再受控制，此时腿部会逐渐变轻。这种训练方法可以有效锻炼腿部肌肉，提高耐力，为提升整体运动表现打下基础。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇训练: 30秒1组, 重复两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感到腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 下蹲时幅度要足够\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"感受变化:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀后腿部感觉变轻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"有效提升快速启动与耐力\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"安全第一: 确保训练环境安全, 避免受伤\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"适度原则: 根据个人体能调整训练强度, 避免过度劳累\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"持续性: 定期进行此类训练, 以持续提升身体素质\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-07-04 21:08:36', '2025-07-28 14:50:04', 1, 1, 0);
INSERT INTO `ai_note_info` VALUES (249, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', 'a1d2856627344a1bb1206e4a1bdde912', '视频笔记分析任务111', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：增强腿部与脚踝力量\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过小碎步热身和间歇性屈膝练习，旨在增强腿部和脚踝的力量与耐力，提升快速启动和移动速度。训练建议下蹲幅度要足够，保持重心稳定，初期可能会感到大腿酸胀，坚持20秒后硬挺10秒，使腿部逐渐适应并感到轻松。此训练特别有效，可作为提高快速启动和耐力的专项练习。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，最后10秒虽感极度疲劳，但完成后腿部会感到异常轻松。此训练为提高快速启动和耐力的专项有效方法。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒参与者要保持身体重心稳定，确保下蹲幅度足够，以充分感受大腿肌肉的酸胀。他指出，在训练的初期20秒内，大腿会感到酸胀，随后的10秒需要硬挺过去，直到感觉腿部变得轻松，这标志着肌肉开始适应并增强。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，为比赛中的快速反应和移动打下坚实基础。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？如何通过下蹲训练达到腿部酸胀并增强耐力的效果？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，或者进行间歇性练习，例如30秒1组，共做两次，每次下蹲至屈膝状态以感受腿部酸胀感，这样可以增强腿部和脚踝的力量与耐力，进而提升启动速度和移动速度。在训练时要注意保持重心，并确保下蹲幅度足够。在下蹲训练中，建议每次坚持20秒感受大腿的酸胀感，接着保持硬挺10秒，直到感觉腿部不再受控制，此时腿部会逐渐变轻。这种训练方法可以有效锻炼腿部肌肉，提高耐力，为提升整体运动表现打下基础。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇训练: 30秒1组，重复两次\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提高启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练技巧与注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 下蹲时确保幅度足够，以充分锻炼大腿肌肉\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀感管理:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒，直至感觉腿部变得轻盈\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练: 可作为提高快速启动与耐力的专项训练\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"训练效果\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"腿部力量提升\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"脚踝稳定性增强\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"启动速度与移动速度显著提高\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，包括快速启动和小碎步热身。每组进行两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p>本课程专注于毽球基本功的训练，通过小碎步热身和间歇性屈膝练习（每组30秒，共两次），增强腿部和脚踝的力量与耐力，提升快速启动和移动速度。训练时要保持重心稳定，下蹲幅度足够，初期出现大腿酸胀属正常现象，坚持20秒后硬挺10秒，直至适应。这项专项训练能有效增强腿部力量，为比赛中的快速反应和移动打下坚实基础。</p>', '已完成', '2025-07-04 21:34:46', '2025-07-28 14:34:15', 1, 1, 1);
INSERT INTO `ai_note_info` VALUES (250, NULL, NULL, 'https://service-back.oss-cn-beijing.aliyuncs.com/test_vide01.mp4', 'bde31656c52b4dd0b446a7d70f5c697b', '视频笔记分析任务181', '\"[{\\\"Id\\\":1,\\\"Start\\\":1910,\\\"End\\\":34320,\\\"Headline\\\":\\\"毽球基本功训练：增强腿部与脚踝力量\\\",\\\"Summary\\\":\\\"本次学习聚焦于毽球基本功训练，通过快速启动和小碎步热身，结合30秒一组、两次屈膝的练习，旨在增强腿部和脚踝的力量与耐力，提升启动速度和移动速度。特别强调下蹲幅度要足够，先用20秒感受大腿酸胀，再坚持10秒，最终让腿部感觉更加轻盈。\\\"}]\"', '\"{\\\"ParagraphSummary\\\":\\\"讨论强调了毽球训练中快速启动和小碎步热身的重要性，推荐进行30秒一组的两次屈膝练习，直至腿部酸胀，以增强腿部和脚踝力量与耐力，提升移动速度。训练时需保持重心，确保下蹲幅度，前20秒专注于大腿酸胀感，后10秒克服腿部疲劳，完成后腿部将感到异常轻松。此训练特别有效，适用于提高快速启动和耐力的专项训练。\\\",\\\"ParagraphTitle\\\":\\\"毽球基本功训练：增强快速启动与耐力\\\",\\\"ConversationalSummary\\\":[{\\\"SpeakerId\\\":\\\"1\\\",\\\"SpeakerName\\\":\\\"发言人1\\\",\\\"Summary\\\":\\\"强调了毽球基本功训练中快速启动和小碎步热身的重要性，提出了针对性的训练方法以增强腿部和脚踝的力量与耐力，进而提升启动和移动速度。他建议进行30秒一组的两次屈膝练习，这种训练特别有效，专注于提高快速启动和耐力。在进行训练时，他提醒要注意保持身体重心，确保下蹲幅度足够，初期20秒内应感受到大腿的酸胀，然后硬挺10秒，直到感觉腿部变得轻松。通过这样的训练，可以有效提升毽球运动员的腿部力量和耐力，从而在比赛中获得更好的表现。\\\"}],\\\"QuestionsAnsweringSummary\\\":[{\\\"Question\\\":\\\"在学习毽球时，如何进行快速启动的专项训练？在进行快速启动训练时，正确的动作和感受是什么样的？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"为了提高快速启动能力，可以采用小碎步热身，连续做30秒一组，共两次，直到腿部有酸胀感。这样能有效增强腿部脚踝的力量和耐力，进而提升启动速度和移动速度。练习时要注意保持重心，下蹲幅度要足够，以确保训练效果。在进行快速启动训练时，首先需下蹲并感受大腿的酸胀感，然后保持这个姿势硬挺10秒，直到感觉大腿不再受控制，接着会感到腿部变轻。这个过程中，关键是要保持正确的重心和下蹲幅度。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]},{\\\"Question\\\":\\\"如何通过特定的训练来提高腿部耐力和快速启动能力？\\\",\\\"SentenceIdsOfQuestion\\\":[1,2,3],\\\"Answer\\\":\\\"可以通过间歇性训练，例如连续快速启动30秒，之后进行短暂停歇，重复进行这样的循环训练。每次下蹲后硬挺大腿10秒，以感受并克服腿部的酸胀感。这种训练不仅能锻炼腿部力量和耐力，还能有效提升启动速度和移动速度。\\\",\\\"SentenceIdsOfAnswer\\\":[1,2,3]}],\\\"MindMapSummary\\\":[{\\\"Title\\\":\\\"毽球基本功训练\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"快速启动与小碎步热身\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"训练目的: 增加腿部及脚踝的力量与耐力\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"训练方法:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"小碎步热身\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"间歇训练: 30秒1组, 重复两次\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"屈膝至感到腿部酸胀\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"效果: 提升启动速度与移动速度\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"专项训练技巧\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"重心控制: 确保训练中有稳定的重心\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"下蹲幅度: 下蹲时幅度要足够\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"时间分配:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"初始20秒感受大腿酸胀\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"酸胀后硬挺10秒\\\",\\\"Topic\\\":[]}]},{\\\"Title\\\":\\\"感受变化:\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"酸胀后腿部感觉变轻\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"有效提升快速启动与耐力\\\",\\\"Topic\\\":[]}]}]},{\\\"Title\\\":\\\"训练注意事项\\\",\\\"Topic\\\":[{\\\"Title\\\":\\\"安全第一: 确保训练环境安全, 避免受伤\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"适度原则: 根据个人体能调整训练强度, 避免过度劳累\\\",\\\"Topic\\\":[]},{\\\"Title\\\":\\\"持续性: 定期进行此类训练, 以持续提升身体素质\\\",\\\"Topic\\\":[]}]}]}]}\"', '\"{\\\"Keywords\\\":[\\\"毽球基本功\\\",\\\"快速启动\\\",\\\"小碎步热身\\\",\\\"间歇30秒\\\",\\\"1组两次\\\",\\\"屈膝\\\",\\\"腿部酸胀\\\",\\\"耐力\\\",\\\"提高启动速度\\\",\\\"移动速度\\\",\\\"重心\\\",\\\"下蹲幅度\\\",\\\"20秒\\\",\\\"硬挺10秒\\\",\\\"专项训练\\\"],\\\"KeySentences\\\":[{\\\"Id\\\":1,\\\"SentenceId\\\":1,\\\"Start\\\":1910,\\\"End\\\":16591,\\\"Text\\\":\\\"今天我们一起来学习毽球基本功，快速启动。进行小碎步热身，每组两次，每次间隔30秒，屈膝至腿部感到酸胀即可。这有助于增强腿部和脚踝的力量与耐力，从而提高启动速度和移动速度。\\\"}],\\\"Classifications\\\":{\\\"Interview\\\":0.008547919,\\\"Lecture\\\":0.97228867,\\\"Meeting\\\":0.019163456}}\"', '<p><br></p>', '已完成', '2025-07-05 14:37:41', '2025-07-28 11:18:51', 1, 1, 1);
