INSERT INTO `schedule_event` VALUES (142, '2025-04-25', '08:00:00', '早训', '进行基础稳定性练习，重点放在左脚内侧踢球时的腿部控制能力上，特别是模仿视频中30-40秒的动作。', '2025-04-25 00:52:11', '1', 1);
INSERT INTO `schedule_event` VALUES (143, '2025-04-25', '14:00:00', '午训', '加强大腿前侧及小腿后侧肌肉群的力量训练，包括深蹲、提踵等动作，每组15次，共做3组。', '2025-04-25 00:52:11', '1', 1);
INSERT INTO `schedule_event` VALUES (144, '2025-04-25', '19:00:00', '晚训', '重复观看并模仿标准样本视频中的20-30秒与50-60秒片段，专注于提高左脚内侧踢球的精准度，每次连续练习10分钟，休息2分钟后继续。', '2025-04-25 00:52:11', '1', 1);
INSERT INTO `schedule_event` VALUES (145, '2025-04-26', '08:00:00', '早训', '通过跳跃练习增强下肢爆发力，如单腿跳绳或箱跳，左右腿各100次。', '2025-04-25 00:52:11', '1', 1);
INSERT INTO `schedule_event` VALUES (146, '2025-04-26', '14:00:00', '午训', '使用弹力带进行阻力训练以提升腿部肌肉力量和灵活性，特别注意膝盖弯曲状态下对抗弹力带拉伸的动作。', '2025-04-25 00:52:11', '1', 1);
INSERT INTO `schedule_event` VALUES (147, '2025-04-26', '19:00:00', '晚训', '在盘踢过程中加入呼吸调整练习，确保每个动作都配合着均匀稳定的呼吸节奏，尤其是当达到第45-50秒时要更加注重流畅性。', '2025-04-25 00:52:11', '1', 1);
INSERT INTO `schedule_event` VALUES (148, '2025-04-27', '08:00:00', '早训', '实施平衡板上的毽球踢球练习，这有助于改善单脚支撑时的身体重心分布，从而提高整体稳定性。', '2025-04-25 00:52:11', '1', 1);
